# ── Helpers ──────────────────────────────────────────────────
def now_ist():
    return datetime.now(TZ)

def fy_bounds(dt=None):
    dt = dt or now_ist()
    year  = dt.year if dt.month >= 4 else dt.year - 1
    start = datetime(year,   4,  1, tzinfo=TZ)
    end   = datetime(year+1, 3, 31, 23, 59, 59, tzinfo=TZ)
    label = f"FY {year}-{str(year+1)[-2:]}"
    return label, start, end

def prev_fy_label(label):
    m = re.search(r"FY\s*(\d{4})-(\d{2})", label or "")
    if not m: return ""
    y = int(m.group(1)) - 1
    return f"FY {y}-{str(y+1)[-2:]}"

def norm_fy(v):
    s = clean(v, "")
    if not s:
        return ""
    m = re.search(r"(\d{2,4})\s*[-/]\s*(\d{2,4})", s)
    if not m:
        return ""
    y1 = int(m.group(1)); y2 = m.group(2)
    if y1 < 100: y1 += 2000          # 24 -> 2024
    return f"FY {y1}-{str(y1+1)[-2:]}"

def clean(v, default=""):
    if v is None: return default
    s = str(v).strip()
    if s.lower() in ("nan","none","","na","n/a","-"): return default
    return s

def to_num(v):
    # Highly robust number extraction that ignores text/currency like "12 pcs" or "₹1,000"
    if v is None: return 0.0
    if isinstance(v,(int,float)):
        if isinstance(v,float) and (np.isnan(v) or np.isinf(v)): return 0.0
        return float(v)
    s = str(v).strip().lower().replace("−", "-").replace("–", "-")
    if s in ("nan","none","","na","n/a","-","nil","null"): return 0.0
    negative_parentheses = bool(re.fullmatch(r"\s*\(.*\)\s*", s))
    s = s.replace(",", "").replace("\u00a0", " ")
    # Scientific notation and decimal-only values are both valid. Accounting
    # parentheses, e.g. (₹1,250), mean a negative number.
    m = re.search(r"[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:e[-+]?\d+)?", s, re.I)
    try:
        num = float(m.group()) if m else 0.0
        return -abs(num) if negative_parentheses else num
    except: return 0.0

def to_int(v): return int(round(to_num(v)))

def parse_date_any(v):
    if v is None: return None
    if isinstance(v, pd.Timestamp):
        if pd.isna(v): return None
        return v.to_pydatetime().replace(tzinfo=None)
    s = str(v).strip()
    if s.lower() in ("nan","none","","na","n/a","-"): return None

    try:
        fv = float(s)
        if 30000 <= fv <= 60000:
            dt = pd.to_datetime(fv, unit="D", origin="1899-12-30", errors="coerce")
            if not pd.isna(dt): return dt.to_pydatetime().replace(tzinfo=None)
        # Unix seconds/milliseconds occasionally arrive from exports as ints.
        if 1_000_000_000 <= fv <= 4_102_444_800:
            dt = pd.to_datetime(fv, unit="s", errors="coerce")
            if not pd.isna(dt): return dt.to_pydatetime().replace(tzinfo=None)
        if 1_000_000_000_000 <= fv <= 4_102_444_800_000:
            dt = pd.to_datetime(fv, unit="ms", errors="coerce")
            if not pd.isna(dt): return dt.to_pydatetime().replace(tzinfo=None)
    except: pass

    if re.fullmatch(r"\d{8}", s):
        for fmt in ("%Y%m%d", "%d%m%Y"):
            try:
                dt = datetime.strptime(s, fmt)
                if 1900 <= dt.year <= 2100:
                    return dt
            except Exception:
                pass

    m_iso = re.match(r"^(\d{4})[-/](\d{1,2})[-/](\d{1,2})", s)
    if m_iso:
        try:
            y, mo, d = int(m_iso.group(1)), int(m_iso.group(2)), int(m_iso.group(3))
            return datetime(y, mo, d)
        except: pass

    m_dmy = re.match(r"^(\d{1,2})[-/](\d{1,2})[-/](\d{2,4})", s)
    if m_dmy:
        d, mo, y = int(m_dmy.group(1)), int(m_dmy.group(2)), int(m_dmy.group(3))
        if y < 100: y += 2000
        try:
            if 1 <= d <= 31 and 1 <= mo <= 12:
                return datetime(y, mo, d)
        except: pass

    for dayfirst in (True, False):
        try:
            dt = pd.to_datetime(s, errors="coerce", dayfirst=dayfirst)
            if not pd.isna(dt): return dt.to_pydatetime().replace(tzinfo=None)
        except: pass
    return None

def base_sku(s): return str(s).strip().upper().split("_")[0]

# ════════════════════════════════════════════════════════════════
#  🏷️ COSANOSTRAA.COM SKU → PRODUCT NAME
#  cosanostraa.com ek Shopify store hai — uska public /products.json
#  endpoint (koi API key nahi chahiye) saare products + variant SKUs
#  deta hai. Isse SKU -> asli product naam ka map banta hai.
#  Jis SKU ka match cosanostraa.com par mil jaye uska ORIGINAL NAME
#  dikhega; jo SKU wahan nahi hai uska SKU code jaisa hai waisa hi
#  (bina chhede) dikhega.
# ════════════════════════════════════════════════════════════════
CN_STORE_URL = "https://cosanostraa.com"
CN_CATALOG = {"exact": {}, "base": {}, "price_exact": {}, "price_base": {}, "ts": 0.0, "count": 0}
CN_REFRESH_INTERVAL = 6 * 3600  # 6 ghante — catalog kam badalta hai

def _cn_normalize(s):
    return re.sub(r"[\s_]+", "-", str(s or "").strip().upper())

def _cn_base_code(s):
    """'BH-1382-CELB' -> 'BH-1382' jaisa core code nikalta hai taaki
    suffix (-CELB, -SET, wagera) waale variants bhi match ho jaayein."""
    ns = _cn_normalize(s)
    m = re.match(r"^([A-Z]{1,5}-?\d{2,6})", ns)
    if not m:
        return ""
    b = m.group(1)
    if "-" not in b:
        mm = re.match(r"^([A-Za-z]+)(\d.*)$", b)
        if mm:
            b = mm.group(1) + "-" + mm.group(2)
    return b


def _inventory_suffix_candidates(sku):
    """Inventory lookup candidates while preserving the displayed/sales SKU.

    Exact SKU always wins.  If it is absent, a trailing descriptive word such
    as -SHIV / -CELB / -RAKHI / -SET can be ignored ONLY for inventory lookup.
    We deliberately do not strip one-letter endings (P/S/X etc.) because those
    can be real size/variant SKUs elsewhere in the dashboard.
    """
    raw = re.sub(r"\s+", "", str(sku or "").strip().upper())
    if not raw:
        return []
    out = [raw]
    cur = raw
    for _ in range(3):
        if "-" not in cur:
            break
        head, tail = cur.rsplit("-", 1)
        tail = tail.strip().upper()
        # Descriptive suffix must start with a letter and contain >=2 chars.
        # Numeric/body fragments such as the 0159_(B) part are never stripped.
        if not re.fullmatch(r"[A-Z][A-Z0-9_()]{1,}", tail):
            break
        if not head:
            break
        out.append(head)
        cur = head
    return out


def _inventory_resolve_key(sku, mapping_or_keys):
    """Return exact inventory key, else a valid trailing-word fallback key."""
    if mapping_or_keys is None:
        return ""
    for cand in _inventory_suffix_candidates(sku):
        try:
            if cand in mapping_or_keys:
                return cand
        except Exception:
            return ""
    return ""

def _cn_fetch_all_products():
    """cosanostraa.com ke public /products.json se saare products
    (title + variant SKUs) paginate karke khींchta hai. Tight timeouts
    taaki cosanostraa.com slow/unreachable ho to bhi app kabhi atke
    nahi — chahe naam na milein, dashboard ka asli data hamesha turant
    aata rahega."""
    out = []
    headers = {
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
                      "(KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36",
        "Accept": "application/json",
    }
    page = 1
    while page <= 60:   # safety cap (~15,000 products)
        url = f"{CN_STORE_URL}/products.json?limit=250&page={page}"
        try:
            r = requests.get(url, headers=headers, timeout=(5, 12))  # (connect, read) — kabhi hang nahi hoga
            if not r.ok:
                break
            products = (r.json() or {}).get("products") or []
        except Exception as e:
            print("cosanostraa.com catalog fetch failed:", str(e)[:120])
            break
        if not products:
            break
        out.extend(products)
        if len(products) < 250:
            break
        page += 1
    return out

def cn_catalog_is_stale():
    return (time.time() - CN_CATALOG["ts"]) > CN_REFRESH_INTERVAL or CN_CATALOG["count"] == 0

def cn_build_catalog(force=False):
    """SKU -> product name map (re)build karta hai. Sirf background
    thread se call hota hai isliye race condition ka practical risk
    nahi (worst case ek refresh cycle purana data)."""
    if not force and not cn_catalog_is_stale():
        return
    try:
        products = _cn_fetch_all_products()
        exact, base = {}, {}
        price_exact, price_base = {}, {}
        for p in products:
            title = clean(p.get("title", ""))
            if not title:
                continue
            for v in (p.get("variants") or []):
                sku = clean(v.get("sku", ""))
                if not sku:
                    continue
                ns = _cn_normalize(sku)
                website_price = to_num(v.get("price", 0))
                if ns and ns not in exact:
                    exact[ns] = title
                if ns and website_price > 0 and ns not in price_exact:
                    # Shopify variant `price` is the current storefront selling price.
                    price_exact[ns] = round(float(website_price), 2)
                b = _cn_base_code(ns)
                if b and b not in base:
                    base[b] = title
                if b and website_price > 0 and b not in price_base:
                    price_base[b] = round(float(website_price), 2)
        if exact:
            CN_CATALOG["exact"] = exact
            CN_CATALOG["base"] = base
            CN_CATALOG["price_exact"] = price_exact
            CN_CATALOG["price_base"] = price_base
            CN_CATALOG["count"] = len(exact)
        CN_CATALOG["ts"] = time.time()
        print(f"cosanostraa.com catalog loaded: {CN_CATALOG['count']} SKUs")
    except Exception as e:
        print("cosanostraa.com catalog build failed:", str(e)[:160])
        CN_CATALOG["ts"] = time.time()  # avoid hammering on repeated failures

def cn_display_name(sku):
    """SKU ke liye cosanostraa.com ka original product naam. Match nahi
    mila to None (SKU code as-is rehne dena caller ki zimmedari)."""
    if not sku:
        return None
    ns = _cn_normalize(sku)
    name = CN_CATALOG["exact"].get(ns)
    if name:
        return name
    b = _cn_base_code(ns)
    if b:
        return CN_CATALOG["base"].get(b)
    return None

def cn_website_selling_price(sku):
    """SKU ka current cosanostraa.com storefront selling price.
    Exact variant SKU ko priority milti hai; suffix mismatch par base-SKU
    fallback use hota hai. Website price unavailable ho to 0 return hota hai.
    COSA order-history selling price ka koi fallback jaan-bujhkar nahi hai."""
    if not sku:
        return 0.0
    ns = _cn_normalize(sku)
    price = to_num(CN_CATALOG.get("price_exact", {}).get(ns, 0))
    if price > 0:
        return round(float(price), 2)
    b = _cn_base_code(ns)
    if b:
        price = to_num(CN_CATALOG.get("price_base", {}).get(b, 0))
        if price > 0:
            return round(float(price), 2)
    return 0.0


def cn_sku_label(sku):
    """Display label: cosanostraa.com par mila to Product Name, warna
    SKU code bilkul waisa hi jaisa hai."""
    name = cn_display_name(sku)
    return name if name else (str(sku) if sku is not None else "")


def _patch_cn_catalog_into_cached_data():
    """Apply refreshed website catalogue fields without re-downloading sales.

    Previously every catalogue refresh triggered a second full dashboard data
    rebuild. On startup that could make users wait through two expensive syncs.
    The catalogue only affects display name + storefront price, so patch those
    fields in the current compiled snapshot and invalidate role response gzip.
    The normal background sheet refresh still runs on its own schedule.
    """
    if not CACHE.get("data"):
        return False
    changed = False
    try:
        with _DATA_LOCK:
            data = CACHE.get("data")
            if not data or not data[0]:
                return False
            for item in data[0]:
                sku = item.get("sku", "")
                if not sku:
                    continue
                new_name = cn_sku_label(sku)
                new_price = cn_website_selling_price(sku)
                if item.get("sku_name") != new_name:
                    item["sku_name"] = new_name
                    changed = True
                if float(to_num(item.get("website_selling_price", 0))) != float(new_price):
                    item["website_selling_price"] = new_price
                    changed = True
            if changed:
                with _RESP_LOCK:
                    _RESP_CACHE.clear()
    except Exception as e:
        print("CN catalog cache patch failed:", str(e)[:120])
        return False
    return changed

