def _wr_clean_value(v):
    if v is None:
        return ""
    try:
        if pd.isna(v):
            return ""
    except Exception:
        pass
    s = str(v).replace("\u00a0", " ").strip()
    if s.lower() in ("nan", "none", "nat") or s.upper() in ("#N/A", "#N/A!", "#REF!", "#VALUE!", "#DIV/0!"):
        return ""
    return s


def _wr_iso_date(v):
    """Tracker has both 15-Dec-2025 and 1/2/2026 style dates.

    Slash dates in this workbook are month/day/year (e.g. 1/2/2026 = Jan 2),
    so explicit US-style formats are tried before day-first fallbacks.
    """
    s = _wr_clean_value(v)
    if not s:
        return ""
    # Remove a trailing time only for the explicit date formats below; pandas
    # fallback still gets the untouched value for unusual exports.
    fmts = (
        "%d-%b-%Y", "%d-%b-%y", "%m/%d/%Y", "%m/%d/%y",
        "%Y-%m-%d", "%d/%m/%Y", "%d/%m/%y",
        "%d-%m-%Y", "%d-%m-%y", "%m-%d-%Y", "%m-%d-%y",
    )
    candidates = [s]
    m = re.match(r"^(.+?)(?:\s+\d{1,2}:\d{2}(?::\d{2})?.*)$", s)
    if m:
        candidates.append(m.group(1).strip())
    for c in candidates:
        for fmt in fmts:
            try:
                return datetime.strptime(c, fmt).date().isoformat()
            except Exception:
                pass
    try:
        dt = pd.to_datetime(s, errors="coerce", dayfirst=False)
        if not pd.isna(dt):
            return dt.date().isoformat()
    except Exception:
        pass
    try:
        dt = pd.to_datetime(s, errors="coerce", dayfirst=True)
        if not pd.isna(dt):
            return dt.date().isoformat()
    except Exception:
        pass
    return ""


def _wr_num(v):
    s = _wr_clean_value(v).replace(",", "").replace("₹", "").strip()
    if not s:
        return 0.0
    try:
        return float(s)
    except Exception:
        return 0.0


def _wr_col(df, *names, pos=None):
    c = find_col(list(df.columns), *names)
    if c is not None:
        return c
    if isinstance(pos, int) and 0 <= pos < len(df.columns):
        return df.columns[pos]
    return None


def _wr_col_exact(df, *names, pos=None):
    """Resolve a BlueDart column by exact normalized header first.

    This deliberately avoids fuzzy matching `Customer` to `Customer Contact`.
    """
    wanted = {re.sub(r"[^a-z0-9]", "", str(n).casefold()) for n in names if n}
    for c in list(df.columns):
        key = re.sub(r"[^a-z0-9]", "", str(c).casefold())
        if key in wanted:
            return c
    if isinstance(pos, int) and 0 <= pos < len(df.columns):
        return df.columns[pos]
    return None


def _wr_contact_value(v):
    """Keep courier contact numbers readable even when pandas infers numerics."""
    s = _wr_clean_value(v)
    if not s:
        return ""
    if re.fullmatch(r"[+-]?\d+\.0+", s):
        return s.split(".", 1)[0]
    if re.fullmatch(r"[+-]?\d+(?:\.\d+)?[eE][+-]?\d+", s):
        try:
            n = float(s)
            if n.is_integer() and abs(n) < 9_000_000_000_000_000:
                return str(int(n))
        except Exception:
            pass
    return s


def _wr_last_nonblank(old, new):
    nv = _wr_clean_value(new)
    return nv if nv else old


def _wr_read_csv_bytes(content):
    """Parse CSV bytes safely for the Website Returns source fallbacks."""
    try:
        return pd.read_csv(
            io.BytesIO(content), dtype=str, on_bad_lines="skip",
            encoding="utf-8", encoding_errors="replace",
        )
    except TypeError:
        return pd.read_csv(
            io.StringIO(content.decode("utf-8", errors="replace")),
            dtype=str, on_bad_lines="skip",
        )


def _wr_fetch_current_tracker_frame(gid, query, explicit_url="", range_hint="", max_bytes=30 * 1024 * 1024):
    """Fetch a compact current Website Order Tracker view without Google auth.

    We try the direct GViz endpoint, the published GViz endpoint, then bounded CSV
    exports.  The query selects only the columns needed by Website Returns so the
    58k-row New_Uniware sheet does not inflate Railway memory.
    """
    gid = str(gid or "").strip()
    if not gid:
        raise ValueError("tracker gid is blank")
    headers = {
        "Cache-Control": "no-cache, no-store, max-age=0",
        "Pragma": "no-cache",
        "User-Agent": "Mozilla/5.0 (CosaNostraaDashboard WebsiteReturnsTracker)",
        "Accept": "text/csv,text/plain,*/*",
    }
    stamp = str(int(time.time()))
    candidates = []
    if explicit_url:
        candidates.append(("configured URL", explicit_url, {"_": stamp}))
    sid = WEBSITE_ORDER_TRACKER_SPREADSHEET_ID
    pub = WEBSITE_ORDER_TRACKER_PUBLISHED_ID
    if sid:
        candidates.append((
            "direct GViz",
            f"https://docs.google.com/spreadsheets/d/{sid}/gviz/tq",
            {"tqx": "out:csv", "gid": gid, "tq": query, "_": stamp},
        ))
    if pub:
        candidates.append((
            "published GViz",
            f"https://docs.google.com/spreadsheets/d/e/{pub}/gviz/tq",
            {"tqx": "out:csv", "gid": gid, "tq": query, "_": stamp},
        ))
    if sid:
        params = {"format": "csv", "gid": gid, "_": stamp}
        if range_hint:
            params["range"] = range_hint
        candidates.append((
            "direct bounded CSV",
            f"https://docs.google.com/spreadsheets/d/{sid}/export",
            params,
        ))
    if pub:
        params = {"gid": gid, "single": "true", "output": "csv", "_": stamp}
        if range_hint:
            params["range"] = range_hint
        candidates.append((
            "published bounded CSV",
            f"https://docs.google.com/spreadsheets/d/e/{pub}/pub",
            params,
        ))

    errors = []
    for label, url, params in candidates:
        try:
            r = requests.get(url, params=params, headers=headers, timeout=(8, 55), allow_redirects=True)
            r.raise_for_status()
            content = r.content
            if len(content) > max_bytes:
                raise ValueError(f"response too large ({len(content)} bytes)")
            head = content[:800].decode("utf-8", errors="replace").lower()
            if "<html" in head or "accounts.google.com" in str(r.url).lower():
                raise ValueError("received HTML/login page instead of CSV")
            frame = _wr_read_csv_bytes(content)
            if frame is None or frame.empty:
                raise ValueError("CSV is empty")
            frame.columns = [str(c).strip() for c in frame.columns]
            return frame, label
        except Exception as e:
            errors.append(f"{label}: {e}")
    raise RuntimeError("Website Order Tracker fetch failed; " + " | ".join(errors[-4:]))


def _wr_tracker_reason(entry):
    if not entry:
        return ""
    return _wr_clean_value(entry.get("return_reason")) or _wr_clean_value(entry.get("reverse_pickup_reason"))


def _wr_load_tracker_enrichment(force=False):
    """Return Display Order Code -> contact + return/RTO enrichment.

    Verified live layout:
      New_Uniware: B Display Order Code, E Reverse Pickup Reason,
                    F Notification Email, G Notification Mobile, I COD.
      RETURN &RTO: A Display Order Code, D Billing Address Name, H New SKU,
                    AB Return type, AC RTO Qty, AD Return Date, AE Return Reason,
                    AF SKU No., AG Channel/Name, AI State.
    """
    now = time.time()
    cached = _WEBSITE_TRACKER_ENRICH_CACHE.get("data")
    if (not force and cached is not None
            and now - float(_WEBSITE_TRACKER_ENRICH_CACHE.get("ts") or 0) < _WEBSITE_TRACKER_ENRICH_TTL):
        return cached, dict(_WEBSITE_TRACKER_ENRICH_CACHE.get("meta") or {})

    out = {}
    meta = {
        "uniware_rows": 0, "return_rto_rows": 0,
        "contact_orders": 0, "reason_orders": 0, "return_orders": 0,
        "uniware_source": "", "return_rto_source": "", "warnings": [],
    }

    # Compact New_Uniware view: one row per item, deduped below to one order.
    try:
        q = "select B,E,F,G,I where B is not null"
        udf, src = _wr_fetch_current_tracker_frame(
            WEBSITE_UNIWARE_GID, q, WEBSITE_UNIWARE_LIVE_URL,
            range_hint="B:I", max_bytes=28 * 1024 * 1024,
        )
        meta["uniware_source"] = src
        meta["uniware_rows"] = int(len(udf))
        c_order = _wr_col_exact(udf, "Display Order Code", pos=0)
        c_reverse = _wr_col_exact(udf, "Reverse Pickup Reason", pos=1)
        c_email = _wr_col_exact(udf, "Notification Email", pos=2)
        c_mobile = _wr_col_exact(udf, "Notification Mobile", pos=3)
        c_cod = _wr_col_exact(udf, "COD", pos=4)
        for _, raw in udf.iterrows():
            key = _daily_reporting_order_key(raw.get(c_order, "")) if c_order is not None else ""
            if not key:
                continue
            rec = out.setdefault(key, {
                "order_id": key, "contacts": [], "emails": [], "reverse_reasons": [],
                "return_types": [], "return_dates": [], "return_reasons": [], "skus": [],
                "customers": [], "states": [], "rto_qty": 0.0, "payment_modes": [],
                "has_return": False,
            })
            contact = _wr_contact_value(raw.get(c_mobile, "")) if c_mobile is not None else ""
            email = _wr_clean_value(raw.get(c_email, "")) if c_email is not None else ""
            reverse = _wr_clean_value(raw.get(c_reverse, "")) if c_reverse is not None else ""
            if contact: rec["contacts"].append(contact)
            if email: rec["emails"].append(email)
            if reverse:
                rec["reverse_reasons"].append(reverse)
                rec["has_return"] = True
            if c_cod is not None:
                pm = _wr_website_payment_mode(raw.get(c_cod, ""))
                if pm in ("COD", "Prepaid"): rec["payment_modes"].append(pm)
    except Exception as e:
        meta["warnings"].append("New_Uniware unavailable: " + str(e)[:220])

    # Compact RETURN & RTO view. This is the live return-field authority.
    try:
        q = "select A,D,H,AB,AC,AD,AE,AF,AG,AI where A is not null"
        rdf, src = _wr_fetch_current_tracker_frame(
            WEBSITE_RETURN_RTO_GID, q, WEBSITE_RETURN_RTO_LIVE_URL,
            range_hint="A:AI", max_bytes=24 * 1024 * 1024,
        )
        meta["return_rto_source"] = src
        meta["return_rto_rows"] = int(len(rdf))
        c_order = _wr_col_exact(rdf, "Display Order Code", pos=0)
        c_customer = _wr_col_exact(rdf, "Billing Address Name", pos=1)
        c_new_sku = _wr_col_exact(rdf, "New SKU", pos=2)
        c_type = _wr_col_exact(rdf, "Return type", "Return Type", pos=3)
        c_qty = _wr_col_exact(rdf, "RTO Qty", "Return Qty", pos=4)
        c_date = _wr_col_exact(rdf, "Return Date", pos=5)
        c_reason = _wr_col_exact(rdf, "Return Reason", "RTO Reason", pos=6)
        c_sku = _wr_col_exact(rdf, "SKU No.", "SKU No", "SKU", pos=7)
        c_name2 = _wr_col_exact(rdf, "Channel/Name", pos=8)
        c_state = _wr_col_exact(rdf, "State", pos=9)
        for _, raw in rdf.iterrows():
            key = _daily_reporting_order_key(raw.get(c_order, "")) if c_order is not None else ""
            if not key:
                continue
            rec = out.setdefault(key, {
                "order_id": key, "contacts": [], "emails": [], "reverse_reasons": [],
                "return_types": [], "return_dates": [], "return_reasons": [], "skus": [],
                "customers": [], "states": [], "rto_qty": 0.0, "payment_modes": [],
                "has_return": False,
            })
            rt = _wr_clean_value(raw.get(c_type, "")) if c_type is not None else ""
            rq = max(0.0, to_num(raw.get(c_qty, 0))) if c_qty is not None else 0.0
            rd = _wr_iso_date(raw.get(c_date, "")) if c_date is not None else ""
            rr = _wr_clean_value(raw.get(c_reason, "")) if c_reason is not None else ""
            cust = _wr_clean_value(raw.get(c_customer, "")) if c_customer is not None else ""
            cust2 = _wr_clean_value(raw.get(c_name2, "")) if c_name2 is not None else ""
            state = _wr_clean_value(raw.get(c_state, "")) if c_state is not None else ""
            for col in (c_new_sku, c_sku):
                sv = _wr_clean_value(raw.get(col, "")).upper() if col is not None else ""
                if sv: rec["skus"].append(sv)
            if rt: rec["return_types"].append(rt)
            if rd: rec["return_dates"].append(rd)
            if rr: rec["return_reasons"].append(rr)
            if cust: rec["customers"].append(cust)
            elif cust2: rec["customers"].append(cust2)
            if state: rec["states"].append(state)
            rec["rto_qty"] += rq
            if rt or rq > 0 or rd or rr:
                rec["has_return"] = True
    except Exception as e:
        meta["warnings"].append("RETURN & RTO unavailable: " + str(e)[:220])

    # Finalize compact values. COD wins only if duplicate item rows disagree.
    for key, rec in out.items():
        rec["customer_contact"] = _wr_unique_join(rec.pop("contacts", []), ", ")
        rec["customer_email"] = _wr_unique_join(rec.pop("emails", []), ", ")
        rec["reverse_pickup_reason"] = _wr_unique_join(rec.pop("reverse_reasons", []))
        rec["return_type"] = _wr_unique_join(rec.pop("return_types", []))
        dates = sorted({x for x in rec.pop("return_dates", []) if x})
        rec["return_date"] = dates[-1] if dates else ""
        rec["return_reason"] = _wr_unique_join(rec.pop("return_reasons", []))
        rec["sku_text"] = ", ".join(sorted({x for x in rec.pop("skus", []) if x}))
        rec["customer"] = _wr_unique_join(rec.pop("customers", []))
        rec["state"] = _wr_unique_join(rec.pop("states", []), ", ")
        pms = rec.pop("payment_modes", [])
        rec["payment_mode"] = "COD" if "COD" in pms else ("Prepaid" if "Prepaid" in pms else "Unclassified")
        rec["reason"] = _wr_tracker_reason(rec)

    meta["contact_orders"] = sum(1 for r in out.values() if r.get("customer_contact"))
    meta["reason_orders"] = sum(1 for r in out.values() if r.get("reason"))
    meta["return_orders"] = sum(1 for r in out.values() if r.get("has_return"))
    _WEBSITE_TRACKER_ENRICH_CACHE.update({
        "data": out, "ts": time.time(), "meta": meta,
        "error": " | ".join(meta.get("warnings") or []),
    })
    return out, dict(meta)


def _wr_enrich_return_row_from_tracker(rec, tracker_map):
    """Fill missing return row fields by exact Website Display Order Code."""
    if not rec:
        return rec
    key = ""
    for raw in (rec.get("display_order_code", ""), rec.get("order_id", "")):
        key = _daily_reporting_order_key(raw)
        if key and key in tracker_map:
            break
    t = tracker_map.get(key) if key else None
    if not t:
        return rec
    if not rec.get("display_order_code"): rec["display_order_code"] = key
    if not rec.get("order_id"): rec["order_id"] = key
    if not rec.get("customer") and t.get("customer"): rec["customer"] = t["customer"]
    if not rec.get("consignee") and t.get("customer"): rec["consignee"] = t["customer"]
    if not rec.get("customer_contact") and t.get("customer_contact"):
        rec["customer_contact"] = t["customer_contact"]
        rec["customer_contact_source"] = "New_Uniware Notification Mobile"
    if t.get("customer_email"):
        rec["customer_email"] = t["customer_email"]
    reason = _wr_tracker_reason(t)
    if not rec.get("rto_reason") and reason:
        rec["rto_reason"] = reason
        rec["rto_reason_source"] = "RETURN & RTO Return Reason" if t.get("return_reason") else "New_Uniware Reverse Pickup Reason"
    if not rec.get("status_description") and t.get("return_type"):
        rec["status_description"] = t["return_type"]
    if not rec.get("status_group") and t.get("return_type"):
        rec["status_group"] = t["return_type"]
    if not rec.get("status_date") and t.get("return_date"):
        rec["status_date"] = t["return_date"]
    if not rec.get("destination") and t.get("state"):
        rec["destination"] = t["state"]
    if not rec.get("mode") and t.get("payment_mode") in ("COD", "Prepaid"):
        rec["mode"] = t["payment_mode"]
    if not rec.get("sku_text_fallback") and t.get("sku_text"):
        rec["sku_text_fallback"] = t["sku_text"]
    return rec


def _wr_fetch_bluedart_source():
    """Fetch BlueDart robustly.

    The normal shared CSV loader adds a cache-busting query parameter. Google
    occasionally redirects older published-sheet URLs to a googleusercontent
    endpoint that rejects that redirected request with HTTP 400. For this one
    operational feed, retry the exact published URL (and a normalized variant)
    without the extra query parameter before declaring the courier feed down.
    """
    errors = []
    try:
        return _fetch_csv_fresh(WEBSITE_RETURNS_URL)
    except Exception as e:
        errors.append(f"cache-busted fetch: {e}")

    candidates = [WEBSITE_RETURNS_URL]
    # Older Google publish links do not need single=true. Some redirected export
    # endpoints are stricter about extra query parameters, so try the equivalent
    # URL without it as well.
    if "single=true" in WEBSITE_RETURNS_URL:
        clean = re.sub(r"([?&])single=true(?:&|$)", r"\1", WEBSITE_RETURNS_URL, flags=re.I)
        clean = clean.replace("?&", "?").rstrip("?&")
        if clean and clean not in candidates:
            candidates.append(clean)

    headers = {
        "Cache-Control": "no-cache, no-store, max-age=0",
        "Pragma": "no-cache",
        "User-Agent": "Mozilla/5.0 (CosaNostraaDashboard WebsiteReturns)",
        "Accept": "text/csv,text/plain,*/*",
    }
    for url in candidates:
        try:
            r = requests.get(url, headers=headers, timeout=(8, 45), allow_redirects=True)
            r.raise_for_status()
            content = r.content
            head = content[:512].decode("utf-8", errors="replace").lower()
            if "<html" in head:
                raise ValueError("received HTML instead of CSV")
            frame = _wr_read_csv_bytes(content)
            if frame is None or frame.empty:
                raise ValueError("CSV is empty")
            return frame
        except Exception as e:
            errors.append(f"direct fetch: {e}")
    raise RuntimeError("BlueDart published CSV unavailable; " + " | ".join(errors[-3:]))


def _wr_load_website_sheet_fallback(force=False):
    """Build Website-return rows from the live Website sheet itself.

    This is a safety net only for periods when the separate BlueDart published
    export is unavailable. It uses the Website sheet's own Return type, RTO Qty,
    Return Date and Return Reason fields, so the Website Returns tab remains
    usable instead of failing completely. It deliberately does *not* pretend
    these rows are BlueDart courier events.
    """
    df = None
    if not force:
        try:
            cached_df = _DF_REFS.get("website_repeat")
            if cached_df is not None and not cached_df.empty:
                df = cached_df
        except Exception:
            df = None
    if df is None:
        df = _fetch_csv_fresh(RAKHI_WEBSITE_ADDR_URL)
    if df is None or df.empty:
        raise ValueError("Website return/RTO fallback sheet is empty")

    cols = list(df.columns)
    def _at(i):
        return cols[i] if 0 <= i < len(cols) else None

    c_order = _wr_col_exact(df, "Display Order Code", pos=0)
    c_name = _wr_col_exact(df, "Billing Address Name", "Customer Name", pos=3)
    c_status = _wr_col_exact(df, "Sale Order Status", "Order Status", pos=6)
    c_sku = _wr_col_exact(df, "New SKU", "SKU", pos=7)
    c_package = _wr_col_exact(df, "Shipping Package Code", pos=8)
    c_invoice = _wr_col_exact(df, "Invoice Code", pos=9)
    c_created = _wr_col_exact(df, "Created", pos=10)
    c_city = _wr_col_exact(df, "Billing Address City", "City", pos=11)
    c_cod = _wr_col_exact(df, "COD", pos=12)
    c_state = _wr_col_exact(df, "Billing Address State", "State", pos=13)
    c_total = _wr_col_exact(df, "Total Price", pos=18)
    c_qty = _wr_col_exact(df, "Qty", "Quantity", pos=21)
    c_order_date = _wr_col_exact(df, "Order_Date", "Order Date", pos=22)
    c_return_type = _wr_col_exact(df, "Return type", "Return Type", pos=26) or _at(26)
    c_rto_qty = _wr_col_exact(df, "RTO Qty", "Return Qty", pos=27) or _at(27)
    c_return_date = _wr_col_exact(df, "Return Date", pos=28) or _at(28)
    c_return_reason = _wr_col_exact(df, "Return Reason", "RTO Reason", pos=29) or _at(29)

    grouped = {}
    source_rows = 0
    for _, raw in df.iterrows():
        order_key = _daily_reporting_order_key(raw.get(c_order, "")) if c_order is not None else ""
        if not order_key:
            continue
        status = _wr_clean_value(raw.get(c_status, "")) if c_status is not None else ""
        status_l = status.casefold()
        if status_l and any(x in status_l for x in ("cancel", "void", "failed")):
            continue
        rto_qty = max(0.0, to_num(raw.get(c_rto_qty, 0))) if c_rto_qty is not None else 0.0
        return_type = _wr_clean_value(raw.get(c_return_type, "")) if c_return_type is not None else ""
        return_date = _wr_iso_date(raw.get(c_return_date, "")) if c_return_date is not None else ""
        return_reason = _wr_clean_value(raw.get(c_return_reason, "")) if c_return_reason is not None else ""
        is_return = bool(
            rto_qty > 0 or return_type or return_date or return_reason
            or any(x in status_l for x in ("return", "rto", "refund"))
        )
        if not is_return:
            continue
        source_rows += 1
        order_date = _wr_iso_date(raw.get(c_order_date, "")) if c_order_date is not None else ""
        if not order_date and c_created is not None:
            order_date = _wr_iso_date(raw.get(c_created, ""))
        customer = _wr_clean_value(raw.get(c_name, "")) if c_name is not None else ""
        city = _wr_clean_value(raw.get(c_city, "")) if c_city is not None else ""
        state = _wr_clean_value(raw.get(c_state, "")) if c_state is not None else ""
        destination = ", ".join([x for x in (city, state) if x])
        sku = _wr_clean_value(raw.get(c_sku, "")).upper() if c_sku is not None else ""
        package = _wr_clean_value(raw.get(c_package, "")) if c_package is not None else ""
        invoice = _wr_clean_value(raw.get(c_invoice, "")) if c_invoice is not None else ""
        amount = _wr_clean_value(raw.get(c_total, "")) if c_total is not None else ""
        pay_mode = _wr_website_payment_mode(raw.get(c_cod, "")) if c_cod is not None else "Unclassified"

        rec = grouped.get(order_key)
        if rec is None:
            rec = {
                "channel": "Website", "order_date": order_date, "customer": customer,
                "customer_contact": "", "display_order_code": order_key, "order_id": order_key,
                "payment": amount, "waybill_no": "", "reference_no": invoice,
                "pickup_date": "", "origin": "", "destination": destination,
                "consignee": customer, "status_description": return_type or "Website Return / RTO",
                "status_group": return_type or "Return/RTO", "status_date": return_date,
                "rto_reason": return_reason, "weight": "", "pcs": str(rto_qty or ""),
                "expected_delivery_date": "", "new_waybill_no": "", "sender": "",
                "mode": pay_mode, "source_kind": "website_sheet_fallback",
                "_skus_fallback": [], "_packages_fallback": [], "_invoices_fallback": [],
                "_types_fallback": [], "_reasons_fallback": [], "_dates_fallback": [],
                "_destinations_fallback": [], "_rto_qty_fallback": 0.0,
            }
            grouped[order_key] = rec
        elif order_date and (not rec.get("order_date") or order_date < rec.get("order_date")):
            rec["order_date"] = order_date
        if not rec.get("customer") and customer:
            rec["customer"] = customer
            rec["consignee"] = customer
        if not rec.get("payment") and amount:
            rec["payment"] = amount
        if sku: rec["_skus_fallback"].append(sku)
        if package: rec["_packages_fallback"].append(package)
        if invoice: rec["_invoices_fallback"].append(invoice)
        if return_type: rec["_types_fallback"].append(return_type)
        if return_reason: rec["_reasons_fallback"].append(return_reason)
        if return_date: rec["_dates_fallback"].append(return_date)
        if destination: rec["_destinations_fallback"].append(destination)
        rec["_rto_qty_fallback"] += rto_qty

    rows = []
    for rec in grouped.values():
        types = rec.pop("_types_fallback", [])
        reasons = rec.pop("_reasons_fallback", [])
        dates = sorted({x for x in rec.pop("_dates_fallback", []) if x})
        destinations = rec.pop("_destinations_fallback", [])
        invoices = rec.pop("_invoices_fallback", [])
        packages = rec.pop("_packages_fallback", [])
        skus = sorted({x for x in rec.pop("_skus_fallback", []) if x})
        rto_total = rec.pop("_rto_qty_fallback", 0.0)
        if types:
            rec["status_group"] = _wr_unique_join(types)
            rec["status_description"] = _wr_unique_join(types)
        rec["rto_reason"] = _wr_unique_join(reasons) or rec.get("rto_reason", "")
        rec["status_date"] = dates[-1] if dates else rec.get("status_date", "")
        rec["destination"] = _wr_unique_join(destinations, ", ") or rec.get("destination", "")
        rec["reference_no"] = _wr_unique_join(invoices, ", ") or rec.get("reference_no", "")
        rec["sku_text_fallback"] = ", ".join(skus)
        rec["package_text_fallback"] = ", ".join(sorted({x for x in packages if x}))
        rec["pcs"] = str(int(rto_total)) if float(rto_total).is_integer() and rto_total else (str(rto_total) if rto_total else rec.get("pcs", ""))
        rows.append(rec)

    # Enrich Website fallback with the current Order Tracker. New_Uniware supplies
    # Notification Mobile; RETURN & RTO supplies return fields. Also include a
    # tracker return that is not yet mirrored into the Mayuresh Website sheet.
    tracker_map, tracker_meta = _wr_load_tracker_enrichment(force=force)
    existing = {}
    for rec in rows:
        _wr_enrich_return_row_from_tracker(rec, tracker_map)
        key = _daily_reporting_order_key(rec.get("display_order_code") or rec.get("order_id"))
        if key: existing[key] = rec
    for key, t in tracker_map.items():
        if key in existing or not t.get("has_return"):
            continue
        reason = _wr_tracker_reason(t)
        rto_qty = max(0.0, to_num(t.get("rto_qty", 0)))
        rec = {
            "channel": "Website", "order_date": "", "customer": t.get("customer", ""),
            "customer_contact": t.get("customer_contact", ""),
            "customer_email": t.get("customer_email", ""),
            "display_order_code": key, "order_id": key, "payment": "",
            "waybill_no": "", "reference_no": "", "pickup_date": "", "origin": "",
            "destination": t.get("state", ""), "consignee": t.get("customer", ""),
            "status_description": t.get("return_type", "") or "Website Return / RTO",
            "status_group": t.get("return_type", "") or "Return/RTO",
            "status_date": t.get("return_date", ""), "rto_reason": reason,
            "weight": "", "pcs": str(int(rto_qty)) if rto_qty and float(rto_qty).is_integer() else (str(rto_qty) if rto_qty else ""),
            "expected_delivery_date": "", "new_waybill_no": "", "sender": "",
            "mode": t.get("payment_mode", ""), "source_kind": "website_tracker_fallback",
            "sku_text_fallback": t.get("sku_text", ""),
            "customer_contact_source": "New_Uniware Notification Mobile" if t.get("customer_contact") else "",
            "rto_reason_source": ("RETURN & RTO Return Reason" if t.get("return_reason") else ("New_Uniware Reverse Pickup Reason" if t.get("reverse_pickup_reason") else "")),
        }
        rows.append(rec)

    rows.sort(key=lambda r: (r.get("status_date") or r.get("order_date") or "", r.get("order_id") or ""), reverse=True)
    return rows, {
        "source_rows": source_rows,
        "sheet_data_rows": int(len(df)),
        "ignored_non_website_rows": 0,
        "tracker_contact_orders": int(tracker_meta.get("contact_orders") or 0),
        "tracker_reason_orders": int(tracker_meta.get("reason_orders") or 0),
        "tracker_return_orders": int(tracker_meta.get("return_orders") or 0),
        "tracker_warnings": list(tracker_meta.get("warnings") or []),
    }


def _load_website_returns(force=False):
    now = time.time()
    if (not force and _WEBSITE_RETURNS_CACHE.get("rows") is not None
            and now - float(_WEBSITE_RETURNS_CACHE.get("ts") or 0) < _WEBSITE_RETURNS_TTL):
        return _WEBSITE_RETURNS_CACHE["rows"]
    try:
        # Verified 24-Aug-2026 source: "bluedart report" -> "Bluedart return"
        # (gid 1316634902), 34 columns A:AH. Read the full published CSV and use
        # exact headers first; positions are only safety fallbacks.
        df = _wr_fetch_bluedart_source()
        if df is None or df.empty:
            raise ValueError("Bluedart return sheet is empty")
        cols = list(df.columns)
        _required_bd_headers = {
            "Channel", "Order date", "Customer Contact", "Display Order Code",
            "Order id", "Payment", "WayBill No", "P/U_Date",
            "Destination Description", "Consignee Name", "Status Description",
            "Status Group", "Status Date", "Rto Reason", "Mode",
        }
        _present_bd_headers = {str(c).strip() for c in cols}
        _missing_bd_headers = sorted(_required_bd_headers - _present_bd_headers)
        if _missing_bd_headers:
            raise ValueError(
                "Bluedart return source header mismatch; missing: "
                + ", ".join(_missing_bd_headers)
            )
        c_channel = _wr_col_exact(df, "Channel", pos=0)
        c_order_date = _wr_col_exact(df, "Order date", "Order Date", pos=1)
        # Current BlueDart layout has Customer Contact in physical column C.
        # Customer name is Consignee Name (L) unless an older explicit Customer/
        # Coustomer column exists. Exact matching prevents contact numbers from
        # being mistaken for customer names.
        c_contact = _wr_col_exact(
            df, "Customer Contact", "Customer Contact No", "Customer Contact Number",
            "Contact No", "Contact Number", "Mobile No", "Mobile Number", "Phone",
            pos=2,
        )
        c_customer = _wr_col_exact(df, "Coustomer", "Customer", "Customer Name", "Buyer Name")
        c_display_order = _wr_col_exact(df, "Display Order Code", pos=3)
        c_order_id = _wr_col_exact(df, "Order id", "Order ID", pos=4)
        c_payment = _wr_col_exact(df, "Payment", pos=5)
        c_waybill = _wr_col_exact(df, "WayBill No", "Waybill No", "Way Bill No", pos=6)
        c_ref = _wr_col_exact(df, "Reference No", "Reference Number", pos=7)
        c_pickup = _wr_col_exact(df, "P/U_Date", "P/U Date", "Pickup Date", pos=8)
        c_origin = _wr_col_exact(df, "Origin Description", pos=9)
        c_dest = _wr_col_exact(df, "Destination Description", pos=10)
        c_consignee = _wr_col_exact(df, "Consignee Name", pos=11)
        c_status_desc = _wr_col_exact(df, "Status Description", pos=12)
        c_status_group = _wr_col_exact(df, "Status Group", pos=13)
        c_status_date = _wr_col_exact(df, "Status Date", pos=14)
        c_weight = _wr_col(df, "Weight", pos=22)
        c_pcs = _wr_col(df, "Pcs", "PCS", pos=24)
        c_exp = _wr_col(df, "Exp Delivery Dat", "Exp Delivery Date", "Expected Delivery Date", pos=25)
        c_new_waybill = _wr_col(df, "New Waybill No", "New WayBill No", pos=27)
        c_sender = _wr_col(df, "Sender", pos=28)
        c_reason = _wr_col_exact(df, "Rto Reason", "RTO Reason", pos=29)
        c_mode = _wr_col(df, "Mode", pos=32)

        # Pandas has already consumed the header row, so len(df) is the number
        # of source data rows.  The published BlueDart Return sheet also contains
        # non-Website formula/error rows (currently labelled Designer); those are
        # not Website returns and must not inflate the operational return count.
        sheet_data_rows = int(len(df))
        source_rows = 0
        ignored_non_website_rows = 0
        shipments = {}
        for _, raw in df.iterrows():
            channel = _wr_clean_value(raw.get(c_channel, "")) if c_channel is not None else ""
            if channel.strip().casefold() != "website":
                ignored_non_website_rows += 1
                continue
            order_id = _wr_clean_value(raw.get(c_order_id, "")) if c_order_id is not None else ""
            waybill = _wr_clean_value(raw.get(c_waybill, "")) if c_waybill is not None else ""
            # Empty tracker lines are not records. WayBill is the shipment-level
            # identifier; Order ID is a fallback only when courier waybill is blank.
            if not waybill and not order_id:
                continue
            source_rows += 1
            key_raw = waybill or ("ORDER:" + order_id)
            key = re.sub(r"[^a-z0-9]", "", key_raw.casefold()) or key_raw.casefold()
            source_customer = _wr_clean_value(raw.get(c_customer, "")) if c_customer is not None else ""
            customer_contact = _wr_contact_value(raw.get(c_contact, "")) if c_contact is not None else ""
            consignee_name = _wr_clean_value(raw.get(c_consignee, "")) if c_consignee is not None else ""
            rec = {
                "channel": channel or "Website",
                "order_date": _wr_iso_date(raw.get(c_order_date, "")) if c_order_date is not None else "",
                # Current tracker keeps the customer name in Consignee Name and
                # the phone/mobile separately in Customer Contact.
                "customer": source_customer or consignee_name,
                "customer_contact": customer_contact,
                "display_order_code": _wr_clean_value(raw.get(c_display_order, "")) if c_display_order is not None else "",
                "order_id": order_id,
                "payment": _wr_clean_value(raw.get(c_payment, "")) if c_payment is not None else "",
                "waybill_no": waybill,
                "reference_no": _wr_clean_value(raw.get(c_ref, "")) if c_ref is not None else "",
                "pickup_date": _wr_iso_date(raw.get(c_pickup, "")) if c_pickup is not None else "",
                "origin": _wr_clean_value(raw.get(c_origin, "")) if c_origin is not None else "",
                "destination": _wr_clean_value(raw.get(c_dest, "")) if c_dest is not None else "",
                "consignee": consignee_name,
                "status_description": _wr_clean_value(raw.get(c_status_desc, "")) if c_status_desc is not None else "",
                "status_group": _wr_clean_value(raw.get(c_status_group, "")) if c_status_group is not None else "",
                "status_date": _wr_iso_date(raw.get(c_status_date, "")) if c_status_date is not None else "",
                "rto_reason": _wr_clean_value(raw.get(c_reason, "")) if c_reason is not None else "",
                "weight": _wr_clean_value(raw.get(c_weight, "")) if c_weight is not None else "",
                "pcs": _wr_clean_value(raw.get(c_pcs, "")) if c_pcs is not None else "",
                "expected_delivery_date": _wr_iso_date(raw.get(c_exp, "")) if c_exp is not None else "",
                "new_waybill_no": _wr_clean_value(raw.get(c_new_waybill, "")) if c_new_waybill is not None else "",
                "sender": _wr_clean_value(raw.get(c_sender, "")) if c_sender is not None else "",
                "mode": _wr_clean_value(raw.get(c_mode, "")) if c_mode is not None else "",
            }
            old = shipments.get(key)
            if old is None:
                shipments[key] = rec
            else:
                # The tracker can repeat a shipment as its status is updated. Keep
                # the latest dated status while retaining useful nonblank fields
                # (especially RTO Reason) from earlier duplicate lines.
                old_status = old.get("status_date") or ""
                new_status = rec.get("status_date") or ""
                prefer_new = bool(new_status and (not old_status or new_status >= old_status))
                merged = dict(old)
                for field in rec:
                    if rec[field] and (prefer_new or not merged.get(field)):
                        merged[field] = rec[field]
                # Always retain a captured reason if the newest event has no reason.
                if not rec.get("rto_reason") and old.get("rto_reason"):
                    merged["rto_reason"] = old["rto_reason"]
                shipments[key] = merged

        rows = list(shipments.values())
        # Even when BlueDart works, fill blank contact/reason from the current
        # Website Order Tracker by exact Display Order Code.
        tracker_map, tracker_meta = _wr_load_tracker_enrichment(force=force)
        for rec in rows:
            _wr_enrich_return_row_from_tracker(rec, tracker_map)
        rows.sort(key=lambda r: (r.get("status_date") or r.get("order_date") or "", r.get("order_id") or ""), reverse=True)
        _WEBSITE_RETURNS_CACHE.update({
            "rows": rows,
            "ts": now,
            "source_rows": source_rows,
            "sheet_data_rows": sheet_data_rows,
            "ignored_non_website_rows": ignored_non_website_rows,
            "error": None,
            "source": "bluedart report · Bluedart return (gid 1316634902) + current Website Order Tracker enrichment",
            "source_kind": "bluedart",
            "source_warning": " | ".join(tracker_meta.get("warnings") or []),
            "tracker_contact_orders": int(tracker_meta.get("contact_orders") or 0),
            "tracker_reason_orders": int(tracker_meta.get("reason_orders") or 0),
            "tracker_return_orders": int(tracker_meta.get("return_orders") or 0),
        })
        return rows
    except Exception as e:
        primary_error = str(e)
        _WEBSITE_RETURNS_CACHE["error"] = primary_error
        # The BlueDart published export can occasionally return HTTP 400 after a
        # Google redirect. Do not take the whole Website Returns dashboard down:
        # fall back to the Website sheet's own live return/RTO fields.
        try:
            fallback_rows, meta = _wr_load_website_sheet_fallback(force=force)
            _WEBSITE_RETURNS_CACHE.update({
                "rows": fallback_rows,
                "ts": now,
                "source_rows": int(meta.get("source_rows") or 0),
                "sheet_data_rows": int(meta.get("sheet_data_rows") or 0),
                "ignored_non_website_rows": int(meta.get("ignored_non_website_rows") or 0),
                "error": None,
                "source": "Website + RETURN & RTO + New_Uniware fallback",
                "source_kind": "website_tracker_fallback",
                "source_warning": "BlueDart public export unavailable; using Website return fields plus current RETURN & RTO and New_Uniware contact mapping." + ((" | " + " | ".join(meta.get("tracker_warnings") or [])) if meta.get("tracker_warnings") else ""),
                "tracker_contact_orders": int(meta.get("tracker_contact_orders") or 0),
                "tracker_reason_orders": int(meta.get("tracker_reason_orders") or 0),
                "tracker_return_orders": int(meta.get("tracker_return_orders") or 0),
            })
            return fallback_rows
        except Exception as fallback_error:
            # Last resort: if a previous successful snapshot exists, keep the tab
            # usable rather than replacing good data with an error screen.
            if _WEBSITE_RETURNS_CACHE.get("rows") is not None:
                return _WEBSITE_RETURNS_CACHE["rows"]
            raise RuntimeError(
                "BlueDart source unavailable and Website fallback failed: "
                + primary_error[:220] + " | " + str(fallback_error)[:220]
            )



def _wr_unique_join(values, sep=" | "):
    out = []
    seen = set()
    for value in values or []:
        text = _wr_clean_value(value)
        key = text.casefold()
        if text and key not in seen:
            seen.add(key)
            out.append(text)
    return sep.join(out)


def _wr_website_payment_mode(value):
    raw = str(value or "").strip().casefold()
    if raw in ("1", "1.0", "cod", "cash on delivery", "cash-on-delivery", "true", "yes"):
        return "COD"
    if raw in ("0", "0.0", "prepaid", "pre-paid", "false", "no"):
        return "Prepaid"
    return "Unclassified"


def _load_website_order_audit(force=False):
    """Build a Website Display-Order-level index and merge BlueDart returns.

    The large Website sheet stays on the server. One order is one physical
    column-A Display Order Code. Website return fields (Return type, RTO Qty,
    Return Date, Return Reason) are OR/aggregated across all lines in that order.
    BlueDart rows are then joined to the same order ID, so the dashboard can show
    a true denominator (all Website orders) and a deduplicated return numerator.
    """
    now = time.time()
    if (not force and _WEBSITE_ORDER_AUDIT_CACHE.get("orders") is not None
            and now - float(_WEBSITE_ORDER_AUDIT_CACHE.get("ts") or 0) < _WEBSITE_ORDER_AUDIT_TTL):
        return _WEBSITE_ORDER_AUDIT_CACHE["orders"]

    try:
        # Reuse the already-loaded Website dataframe when possible. A manual
        # Website Returns refresh forces a direct fresh CSV read instead.
        df = None
        if not force:
            try:
                cached_df = _DF_REFS.get("website_repeat")
                if cached_df is not None and not cached_df.empty:
                    df = cached_df
            except Exception:
                df = None
        if df is None:
            df = _fetch_csv_fresh(RAKHI_WEBSITE_ADDR_URL)
        if df is None or df.empty:
            raise ValueError("Website sales sheet is empty")

        cols = list(df.columns)
        def _at(i):
            return cols[i] if 0 <= i < len(cols) else None

        c_order = _wr_col_exact(df, "Display Order Code", pos=0)
        c_pin = _wr_col_exact(df, "Shipping Address Pincode", "Shipping Pincode", pos=2)
        c_name = _wr_col_exact(df, "Billing Address Name", "Customer Name", pos=3)
        c_addr = _wr_col_exact(df, "Final Billing Address", "Billing Address", pos=4)
        c_status = _wr_col_exact(df, "Sale Order Status", "Order Status", pos=6)
        c_sku = _wr_col_exact(df, "New SKU", "SKU", pos=7)
        c_package = _wr_col_exact(df, "Shipping Package Code", pos=8)
        c_invoice = _wr_col_exact(df, "Invoice Code", pos=9)
        c_created = _wr_col_exact(df, "Created", pos=10)
        c_city = _wr_col_exact(df, "Billing Address City", pos=11)
        c_cod = _wr_col_exact(df, "COD", pos=12)
        c_state = _wr_col_exact(df, "Billing Address State", pos=13)
        c_selling = _wr_col_exact(df, "Selling Price", pos=17)
        c_total = _wr_col_exact(df, "Total Price", pos=18)
        c_qty = _wr_col_exact(df, "Qty", "Quantity", pos=21)
        c_order_date = _wr_col_exact(df, "Order_Date", "Order Date", pos=22)
        # Physical columns AA:AD in the verified Website sheet.
        c_return_type = _at(26)
        c_rto_qty = _at(27)
        c_return_date = _at(28)
        c_return_reason = _at(29)
        c_type = _at(30)

        orders = {}
        source_rows = 0
        for _, raw in df.iterrows():
            order_key = _daily_reporting_order_key(raw.get(c_order, "")) if c_order is not None else ""
            if not order_key:
                continue
            status = _wr_clean_value(raw.get(c_status, "")) if c_status is not None else ""
            status_l = status.casefold()
            if status_l and any(x in status_l for x in ("cancel", "void", "failed")):
                continue
            source_rows += 1

            order_date = _wr_iso_date(raw.get(c_order_date, "")) if c_order_date is not None else ""
            if not order_date and c_created is not None:
                order_date = _wr_iso_date(raw.get(c_created, ""))
            payment_mode = _wr_website_payment_mode(raw.get(c_cod, "")) if c_cod is not None else "Unclassified"
            sku = _wr_clean_value(raw.get(c_sku, "")).upper() if c_sku is not None else ""
            qty = max(0.0, to_num(raw.get(c_qty, 0))) if c_qty is not None else 1.0
            rto_qty = max(0.0, to_num(raw.get(c_rto_qty, 0))) if c_rto_qty is not None else 0.0
            return_type = _wr_clean_value(raw.get(c_return_type, "")) if c_return_type is not None else ""
            return_date = _wr_iso_date(raw.get(c_return_date, "")) if c_return_date is not None else ""
            return_reason = _wr_clean_value(raw.get(c_return_reason, "")) if c_return_reason is not None else ""
            website_returned = bool(
                rto_qty > 0 or return_type or return_date or return_reason
                or any(x in status_l for x in ("return", "rto", "refund"))
            )

            rec = orders.get(order_key)
            if rec is None:
                rec = {
                    "display_order_code": order_key,
                    "order_date": order_date,
                    "customer": _wr_clean_value(raw.get(c_name, "")) if c_name is not None else "",
                    "address": _wr_clean_value(raw.get(c_addr, "")) if c_addr is not None else "",
                    "pincode": _wr_clean_value(raw.get(c_pin, "")) if c_pin is not None else "",
                    "city": _wr_clean_value(raw.get(c_city, "")) if c_city is not None else "",
                    "state": _wr_clean_value(raw.get(c_state, "")) if c_state is not None else "",
                    "payment_mode": payment_mode,
                    "qty": 0.0,
                    "selling_price_total": 0.0,
                    "total_price": 0.0,
                    "rto_qty": 0.0,
                    "website_returned": False,
                    "bluedart_returned": False,
                    "_skus": [], "_statuses": [], "_packages": [], "_invoices": [],
                    "_return_types": [], "_return_dates": [], "_return_reasons": [],
                    "_types": [],
                    "_bd_contacts": [], "_bd_customers": [], "_bd_pickups": [],
                    "_bd_statuses": [], "_bd_status_groups": [], "_bd_status_dates": [], "_bd_reasons": [],
                    "_bd_latest_status_group": "",
                    # Unclassified is allowed ONLY when a real BlueDart row has
                    # both Order ID and Customer Contact, while Status Group N is blank.
                    "_bd_blank_status_qualified": False, "_bd_matched_rows": 0,
                    "_bd_destinations": [], "_bd_waybills": [], "_bd_refs": [],
                }
                orders[order_key] = rec
            elif order_date and (not rec.get("order_date") or order_date < rec.get("order_date")):
                rec["order_date"] = order_date

            # Prefer classified payment over unknown. If duplicate lines disagree,
            # retain COD if any line says COD because M is an order-level flag.
            if payment_mode == "COD" or rec.get("payment_mode") == "Unclassified":
                rec["payment_mode"] = payment_mode
            if not rec.get("customer") and c_name is not None:
                rec["customer"] = _wr_clean_value(raw.get(c_name, ""))
            if not rec.get("address") and c_addr is not None:
                rec["address"] = _wr_clean_value(raw.get(c_addr, ""))
            if not rec.get("city") and c_city is not None:
                rec["city"] = _wr_clean_value(raw.get(c_city, ""))
            if not rec.get("state") and c_state is not None:
                rec["state"] = _wr_clean_value(raw.get(c_state, ""))
            if not rec.get("pincode") and c_pin is not None:
                rec["pincode"] = _wr_clean_value(raw.get(c_pin, ""))

            rec["qty"] += float(qty)
            rec["rto_qty"] += float(rto_qty)
            rec["selling_price_total"] += max(0.0, to_num(raw.get(c_selling, 0))) if c_selling is not None else 0.0
            rec["total_price"] += max(0.0, to_num(raw.get(c_total, 0))) if c_total is not None else 0.0
            rec["website_returned"] = bool(rec.get("website_returned") or website_returned)
            if sku: rec["_skus"].append(sku)
            if status: rec["_statuses"].append(status)
            if c_package is not None: rec["_packages"].append(raw.get(c_package, ""))
            if c_invoice is not None: rec["_invoices"].append(raw.get(c_invoice, ""))
            if return_type: rec["_return_types"].append(return_type)
            if return_date: rec["_return_dates"].append(return_date)
            if return_reason: rec["_return_reasons"].append(return_reason)
            if c_type is not None: rec["_types"].append(raw.get(c_type, ""))

        # Current Website Order Tracker enrichment. This is independent of the
        # BlueDart public export, so contact search and Website-return reasons keep
        # working even while the old BlueDart published tab is unavailable.
        tracker_map, tracker_meta = _wr_load_tracker_enrichment(force=force)
        for order_key, rec in orders.items():
            t = tracker_map.get(order_key)
            if not t:
                continue
            if not rec.get("customer") and t.get("customer"):
                rec["customer"] = t["customer"]
            if rec.get("payment_mode") == "Unclassified" and t.get("payment_mode") in ("COD", "Prepaid"):
                rec["payment_mode"] = t["payment_mode"]
            if t.get("sku_text"):
                rec["_skus"].extend([x.strip() for x in str(t.get("sku_text") or "").split(",") if x.strip()])
            if t.get("has_return"):
                rec["website_returned"] = True
                rec["rto_qty"] = max(float(rec.get("rto_qty") or 0.0), float(t.get("rto_qty") or 0.0))
                if t.get("return_type"): rec["_return_types"].append(t["return_type"])
                if t.get("return_date"): rec["_return_dates"].append(t["return_date"])
                reason = _wr_tracker_reason(t)
                if reason: rec["_return_reasons"].append(reason)
            if t.get("customer_contact"): rec["_bd_contacts"].append(t["customer_contact"])
            if t.get("customer"): rec["_bd_customers"].append(t["customer"])
            rec["tracker_customer_email"] = t.get("customer_email", "")
            rec["tracker_reason_source"] = ("RETURN & RTO Return Reason" if t.get("return_reason") else ("New_Uniware Reverse Pickup Reason" if t.get("reverse_pickup_reason") else ""))

        # Join genuine BlueDart Website shipment/status rows to Website column-A
        # Display Order Code. Status Group (physical column N) is the authority for
        # DL / IT / UD / RT / RD classification. If the operational endpoint is
        # using the Website fallback, do not invent BlueDart status-group values.
        bd_rows = _load_website_returns(force=force)
        if _WEBSITE_RETURNS_CACHE.get("source_kind") != "bluedart":
            bd_rows = []
        unmatched_bluedart = 0
        for bd in bd_rows:
            matched = None
            for raw_order in (bd.get("display_order_code", ""), bd.get("order_id", "")):
                key = _daily_reporting_order_key(raw_order)
                if key and key in orders:
                    matched = orders[key]
                    break
            if matched is None:
                unmatched_bluedart += 1
                continue
            bd_status_group = _wr_clean_value(bd.get("status_group", ""))
            bd_order_id = _wr_clean_value(bd.get("order_id", ""))
            bd_contact = _wr_contact_value(bd.get("customer_contact", ""))
            matched["_bd_matched_rows"] = int(matched.get("_bd_matched_rows") or 0) + 1
            # User rule: Unclassified means a genuine BlueDart row exists and
            # BOTH Order ID + Customer Contact are present, but Status Group N is blank.
            # No BlueDart match, missing identity/contact, or an unknown NONBLANK
            # status value must never be counted as Unclassified.
            if (not bd_status_group) and bd_order_id and bd_contact:
                matched["_bd_blank_status_qualified"] = True
            # A BlueDart row is an RTO only when Status Group N explicitly says
            # RT or RD. DL/IT/UD rows are shipment statuses, not returns.
            if _wr_bluedart_status_stage(bd_status_group) == "Return to Origin":
                matched["bluedart_returned"] = True
            matched["_bd_contacts"].append(bd_contact)
            matched["_bd_customers"].append(bd.get("customer", ""))
            matched["_bd_pickups"].append(bd.get("pickup_date", ""))
            matched["_bd_statuses"].append(bd.get("status_description", "") or bd_status_group)
            if bd_status_group:
                matched["_bd_status_groups"].append(bd_status_group)
                # _load_website_returns() is sorted newest status first, so the
                # first nonblank group seen for an order is its latest group.
                if not matched.get("_bd_latest_status_group"):
                    matched["_bd_latest_status_group"] = bd_status_group
            matched["_bd_status_dates"].append(bd.get("status_date", ""))
            matched["_bd_reasons"].append(bd.get("rto_reason", ""))
            matched["_bd_destinations"].append(bd.get("destination", ""))
            matched["_bd_waybills"].append(bd.get("waybill_no", ""))
            matched["_bd_refs"].append(bd.get("reference_no", ""))

        final_orders = []
        for rec in orders.values():
            skus = sorted({x for x in rec.pop("_skus", []) if x})
            statuses = rec.pop("_statuses", [])
            packages = rec.pop("_packages", [])
            invoices = rec.pop("_invoices", [])
            return_types = rec.pop("_return_types", [])
            return_dates = sorted({x for x in rec.pop("_return_dates", []) if x})
            return_reasons = rec.pop("_return_reasons", [])
            types = rec.pop("_types", [])
            bd_contacts = rec.pop("_bd_contacts", [])
            bd_customers = rec.pop("_bd_customers", [])
            bd_pickups = sorted({x for x in rec.pop("_bd_pickups", []) if x})
            bd_statuses = rec.pop("_bd_statuses", [])
            bd_status_groups = rec.pop("_bd_status_groups", [])
            bd_latest_status_group = rec.pop("_bd_latest_status_group", "")
            bd_blank_status_qualified = bool(rec.pop("_bd_blank_status_qualified", False))
            bd_matched_rows = int(rec.pop("_bd_matched_rows", 0) or 0)
            bd_status_dates = sorted({x for x in rec.pop("_bd_status_dates", []) if x})
            bd_reasons = rec.pop("_bd_reasons", [])
            bd_destinations = rec.pop("_bd_destinations", [])
            bd_waybills = rec.pop("_bd_waybills", [])
            bd_refs = rec.pop("_bd_refs", [])

            rec.update({
                "skus": skus,
                "sku_text": ", ".join(skus),
                "website_order_status": _wr_unique_join(statuses),
                "packages": _wr_unique_join(packages, ", "),
                "invoices": _wr_unique_join(invoices, ", "),
                "website_return_type": _wr_unique_join(return_types),
                "website_return_date": return_dates[-1] if return_dates else "",
                "website_return_reason": _wr_unique_join(return_reasons),
                "website_type": _wr_unique_join(types),
                "customer_contact": _wr_unique_join(bd_contacts, ", "),
                "bluedart_customer": _wr_unique_join(bd_customers),
                "bluedart_pickup_date": bd_pickups[-1] if bd_pickups else "",
                "bluedart_status": _wr_unique_join(bd_statuses),
                "bluedart_status_group": _wr_unique_join(bd_status_groups),
                "bluedart_latest_status_group": bd_latest_status_group,
                "bluedart_blank_status_qualified": bd_blank_status_qualified,
                "bluedart_matched_rows": bd_matched_rows,
                "bluedart_status_date": bd_status_dates[-1] if bd_status_dates else "",
                "bluedart_rto_reason": _wr_unique_join(bd_reasons),
                "bluedart_destination": _wr_unique_join(bd_destinations),
                "bluedart_waybill": _wr_unique_join(bd_waybills, ", "),
                "bluedart_reference": _wr_unique_join(bd_refs, ", "),
            })
            rec["returned"] = bool(rec.get("website_returned") or rec.get("bluedart_returned"))
            # Search text is server-only; it allows order/customer/contact/SKU/etc.
            rec["_search"] = " ".join([
                str(rec.get("display_order_code", "")), str(rec.get("customer", "")),
                str(rec.get("bluedart_customer", "")), str(rec.get("customer_contact", "")),
                str(rec.get("address", "")), str(rec.get("city", "")), str(rec.get("state", "")),
                str(rec.get("pincode", "")), str(rec.get("sku_text", "")), str(rec.get("packages", "")),
                str(rec.get("invoices", "")), str(rec.get("website_order_status", "")),
                str(rec.get("website_return_type", "")), str(rec.get("website_return_reason", "")),
                str(rec.get("bluedart_status", "")), str(rec.get("bluedart_status_group", "")),
                str(rec.get("bluedart_latest_status_group", "")), str(rec.get("bluedart_rto_reason", "")),
                str(rec.get("bluedart_destination", "")), str(rec.get("bluedart_waybill", "")),
            ]).casefold()
            final_orders.append(rec)

        final_orders.sort(key=lambda r: (r.get("order_date") or "", r.get("display_order_code") or ""), reverse=True)
        _WEBSITE_ORDER_AUDIT_CACHE.update({
            "orders": final_orders,
            "ts": now,
            "error": None,
            "source_rows": source_rows,
            "unmatched_bluedart": unmatched_bluedart,
            "tracker_contact_orders": int(tracker_meta.get("contact_orders") or 0),
            "tracker_reason_orders": int(tracker_meta.get("reason_orders") or 0),
        })
        return final_orders
    except Exception as e:
        _WEBSITE_ORDER_AUDIT_CACHE["error"] = str(e)
        if _WEBSITE_ORDER_AUDIT_CACHE.get("orders") is not None:
            return _WEBSITE_ORDER_AUDIT_CACHE["orders"]
        raise


def _website_returns_combo_child_map():
    """Compact parent-CMB -> child-SKU map for the Website Returns SKU filter.

    The browser filter already treats a child SKU query as a match for a returned
    parent CMB. The order-level donut must use the same rule. Cache the compact
    map against the main dashboard snapshot timestamp so typing in SKU Search
    does not rebuild the full catalogue on every keystroke.
    """
    stamp = float(CACHE.get("ts") or 0.0)
    cached = CACHE.get("website_returns_combo_child_map") or {}
    if cached.get("ts") == stamp and isinstance(cached.get("map"), dict):
        return cached["map"]

    try:
        master_rows = ((CACHE.get("data") or [None])[0] or [])
    except Exception:
        master_rows = []
    mapping = {}
    for item in master_rows:
        parent_raw = str((item or {}).get("sku") or "").strip().upper()
        parent_compact = re.sub(r"[^A-Z0-9]", "", parent_raw)
        if not parent_compact:
            continue
        children = []
        for child in ((item or {}).get("combo_details") or []):
            child_raw = str((child or {}).get("sku") or "").strip().upper()
            child_compact = re.sub(r"[^A-Z0-9]", "", child_raw)
            if child_raw and child_compact:
                children.append((child_raw, child_compact))
        if children:
            mapping[parent_compact] = tuple(children)
    CACHE["website_returns_combo_child_map"] = {"ts": stamp, "map": mapping}
    return mapping


def _wr_bluedart_status_stage(value):
    """Map BlueDart Status Group (physical column N) to the dashboard stage.

    User-confirmed codes:
      DL = Delivered
      IT = In Transit
      UD = Undelivered
      RT/RD = Return to Origin

    Blank/other values stay Unclassified. We never infer a courier stage from
    Website order status because the Website Returns status mix must follow N.
    """
    raw = str(value or "").strip().upper()
    codes = re.findall(r"(?<![A-Z0-9])(IT|UD|DL|RT|RD)(?![A-Z0-9])", raw)
    if not codes:
        return "Unclassified"
    code_set = set(codes)
    if "RT" in code_set or "RD" in code_set:
        return "Return to Origin"
    if "UD" in code_set:
        return "Undelivered"
    if "DL" in code_set:
        return "Delivered"
    if "IT" in code_set:
        return "In Transit"
    return "Unclassified"


def _wr_order_stage(rec):
    """Classify one Website order strictly from BlueDart Status Group column N.

    Unclassified is deliberately narrow: a matched BlueDart row must contain
    Order ID + Customer Contact and have a blank Status Group. Orders with no
    BlueDart match, missing identity/contact, or an unknown nonblank group are
    left outside the status mix instead of being mislabeled Unclassified.
    """
    rec = rec or {}
    raw_group = str(rec.get("bluedart_latest_status_group") or rec.get("bluedart_status_group") or "").strip()
    stage = _wr_bluedart_status_stage(raw_group)
    if stage != "Unclassified":
        return stage
    if (not raw_group) and bool(rec.get("bluedart_blank_status_qualified")):
        return "Unclassified"
    return ""


def _wr_public_order(rec):
    """Return browser-safe order fields and attach the normalized order stage."""
    out = {
        k: v for k, v in (rec or {}).items()
        if not str(k).startswith("_")
        and k not in ("selling_price_total", "total_price")
    }
    out["order_stage"] = _wr_order_stage(rec or {})
    return out


def _website_returns_overview_payload(force=False):
    """Return the order-level Website denominator under the active UI filters.

    The Website Orders & Returns screen has two grains:
      * shipment-level BlueDart/Website-return rows for return KPIs and analysis;
      * unique Website Display Order Code for the BlueDart Status Group pie and all-orders table.

    Every active Website Returns filter is applied to the order-level status mix.
    The courier stage itself is taken strictly from BlueDart Status Group column N:
    DL=Delivered, IT=In Transit, UD=Undelivered, RT/RD=Return to Origin.
    """
    orders = _load_website_order_audit(force=force)

    def _arg(name, default=""):
        return str(request.args.get(name, default) or default).strip()

    def _date_arg(name):
        raw = _arg(name)
        if not raw:
            return ""
        # Browser date inputs normally send YYYY-MM-DD, but normalize again on
        # the server so localized MM/DD/YYYY or legacy values cannot bypass the
        # filter. _wr_iso_date returns a zero-padded ISO date for string compare.
        return _wr_iso_date(raw) or raw

    order_from = _date_arg("order_from")
    order_to = _date_arg("order_to")
    pickup_from = _date_arg("pickup_from")
    pickup_to = _date_arg("pickup_to")
    status_from = _date_arg("status_from")
    status_to = _date_arg("status_to")
    payment = _arg("payment", "All") or "All"
    pay_min_raw = _arg("payment_min")
    pay_max_raw = _arg("payment_max")
    pay_min = float(to_num(pay_min_raw)) if pay_min_raw else None
    pay_max = float(to_num(pay_max_raw)) if pay_max_raw else None
    origin = _arg("origin", "All") or "All"
    destination_q = _arg("destination").casefold()
    status_description = _arg("status_description", "All") or "All"
    status_group = _arg("status_group", "All") or "All"
    reason = _arg("reason", "All") or "All"
    sku_q = _arg("sku").upper()
    search_q = _arg("search").casefold()
    table_all = _arg("table_all").casefold() in ("1", "true", "yes")
    try:
        table_page = max(1, int(float(_arg("table_page", "1") or 1)))
    except Exception:
        table_page = 1
    try:
        table_page_size = int(float(_arg("table_page_size", "350") or 350))
    except Exception:
        table_page_size = 350
    table_page_size = max(50, min(500, table_page_size))

    origin_cf = origin.casefold()
    status_description_cf = status_description.casefold()
    status_group_cf = status_group.casefold()
    reason_cf = reason.casefold()
    sku_compact = re.sub(r"[^A-Z0-9]", "", sku_q)
    combo_child_map = _website_returns_combo_child_map() if sku_q else {}

    orders_by_key = {}
    for rec in orders:
        key = _daily_reporting_order_key(rec.get("display_order_code", ""))
        if key:
            orders_by_key[key] = rec
    valid_order_keys = set(orders_by_key)

    return_filter_active = any((
        pickup_from, pickup_to, status_from, status_to,
        pay_min_raw, pay_max_raw, destination_q,
        origin not in ("", "All"),
        status_description not in ("", "All"),
        status_group not in ("", "All"),
        reason not in ("", "All"),
    ))
    return_match_keys = set()
    return_search_keys = set()

    def _row_order_keys(row):
        out = []
        for raw_order in (row.get("display_order_code", ""), row.get("order_id", "")):
            key = _daily_reporting_order_key(raw_order)
            if key and key in valid_order_keys and key not in out:
                out.append(key)
        return out

    def _date_ok(value, start_value, end_value):
        raw = str(value or "").strip()
        d = _wr_iso_date(raw) or raw
        if start_value and (not d or d < start_value):
            return False
        if end_value and (not d or d > end_value):
            return False
        return True

    def _payment_number(value):
        raw = str(value or "").strip()
        if not raw or not re.search(r"\d", raw):
            return None
        return float(to_num(raw))

    # _load_website_order_audit(force=True) already refreshes the return source,
    # so use its cache here and avoid downloading the same live sheet twice.
    if return_filter_active or search_q:
        for row in _load_website_returns(force=False):
            row_keys = _row_order_keys(row)
            if not row_keys:
                continue

            row_ok = True
            if not _date_ok(row.get("pickup_date", ""), pickup_from, pickup_to):
                row_ok = False
            if row_ok and not _date_ok(row.get("status_date", ""), status_from, status_to):
                row_ok = False

            pay_value = _payment_number(row.get("payment", ""))
            if row_ok and pay_min is not None and (pay_value is None or pay_value < pay_min):
                row_ok = False
            if row_ok and pay_max is not None and (pay_value is None or pay_value > pay_max):
                row_ok = False

            if row_ok and origin not in ("", "All"):
                if str(row.get("origin", "") or "").strip().casefold() != origin_cf:
                    row_ok = False
            if row_ok and destination_q:
                if destination_q not in str(row.get("destination", "") or "").casefold():
                    row_ok = False
            if row_ok and status_description not in ("", "All"):
                if str(row.get("status_description", "") or "").strip().casefold() != status_description_cf:
                    row_ok = False
            if row_ok and status_group not in ("", "All"):
                if str(row.get("status_group", "") or "").strip().casefold() != status_group_cf:
                    row_ok = False
            if row_ok and reason not in ("", "All"):
                if str(row.get("rto_reason", "") or "").strip().casefold() != reason_cf:
                    row_ok = False

            if row_ok:
                return_match_keys.update(row_keys)

            if search_q and row_ok:
                audit_bits = []
                for key in row_keys:
                    audit = orders_by_key.get(key) or {}
                    audit_bits.extend((
                        audit.get("sku_text", ""), audit.get("payment_mode", ""),
                        audit.get("customer", ""), audit.get("city", ""),
                        audit.get("state", ""), audit.get("pincode", ""),
                    ))
                row_search_hay = " ".join(str(v or "") for v in (
                    row.get("order_id", ""), row.get("display_order_code", ""),
                    row.get("customer", ""), row.get("customer_contact", ""),
                    row.get("payment", ""), row.get("origin", ""),
                    row.get("destination", ""), row.get("status_description", ""),
                    row.get("status_group", ""), row.get("status_date", ""),
                    row.get("rto_reason", ""), row.get("waybill_no", ""),
                    row.get("reference_no", ""), *audit_bits,
                )).casefold()
                if search_q in row_search_hay:
                    return_search_keys.update(row_keys)

    # First apply Website order-level filters. Shipment-level filters are then
    # intersected below so the status pie and all-orders table use the same state.
    base_orders = []
    for rec in orders:
        rec_key = _daily_reporting_order_key(rec.get("display_order_code", ""))
        od_raw = str(rec.get("order_date", "") or "").strip()
        od = _wr_iso_date(od_raw) or od_raw
        if order_from and (not od or od < order_from):
            continue
        if order_to and (not od or od > order_to):
            continue
        if payment in ("COD", "Prepaid") and rec.get("payment_mode") != payment:
            continue
        if sku_q:
            ok = False
            for sku in rec.get("skus") or []:
                su = str(sku or "").upper()
                sc = re.sub(r"[^A-Z0-9]", "", su)
                if sku_q in su or (sku_compact and sku_compact in sc):
                    ok = True
                    break
                # A returned CMB also matches a searched child SKU, exactly like
                # the shipment table's client-side combo-aware filter.
                for child_raw, child_compact in combo_child_map.get(sc, ()):
                    if sku_q in child_raw or (sku_compact and sku_compact in child_compact):
                        ok = True
                        break
                if ok:
                    break
            if not ok:
                continue
        if search_q:
            direct_match = search_q in str(rec.get("_search", ""))
            if not direct_match and rec_key not in return_search_keys:
                continue
        base_orders.append(rec)

    base_keys = {
        _daily_reporting_order_key(r.get("display_order_code", ""))
        for r in base_orders
        if _daily_reporting_order_key(r.get("display_order_code", ""))
    }
    if return_filter_active:
        status_orders = [
            r for r in base_orders
            if _daily_reporting_order_key(r.get("display_order_code", "")) in return_match_keys
        ]
    else:
        status_orders = base_orders

    # Actual return-source metrics stay available, but the operational status pie
    # follows the filtered order set above and BlueDart Status Group N only.
    returned = [r for r in status_orders if r.get("returned")]
    total_orders = len(status_orders)
    website_returns = sum(1 for r in returned if r.get("website_returned"))
    bluedart_returns = sum(1 for r in returned if r.get("bluedart_returned"))
    both_returns = sum(1 for r in returned if r.get("website_returned") and r.get("bluedart_returned"))
    cod_orders = sum(1 for r in status_orders if r.get("payment_mode") == "COD")
    prepaid_orders = sum(1 for r in status_orders if r.get("payment_mode") == "Prepaid")

    stage_counts = {
        "Delivered": 0,
        "In Transit": 0,
        "Undelivered": 0,
        "Return to Origin": 0,
        "Unclassified": 0,
    }
    for rec in status_orders:
        stage = _wr_order_stage(rec)
        if stage in stage_counts:
            stage_counts[stage] += 1
    delivered_orders = stage_counts["Delivered"]
    in_transit_orders = stage_counts["In Transit"]
    undelivered_orders = stage_counts["Undelivered"]
    return_to_origin_orders = stage_counts["Return to Origin"]
    unclassified_orders = stage_counts["Unclassified"]
    status_mix_orders = sum(stage_counts.values())
    status_not_counted_orders = max(0, total_orders - status_mix_orders)
    # Legacy key retained for any older frontend/cache consumer; it now means the
    # BlueDart RT/RD bucket, not generic Website-return detection.
    stage_returned_orders = return_to_origin_orders

    details_active = bool(search_q or sku_q)
    detail_source = status_orders
    detail_rows = []
    if details_active:
        detail_rows = [_wr_public_order(rec) for rec in detail_source[:500]]

    # Main table uses the exact same filtered order set as the status mix. Keep
    # it server-paginated so 20k+ Website orders do not freeze the browser.
    table_source = status_orders
    table_total = len(table_source)
    table_pages = max(1, (table_total + table_page_size - 1) // table_page_size)
    table_page = min(table_page, table_pages)
    if table_all:
        table_slice = table_source
    else:
        start = (table_page - 1) * table_page_size
        table_slice = table_source[start:start + table_page_size]
    table_orders = [_wr_public_order(rec) for rec in table_slice]

    active_filter_count = sum(bool(v) for v in (
        order_from, order_to, pickup_from, pickup_to, status_from, status_to,
        pay_min_raw, pay_max_raw, destination_q, sku_q, search_q,
        "" if payment == "All" else payment,
        "" if origin == "All" else origin,
        "" if status_description == "All" else status_description,
        "" if status_group == "All" else status_group,
        "" if reason == "All" else reason,
    ))

    return {
        "summary": {
            "total_orders": total_orders,
            "returned_orders": len(returned),
            "stage_returned_orders": stage_returned_orders,
            "return_to_origin_orders": return_to_origin_orders,
            "delivered_orders": delivered_orders,
            "in_transit_orders": in_transit_orders,
            "undelivered_orders": undelivered_orders,
            "unclassified_orders": unclassified_orders,
            "status_mix_orders": status_mix_orders,
            "status_not_counted_orders": status_not_counted_orders,
            "not_returned_orders": max(0, total_orders - return_to_origin_orders),
            "return_rate": round((return_to_origin_orders * 100.0 / total_orders), 2) if total_orders else 0.0,
            "website_sheet_returned": website_returns,
            "bluedart_returned": bluedart_returns,
            "both_sources": both_returns,
            "cod_orders": cod_orders,
            "prepaid_orders": prepaid_orders,
        },
        "orders": detail_rows,
        "table_orders": table_orders,
        "table_total": table_total,
        "table_page": table_page,
        "table_page_size": table_page_size,
        "table_pages": table_pages,
        "table_all": bool(table_all),
        "details_active": details_active,
        "details_total": len(detail_source) if details_active else 0,
        "details_limited": bool(details_active and len(detail_source) > 500),
        "active_filter_count": active_filter_count,
        "applied_order_from": order_from,
        "applied_order_to": order_to,
        "return_filter_active": bool(return_filter_active),
        "return_filter_orders": len(base_keys.intersection(return_match_keys)) if return_filter_active else 0,
        "source_rows": int(_WEBSITE_ORDER_AUDIT_CACHE.get("source_rows") or 0),
        "unmatched_bluedart": int(_WEBSITE_ORDER_AUDIT_CACHE.get("unmatched_bluedart") or 0),
        "tracker_contact_orders": int(_WEBSITE_ORDER_AUDIT_CACHE.get("tracker_contact_orders") or 0),
        "tracker_reason_orders": int(_WEBSITE_ORDER_AUDIT_CACHE.get("tracker_reason_orders") or 0),
        "loaded_at": now_ist().strftime("%d-%b-%Y %H:%M"),
    }


# ════════════════════════════════════════════════════════════════
#  LIVE WEBSITE OOS AUDIT
#  No email automation: this only crawls the live Shopify catalogue, maps
#  Website OOS SKUs to backend Inv Stock, serves the dashboard tab, and exports
#  the exact email-ready Excel format requested by operations.
# ════════════════════════════════════════════════════════════════
_WEBSITE_OOS_CACHE = {"payload": None, "ts": 0.0}
_WEBSITE_OOS_TTL = 180
_WEBSITE_OOS_LOCK = threading.Lock()

def _website_oos_bool(v):
    if isinstance(v, bool):
        return v
    if v is None:
        return None
    s = str(v).strip().lower()
    if s in ("true", "1", "yes", "y", "available", "in stock", "instock"):
        return True
    if s in ("false", "0", "no", "n", "unavailable", "out of stock", "outofstock", "sold out"):
        return False
    return None

def _website_oos_fetch_live_products():
    """Fetch the complete public Shopify catalogue with strict completeness.

    Unlike the background CN-name loader, this audit refuses a partial crawl:
    if any page fails, the API returns an error (or an already cached complete
    payload) rather than falsely claiming that missing pages have no OOS SKUs.
    """
    headers = {
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36",
        "Accept": "application/json",
        "Cache-Control": "no-cache",
        "Pragma": "no-cache",
    }
    products_all = []
    pages = 0
    for page in range(1, 61):
        url = f"{CN_STORE_URL}/products.json?limit=250&page={page}&_={int(time.time())}"
        r = requests.get(url, headers=headers, timeout=(6, 18))
        if not r.ok:
            raise RuntimeError(f"cosanostraa.com products page {page} returned HTTP {r.status_code}")
        try:
            payload = r.json() or {}
        except Exception as e:
            raise RuntimeError(f"cosanostraa.com products page {page} returned invalid JSON: {e}")
        products = payload.get("products") or []
        if not isinstance(products, list):
            raise RuntimeError(f"cosanostraa.com products page {page} has invalid products payload")
        pages += 1
        if not products:
            return products_all, pages
        products_all.extend(products)
        if len(products) < 250:
            return products_all, pages
    raise RuntimeError("cosanostraa.com catalogue exceeded 60 pages; audit stopped to avoid incomplete results")

def _website_oos_fetch_7d_sales():
    """Return normalized SKU -> Website sold qty for today + previous 6 days.

    Source and quantity rules intentionally mirror the dashboard's authoritative
    Website sales logic: physical W / Order_Date, New SKU, cancelled/void/failed
    rows excluded, and sold qty is gross Qty minus RTO/Return Qty (never below 0).
    The published CSV is fetched with _fetch_csv_fresh so every 5-minute OOS
    live refresh sees the latest Website order sheet rather than a stale cache.
    """
    df = _fetch_csv_fresh(RAKHI_WEBSITE_ADDR_URL)
    if df is None or df.empty:
        return {}, "", ""
    df.columns = [str(c).strip() for c in df.columns]
    cols = list(df.columns)
    def _at(i):
        return cols[i] if len(cols) > i else None

    w_date = (_at(22) or find_col(
        df.columns, "Order_Date", "Order Date", "Display Order Date", "order date", "orderdate"
    ))
    w_sku = (find_col(df.columns, "New SKU", "SKU", "sku code", "product sku", "item sku") or _at(7))
    qty_keys = {
        "finalqty", "finalquantity", "soldqty", "saleqty", "orderqty",
        "orderedqty", "totalqty", "quantity", "qty",
    }
    w_qty = next((
        c for c in df.columns
        if re.sub(r"[^a-z0-9]", "", str(c).lower()) in qty_keys
    ), None)
    w_status = find_col(df.columns, "Sale Order Status", "Order Status", "status")
    w_rto = find_col(df.columns, "RTO Qty", "Return Qty", "Returned Qty")
    if not w_date or not w_sku:
        raise RuntimeError(f"Website 7D sold qty columns missing: date={w_date}, sku={w_sku}")

    today = datetime.now(TZ).date()
    start = today - timedelta(days=6)
    totals = {}
    for row in _df_chunks(df, 4000):
        status = str(row.get(w_status, "") or "").strip().lower() if w_status else ""
        if status and any(x in status for x in ("cancel", "void", "failed")):
            continue
        dt = parse_date_any(row.get(w_date, ""))
        if dt is None:
            continue
        d = dt.date()
        if d < start or d > today:
            continue
        sku = clean(row.get(w_sku, ""))
        key = _cn_normalize(sku)
        if not key:
            continue
        gross = to_num(row.get(w_qty, 0)) if w_qty else 1.0
        rto = max(0.0, to_num(row.get(w_rto, 0))) if w_rto else 0.0
        sold = max(0.0, float(gross) - float(rto)) if w_qty else 1.0
        if sold <= 0:
            continue
        totals[key] = totals.get(key, 0.0) + sold
    return totals, start.isoformat(), today.isoformat()

def _build_website_oos_report(force=False):
    now = time.time()
    cached = _WEBSITE_OOS_CACHE.get("payload")
    if (not force and cached is not None and now - float(_WEBSITE_OOS_CACHE.get("ts") or 0) < _WEBSITE_OOS_TTL):
        return cached

    with _WEBSITE_OOS_LOCK:
        now = time.time()
        cached = _WEBSITE_OOS_CACHE.get("payload")
        if (not force and cached is not None and now - float(_WEBSITE_OOS_CACHE.get("ts") or 0) < _WEBSITE_OOS_TTL):
            return cached
        try:
            products, page_count = _website_oos_fetch_live_products()
            if not products:
                raise RuntimeError("cosanostraa.com returned zero products; refusing to publish an empty OOS audit")

            # Manual/5-minute live refresh also refreshes backend inventory and
            # the Website order sheet used for the Last 7 Days sold-qty column.
            inv_rows, inv_meta = _build_operations_inventory(force=force)
            website_sales_7d, website_sales_7d_from, website_sales_7d_to = _website_oos_fetch_7d_sales()
            inv_map = {}
            for r in (inv_rows or []):
                key = _cn_normalize(r.get("sku", ""))
                if not key:
                    continue
                rec = {
                    "inv_stock": max(0, to_int(r.get("inv_stock", 0))),
                    "blocked_qty": max(0, to_int(r.get("blocked_qty", 0))),
                    "inv_wip": max(0, to_int(r.get("inv_wip", 0))),
                }
                old = inv_map.get(key)
                if old:
                    old["inv_stock"] = max(old["inv_stock"], rec["inv_stock"])
                    old["blocked_qty"] = max(old["blocked_qty"], rec["blocked_qty"])
                    old["inv_wip"] = max(old["inv_wip"], rec["inv_wip"])
                else:
                    inv_map[key] = rec

            master_map = {}
            try:
                master_rows = ((CACHE.get("data") or [None])[0] or [])
            except Exception:
                master_rows = []
            if not master_rows:
                try:
                    master_rows = (get_data(False) or [None])[0] or []
                except Exception:
                    master_rows = []
            for item in master_rows:
                key = _cn_normalize((item or {}).get("sku", ""))
                if key and key not in master_map:
                    master_map[key] = item

            # Aggregate duplicate published variant SKUs. A SKU is OOS only if
            # every published occurrence has a known `available` value and none
            # of those occurrences is available. This prevents duplicate product
            # listings from generating a false OOS flag.
            sku_web = {}
            for p in products:
                title = clean((p or {}).get("title", ""))
                handle = clean((p or {}).get("handle", ""))

                # Shopify products.json supplies product images and variant image_id.
                # Prefer the exact variant image; fall back to the product's main
                # image so every OOS row can show a useful live storefront photo.
                images_by_id = {}
                product_image_url = ""
                for _img in ((p or {}).get("images") or []):
                    if not isinstance(_img, dict):
                        continue
                    _src = clean(_img.get("src", ""))
                    _iid = clean(_img.get("id", ""))
                    if _src:
                        if _src.startswith("//"):
                            _src = "https:" + _src
                        elif _src.startswith("/"):
                            _src = CN_STORE_URL.rstrip("/") + _src
                        if not product_image_url:
                            product_image_url = _src
                        if _iid:
                            images_by_id[_iid] = _src
                _main_img = (p or {}).get("image") or {}
                if isinstance(_main_img, dict):
                    _src = clean(_main_img.get("src", ""))
                    if _src:
                        if _src.startswith("//"):
                            _src = "https:" + _src
                        elif _src.startswith("/"):
                            _src = CN_STORE_URL.rstrip("/") + _src
                        product_image_url = _src or product_image_url

                for v in ((p or {}).get("variants") or []):
                    sku = clean((v or {}).get("sku", ""))
                    if not sku:
                        continue
                    key = _cn_normalize(sku)
                    if not key:
                        continue
                    variant_id = clean((v or {}).get("id", ""))
                    if handle:
                        product_url = f"{CN_STORE_URL}/products/{handle}"
                        if variant_id:
                            product_url += f"?variant={variant_id}"
                    else:
                        product_url = CN_STORE_URL
                    available = _website_oos_bool((v or {}).get("available"))

                    # Variant-specific photo, if available. Shopify may expose
                    # either image_id or featured_image depending on storefront.
                    image_url = ""
                    _variant_image_id = clean((v or {}).get("image_id", ""))
                    if _variant_image_id:
                        image_url = images_by_id.get(_variant_image_id, "")
                    _featured = (v or {}).get("featured_image") or (v or {}).get("image") or {}
                    if (not image_url) and isinstance(_featured, dict):
                        _src = clean(_featured.get("src", ""))
                        if _src:
                            if _src.startswith("//"):
                                _src = "https:" + _src
                            elif _src.startswith("/"):
                                _src = CN_STORE_URL.rstrip("/") + _src
                            image_url = _src
                    if not image_url:
                        image_url = product_image_url

                    rec = sku_web.get(key)
                    if rec is None:
                        rec = {
                            "sku": sku, "product_title": title, "product_url": product_url,
                            "image_url": image_url,
                            "occurrences": 0, "availability_known": 0, "any_available": False,
                        }
                        sku_web[key] = rec
                    rec["occurrences"] += 1
                    if available is not None:
                        rec["availability_known"] += 1
                        if available:
                            rec["any_available"] = True
                    # Prefer a real handle URL/title if the first duplicate was sparse.
                    if (not rec.get("product_title")) and title:
                        rec["product_title"] = title
                    if (not rec.get("product_url") or rec.get("product_url") == CN_STORE_URL) and handle:
                        rec["product_url"] = product_url
                    if (not rec.get("image_url")) and image_url:
                        rec["image_url"] = image_url

            oos_rows = []
            unknown_availability = 0
            for key, web in sku_web.items():
                if web["any_available"]:
                    continue
                if web["availability_known"] != web["occurrences"]:
                    unknown_availability += 1
                    continue
                inv_key = _inventory_resolve_key(key, inv_map)
                inv = inv_map.get(inv_key) or {}
                master_key = key if key in master_map else _inventory_resolve_key(key, master_map)
                master_item = master_map.get(master_key) or {}
                cn_name = clean(master_item.get("cn_name", "")) or clean(web.get("product_title", "")) or web.get("sku", "")
                oos_rows.append({
                    "sku": web.get("sku", ""),
                    "cn_name": cn_name,
                    "product_title": web.get("product_title", ""),
                    "product_url": web.get("product_url", ""),
                    "image_url": web.get("image_url", ""),
                    "website_status": "Out of Stock",
                    "website_sold_qty_7d": round(float(website_sales_7d.get(key, 0.0)), 4),
                    "inv_stock": max(0, to_int(inv.get("inv_stock", 0))),
                    "blocked_qty": max(0, to_int(inv.get("blocked_qty", 0))),
                    "inv_wip": max(0, to_int(inv.get("inv_wip", 0))),
                    "inventory_source_sku": inv_key or "",
                    "inventory_suffix_fallback": bool(inv_key and inv_key != key),
                    "backend_match": bool(inv_key),
                })

            oos_rows.sort(key=lambda r: (-int(r.get("inv_stock") or 0), str(r.get("sku") or "").upper()))
            payload = {
                "rows": oos_rows,
                "website_products": len(products),
                "website_pages": page_count,
                "website_skus": len(sku_web),
                "website_oos_skus": len(oos_rows),
                "oos_with_backend_stock": sum(1 for r in oos_rows if int(r.get("inv_stock") or 0) > 0),
                "oos_without_backend_stock": sum(1 for r in oos_rows if int(r.get("inv_stock") or 0) <= 0),
                "backend_matched_oos_skus": sum(1 for r in oos_rows if r.get("backend_match")),
                "availability_unknown_skus": unknown_availability,
                "website_sales_7d_from": website_sales_7d_from,
                "website_sales_7d_to": website_sales_7d_to,
                "website_sales_source": "Website Order_Date / New SKU",
                "inventory_source": str((inv_meta or {}).get("source") or "All Product"),
                "inventory_stock_column": str((inv_meta or {}).get("stock_column") or "Inv Stock"),
                "checked_at": datetime.now(TZ).isoformat(),
                "website_source": f"{CN_STORE_URL}/products.json",
            }
            _WEBSITE_OOS_CACHE.update({"payload": payload, "ts": time.time()})
            return payload
        except Exception:
            # A complete previous crawl is safer than a partial new one. Manual
            # refresh still reports failure if no complete cache exists.
            if cached is not None and not force:
                return cached
            raise

@app.route("/api/website-oos")
def api_website_oos():
    if session.get("role") not in ("admin", "employee"):
        return jsonify({"error": "login required"}), 401
    try:
        force = request.args.get("force", "0").strip().lower() in ("1", "true", "yes")
        return jsonify(_build_website_oos_report(force=force))
    except Exception as e:
        return jsonify({"error": "Website OOS live audit failed: " + str(e)[:400]}), 502

@app.route("/api/website-oos/export.xlsx", methods=["POST"])
def api_website_oos_export_xlsx():
    if session.get("role") not in ("admin", "employee"):
        return jsonify({"error": "login required"}), 401
    try:
        import io
        import openpyxl
        from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
        from openpyxl.utils import get_column_letter

        body = request.get_json(silent=True) or {}
        threshold = max(1, to_int(body.get("threshold", 1)))
        raw_rows = body.get("rows") or []
        rows = []
        seen = set()
        for r in raw_rows:
            sku = clean((r or {}).get("sku", ""))
            if not sku:
                continue
            key = _cn_normalize(sku)
            if not key or key in seen:
                continue
            inv_stock = max(0, to_int((r or {}).get("inv_stock", 0)))
            if inv_stock < threshold:
                continue
            seen.add(key)
            rows.append({
                "SKU code": sku,
                "CN Name": clean((r or {}).get("cn_name", "")),
                "Product URL": clean((r or {}).get("product_url", "")),
                "Website Status": clean((r or {}).get("website_status", "")) or "Out of Stock",
                "In stock inventory": inv_stock,
            })
        rows.sort(key=lambda x: (-x["In stock inventory"], x["SKU code"].upper()))
        if not rows:
            return jsonify({"error": f"No Website OOS SKU has backend Inv Stock >= {threshold}."}), 404

        wb = openpyxl.Workbook()
        ws = wb.active
        ws.title = "OOS Stock Flags"
        subject = f"{len(rows)} SKUs with Sufficient stock is showing OOS"
        ws.merge_cells("A1:E1")
        ws["A1"] = subject
        ws["A1"].font = Font(bold=True, size=15, color="7A1C16")
        ws["A1"].fill = PatternFill("solid", fgColor="FDE9E7")
        ws["A1"].alignment = Alignment(horizontal="left", vertical="center")
        ws.row_dimensions[1].height = 27
        ws.merge_cells("A2:E2")
        ws["A2"] = f"Live Website OOS audit | Sufficient stock threshold: {threshold} | Generated: {datetime.now(TZ).strftime('%d-%b-%Y %I:%M %p')}"
        ws["A2"].font = Font(italic=True, size=9, color="6B6258")

        headers = ["SKU code", "CN Name", "Product URL", "Website Status", "In stock inventory"]
        header_row = 4
        for c, h in enumerate(headers, 1):
            cell = ws.cell(header_row, c, h)
            cell.font = Font(bold=True, color="FFFFFF")
            cell.fill = PatternFill("solid", fgColor="8C6A24")
            cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
        thin = Side(style="thin", color="DDD5C5")
        border = Border(left=thin, right=thin, top=thin, bottom=thin)
        for r_idx, row in enumerate(rows, header_row + 1):
            for c_idx, h in enumerate(headers, 1):
                cell = ws.cell(r_idx, c_idx, row[h])
                cell.border = border
                cell.alignment = Alignment(vertical="top", wrap_text=(h in ("CN Name", "Product URL")))
            url_cell = ws.cell(r_idx, 3)
            if str(url_cell.value or "").startswith(("http://", "https://")):
                url_cell.hyperlink = str(url_cell.value)
                url_cell.style = "Hyperlink"
            ws.cell(r_idx, 5).number_format = "#,##0"

        for cell in ws[header_row]:
            cell.border = border
        ws.freeze_panes = "A5"
        ws.auto_filter.ref = f"A{header_row}:E{header_row + len(rows)}"
        widths = [18, 42, 60, 20, 20]
        for i, width in enumerate(widths, 1):
            ws.column_dimensions[get_column_letter(i)].width = width

        bio = io.BytesIO()
        wb.save(bio)
        bio.seek(0)
        fname = f"{len(rows)}_SKUs_with_Sufficient_stock_showing_OOS_{datetime.now(TZ).strftime('%Y-%m-%d')}.xlsx"
        resp = app.response_class(bio.read(), mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")
        resp.headers["Content-Disposition"] = f'attachment; filename="{fname}"'
        resp.headers["X-Email-Subject"] = subject
        return resp
    except Exception as e:
        return jsonify({"error": "Website OOS Excel export failed: " + str(e)[:400]}), 500

