@app.route("/api/website-returns")
def api_website_returns():
    force = request.args.get("force", "0").lower() in ("1", "true", "yes")
    try:
        rows = _load_website_returns(force=force)
        payment_lookup = CACHE.get("website_return_payment_mode_lookup") or {}
        order_sku_lookup = CACHE.get("website_return_order_skus") or {}

        # Authoritative Website Order_Date lookup for the shipment-level return
        # cards. This keeps Order From/To identical between return KPIs and the
        # order-level Returned/Delivered/In-Transit pie. _load_website_returns()
        # is already cached above, so building/reusing the audit cannot recurse.
        audit_by_key = {}
        try:
            for _audit in _load_website_order_audit(force=False):
                _key = _daily_reporting_order_key(_audit.get("display_order_code", ""))
                if _key:
                    audit_by_key[_key] = _audit
        except Exception:
            audit_by_key = {}

        enriched_rows = []
        for r in rows:
            rec = dict(r)
            payment_mode = ""
            matched_key = ""
            matched_skus = []
            # BlueDart Display Order Code is often #N/A, while BlueDart Order ID
            # contains the Website Display Order Code.  Try both identities but
            # always resolve them through the exact Website column-A order token.
            for raw_order in (rec.get("display_order_code", ""), rec.get("order_id", "")):
                token = _daily_reporting_order_token("Website", raw_order)
                if not token:
                    continue
                if not matched_skus and token in order_sku_lookup:
                    matched_skus = list(order_sku_lookup.get(token) or [])
                    matched_key = matched_key or _daily_reporting_order_key(raw_order)
                if not payment_mode and token in payment_lookup:
                    payment_mode = payment_lookup[token]
                    matched_key = matched_key or _daily_reporting_order_key(raw_order)
                if payment_mode and matched_skus:
                    break
            # Prefer the exact Website order audit for Order Date, payment and
            # SKU identity whenever the courier row maps to a Display Order Code.
            audit_rec = None
            audit_key = ""
            for raw_order in (rec.get("display_order_code", ""), rec.get("order_id", "")):
                k = _daily_reporting_order_key(raw_order)
                if k and k in audit_by_key:
                    audit_key = k
                    audit_rec = audit_by_key[k]
                    break
            if audit_rec is not None:
                website_order_date = str(audit_rec.get("order_date", "") or "").strip()
                if website_order_date:
                    rec["order_date"] = _wr_iso_date(website_order_date) or website_order_date
                if audit_rec.get("payment_mode") in ("COD", "Prepaid"):
                    payment_mode = audit_rec.get("payment_mode")
                audit_skus = [str(x).strip().upper() for x in (audit_rec.get("skus") or []) if str(x).strip()]
                if audit_skus:
                    matched_skus = audit_skus
                matched_key = matched_key or audit_key

            rec["payment_mode"] = payment_mode
            rec["skus"] = sorted({str(x).strip().upper() for x in matched_skus if str(x).strip()})
            rec["sku_text"] = ", ".join(rec["skus"])
            # Backfill the broken BlueDart Display Order Code only after either
            # payment or SKU matching confirms the exact Website order identity.
            if not rec.get("display_order_code") and (payment_mode or rec["skus"]) and matched_key:
                rec["display_order_code"] = matched_key
            enriched_rows.append(rec)

        filters = {
            "rto_reasons": sorted({r.get("rto_reason", "") for r in enriched_rows if r.get("rto_reason")}),
            "origins": sorted({r.get("origin", "") for r in enriched_rows if r.get("origin")}),
            "destinations": sorted({r.get("destination", "") for r in enriched_rows if r.get("destination")}),
            "status_descriptions": sorted({r.get("status_description", "") for r in enriched_rows if r.get("status_description")}),
            "status_groups": sorted({r.get("status_group", "") for r in enriched_rows if r.get("status_group")}),
            "skus": sorted({sku for r in enriched_rows for sku in (r.get("skus") or []) if sku}),
            "payment_modes": [m for m in ("COD", "Prepaid") if any(r.get("payment_mode") == m for r in enriched_rows)],
        }
        classified = sum(1 for r in enriched_rows if r.get("payment_mode") in ("COD", "Prepaid"))
        sku_linked = sum(1 for r in enriched_rows if r.get("skus"))
        return jsonify({
            "rows": enriched_rows,
            "filters": filters,
            "source_rows": int(_WEBSITE_RETURNS_CACHE.get("source_rows") or 0),
            "sheet_data_rows": int(_WEBSITE_RETURNS_CACHE.get("sheet_data_rows") or 0),
            "ignored_non_website_rows": int(_WEBSITE_RETURNS_CACHE.get("ignored_non_website_rows") or 0),
            "sheet_rows_including_header": int(_WEBSITE_RETURNS_CACHE.get("sheet_data_rows") or 0) + 1,
            "unique_shipments": len(rows),
            "payment_classified": classified,
            "payment_unclassified": max(0, len(rows) - classified),
            "sku_linked": sku_linked,
            "payment_mode_source": "Website order COD flag (Display Order Code)",
            "sku_source": "Website sales sheet: Display Order Code + New SKU",
            "loaded_at": now_ist().strftime("%d-%b-%Y %H:%M"),
            "source": _WEBSITE_RETURNS_CACHE.get("source") or "BlueDart Return",
            "source_kind": _WEBSITE_RETURNS_CACHE.get("source_kind") or "bluedart",
            "source_warning": _WEBSITE_RETURNS_CACHE.get("source_warning") or "",
            "tracker_contact_orders": int(_WEBSITE_RETURNS_CACHE.get("tracker_contact_orders") or 0),
            "tracker_reason_orders": int(_WEBSITE_RETURNS_CACHE.get("tracker_reason_orders") or 0),
            "tracker_return_orders": int(_WEBSITE_RETURNS_CACHE.get("tracker_return_orders") or 0),
            "contact_source": "New_Uniware: Display Order Code + Notification Mobile",
            "return_reason_source": "RETURN & RTO: Return Reason; New_Uniware Reverse Pickup Reason fallback",
        })
    except Exception as e:
        return jsonify({"error": "Website Returns sheet load failed: " + str(e)[:300]}), 502

# ════════════════════════════════════════════════════════════════
#  🎯 TARGET vs ACTUAL  (admin only)
#  Target sheet: Date, Stake Holder, Channel Type, Qty Target, SP Target
#  Actual: COSA se (month + stakeholder[customer] + channel[type] wise)
# ════════════════════════════════════════════════════════════════
_TARGET_CACHE = {"rows": None, "ts": 0}

# Approved one-month override: August 2026 Website SP target = ₹3 crore.
# It is applied once in the shared target source, so Target vs Actual and
# Daily Revenue Glimpse always calculate from the same Website target.
WEBSITE_SP_TARGET_OVERRIDE_MONTH = "2026-08"
WEBSITE_SP_TARGET_OVERRIDE_VALUE = 30000000.0

def _apply_website_sp_target_override(rows):
    matched = [
        r for r in rows
        if r.get("month") == WEBSITE_SP_TARGET_OVERRIDE_MONTH
        and str(r.get("channel") or "").strip().casefold() in ("website", "online", "d2c")
    ]
    if not matched:
        rows.append({
            "month": WEBSITE_SP_TARGET_OVERRIDE_MONTH,
            "month_label": "Aug 2026",
            "stakeholder": "Website",
            "channel": "Website",
            "qty_target": 0.0,
            "sp_target": WEBSITE_SP_TARGET_OVERRIDE_VALUE,
        })
        return rows

    # Preserve multiple stakeholder rows if the sheet has them, while making
    # their combined Website target exactly ₹3 crore (no double target).
    old_total = sum(max(0.0, to_num(r.get("sp_target"))) for r in matched)
    assigned = 0.0
    for idx, row in enumerate(matched):
        if idx == len(matched) - 1:
            value = WEBSITE_SP_TARGET_OVERRIDE_VALUE - assigned
        elif old_total > 0:
            value = WEBSITE_SP_TARGET_OVERRIDE_VALUE * max(0.0, to_num(row.get("sp_target"))) / old_total
        else:
            value = WEBSITE_SP_TARGET_OVERRIDE_VALUE / len(matched)
        row["sp_target"] = value
        assigned += value
    return rows

def _fetch_target_rows():
    """Target sheet ko parse karke normalized rows deta hai (cache 10 min)."""
    if _TARGET_CACHE["rows"] is not None and (time.time() - _TARGET_CACHE["ts"] < 600):
        return _TARGET_CACHE["rows"]
    df = _fetch_csv_fresh(TARGET_URL)
    cols = list(df.columns)
    def _at(i): return cols[i] if len(cols) > i else None
    C_D  = _at(0) or find_col(df.columns, "Date","month")
    C_SH = _at(1) or find_col(df.columns, "Stake Holder","stakeholder","stake","name","person")
    C_CH = _at(2) or find_col(df.columns, "Channel Type","channel","type")
    C_QT = _at(3) or find_col(df.columns, "Qty Target","qty target","quantity target","qty")
    C_ST = _at(4) or find_col(df.columns, "SP Target","sp target","revenue target","value target","sp")
    out = []
    for _, r in df.iterrows():
        dt = parse_date_any(r.get(C_D, "")) if C_D else None
        if dt is None:
            continue
        mk = dt.strftime("%Y-%m")
        sh = clean(r.get(C_SH, "")) if C_SH else ""
        ch = _marketplace_display_text(r.get(C_CH, "")) if C_CH else ""
        if _is_amazon_fba_value(ch):
            ch = "Amazon"
        qt = to_num(r.get(C_QT, 0)) if C_QT else 0.0
        st = to_num(r.get(C_ST, 0)) if C_ST else 0.0
        if not sh and not ch:
            continue
        out.append({"month": mk, "month_label": dt.strftime("%b %Y"),
                    "stakeholder": sh or "—", "channel": ch or "—",
                    "qty_target": qt, "sp_target": st})
    out = _apply_website_sp_target_override(out)
    merged = []
    amazon_positions = {}
    for row in out:
        if str(row.get("channel") or "").strip().casefold() != "amazon":
            merged.append(row)
            continue
        key = (row.get("month", ""), str(row.get("stakeholder") or "").strip().casefold())
        pos = amazon_positions.get(key)
        if pos is None:
            amazon_positions[key] = len(merged)
            merged.append(dict(row))
        else:
            merged[pos]["qty_target"] = float(merged[pos].get("qty_target") or 0) + float(row.get("qty_target") or 0)
            merged[pos]["sp_target"] = float(merged[pos].get("sp_target") or 0) + float(row.get("sp_target") or 0)
    out = merged
    _TARGET_CACHE["rows"] = out
    _TARGET_CACHE["ts"] = time.time()
    return out

# ════════════════════════════════════════════════════════════════
