def _rakhi_prod_need_by_iso(value):
    """Normalize plan delivery text to an August-2026 ISO date.

    Handles text variants such as Need By 12th / need by 12 / 12th / Aug 12.
    The uploaded plan is explicitly for August 2026.
    """
    if isinstance(value, datetime):
        return value.date().isoformat()
    if isinstance(value, date):
        return value.isoformat()
    s = clean(value)
    if not s:
        return ""
    # Need-by text is authoritative: any ordinal/day number belongs to Aug-2026.
    m = re.search(r"(?<!\d)(3[01]|[12]?\d)(?:st|nd|rd|th)?(?!\d)", s, re.I)
    if m:
        try:
            return date(2026, 8, int(m.group(1))).isoformat()
        except ValueError:
            return ""
    dt = parse_date_any(s)
    if dt:
        try:
            return date(2026, 8, dt.day).isoformat()
        except ValueError:
            return ""
    return ""

def _rakhi_prod_order_key(value):
    """Stable Order No. key across int/float/text/case/spacing formats."""
    if value is None:
        return ""
    try:
        if isinstance(value, (int, np.integer)):
            return str(int(value))
        if isinstance(value, (float, np.floating)) and np.isfinite(value) and float(value).is_integer():
            return str(int(value))
    except Exception:
        pass
    s = str(value)
    try:
        import unicodedata
        s = unicodedata.normalize("NFKC", s)
    except Exception:
        pass
    s = s.replace("\u00a0", " ").strip().strip("'\"")
    # Spreadsheet exports can format integer order numbers as 1427.0,
    # 1,427.00, or text with spaces. Normalize all of them to the same key.
    compact = re.sub(r"[,\s]+", "", s)
    if re.fullmatch(r"[+-]?\d+(?:\.0+)?", compact):
        try:
            return str(int(float(compact)))
        except Exception:
            pass
    return re.sub(r"\s+", " ", s).strip().casefold()

def _rakhi_prod_order_rank(value):
    """Numeric order sequence for comparing newer production orders."""
    s = _rakhi_prod_order_key(value)
    m = re.search(r"\d+", s)
    return int(m.group(0)) if m else None

def _rakhi_prod_live_need_by(sku, order_no):
    """Need-by rule for live Production rows that are not in the supplied plan.

    Direct RKH is always due 13-Aug-2026. Other live pending SKUs through
    Order No. 1435 are due 31-Aug-2026. Later/non-numeric order numbers are
    intentionally left blank. Inputs may be int/float/text/mixed case.
    """
    sk = _rakhi_prod_sku_key(sku)
    if sk.startswith("RKH"):
        return "2026-08-13", "Need By 13th"
    rank = _rakhi_prod_order_rank(order_no)
    if rank is not None and rank <= 1435:
        return "2026-08-31", "Need By 31st"
    return "", ""

def _rakhi_prod_sku_key(value):
    """Case/punctuation/Unicode-insensitive SKU key for CSV + Production joins."""
    if value is None:
        return ""
    s = str(value)
    try:
        import unicodedata
        s = unicodedata.normalize("NFKC", s)
    except Exception:
        pass
    s = s.replace("\u00a0", " ").strip().upper()
    return re.sub(r"[^A-Z0-9]", "", s)

def _fetch_rakhi_receipts_freshest(today_date):
    """Fetch the freshest reachable Rakhi inward CSV.

    The same Google sheet is exposed through the user's published CSV and, when
    public access permits it, through the live GViz CSV endpoint.  All sources
    are fetched in parallel and ranked by newest valid Date first, then by the
    amount/row count after the 06-Aug baseline.  This prevents an older
    Publish-to-web snapshot from winning merely because it returned first.
    """
    baseline_date = datetime.strptime(_RAKHI_PRODUCTION_BASELINE_DATE, "%Y-%m-%d").date()
    specs = []
    seen = set()
    for label, url in [
        ("direct", u) for u in _RAKHI_RECEIPTS_DIRECT_URLS if u
    ] + [("published", _RAKHI_RECEIPTS_CSV_URL)]:
        url = str(url or "").strip()
        if not url or url in seen:
            continue
        seen.add(url)
        specs.append((label, url))

    headers = {
        "Cache-Control": "no-cache, no-store, max-age=0",
        "Pragma": "no-cache",
        "User-Agent": "Mozilla/5.0 (CosaNostraaDashboard-RakhiLive)",
        "Accept": "text/csv,text/plain,*/*",
    }

    def _fetch_one(idx, label, url):
        bust = ("&" if "?" in url else "?") + f"cachebust={int(time.time()*1000)}-{idx}"
        r = requests.get(url + bust, headers=headers, timeout=(5, 18), allow_redirects=True)
        r.raise_for_status()
        content = r.content
        if "<html" in content[:1024].decode("utf-8", errors="replace").lower():
            raise ValueError("HTML returned instead of CSV")
        try:
            df = pd.read_csv(io.BytesIO(content), dtype=str, on_bad_lines="skip",
                             encoding="utf-8", encoding_errors="replace")
        except TypeError:
            df = pd.read_csv(io.StringIO(content.decode("utf-8", errors="replace")),
                             dtype=str, on_bad_lines="skip")
        cols = list(df.columns)
        date_col = find_col(cols, "Date")
        order_col = find_col(cols, "Order No.", "Order No", "Order")
        sku_col = find_col(cols, "SKU No.", "SKU No", "SKU")
        qty_col = find_col(cols, "SUM of Qty.", "SUM of Qty", "Sum Qty", "Qty")
        if not all((date_col, order_col, sku_col, qty_col)):
            raise ValueError("required Rakhi inward columns not found")

        latest = None
        post_rows = 0
        post_qty = 0.0
        for _, row in df.iterrows():
            dt = parse_date_any(row.get(date_col))
            if dt is None:
                continue
            d = dt.date()
            if d > today_date:
                continue
            if latest is None or d > latest:
                latest = d
            if d > baseline_date:
                q = max(0.0, to_num(row.get(qty_col)))
                if q > 0:
                    post_rows += 1
                    post_qty += q
        rank = (
            latest.toordinal() if latest else -1,
            post_rows,
            int(round(post_qty)),
            int(len(df)),
        )
        return {
            "df": df,
            "label": label,
            "url": url,
            "rank": rank,
            "latest": latest,
            "post_rows": post_rows,
            "post_qty": int(round(post_qty)),
            "rows": int(len(df)),
        }

    results = []
    errors = []
    try:
        from concurrent.futures import ThreadPoolExecutor, as_completed
        with ThreadPoolExecutor(max_workers=max(1, min(4, len(specs))), thread_name_prefix="rakhi-inward") as ex:
            futures = {ex.submit(_fetch_one, i, label, url): (label, url) for i, (label, url) in enumerate(specs)}
            for fut in as_completed(futures):
                label, _url = futures[fut]
                try:
                    results.append(fut.result())
                except Exception as exc:
                    errors.append(f"{label}: {str(exc)[:180]}")
    except Exception:
        # Conservative fallback if thread creation is unavailable on a host.
        for i, (label, url) in enumerate(specs):
            try:
                results.append(_fetch_one(i, label, url))
            except Exception as exc:
                errors.append(f"{label}: {str(exc)[:180]}")

    if not results:
        raise ValueError("Rakhi inward source unavailable" + (": " + " | ".join(errors) if errors else ""))
    best = max(results, key=lambda x: x["rank"])
    return best["df"], {
        "source_mode": best["label"],
        "source_latest_date": best["latest"].isoformat() if best["latest"] else "",
        "source_latest_date_display": best["latest"].strftime("%d-%b-%Y") if best["latest"] else "",
        "source_candidate_count": len(results),
        "source_fetch_errors": errors,
    }


def _build_rakhi_receipts_after_aug6(force=False):
    """Aggregate the user's published Rakhi receiving sheet after 06-Aug-2026.

    Two views are returned:
      * by_sku: retained for diagnostics/other views.
      * by_order_sku: authoritative for the first Rakhi Production tracker.

    Matching is header-based and normalizes text/numeric Order No. and SKU values.
    Only receipt dates strictly after the 06-Aug-2026 baseline and not later than
    today (IST) are counted. The cache is deliberately short so the table keeps
    updating through the day; Refresh forces an immediate source fetch.
    """
    now_ts = time.time()
    cached = _RAKHI_RECEIPTS_CACHE.get("payload")
    if (
        not force and cached is not None and
        now_ts - float(_RAKHI_RECEIPTS_CACHE.get("ts") or 0) < _RAKHI_RECEIPTS_CACHE_TTL
    ):
        return cached

    today_date = now_ist().date()
    yesterday_date = today_date - timedelta(days=1)
    day_before_date = today_date - timedelta(days=2)
    baseline_date = datetime.strptime(_RAKHI_PRODUCTION_BASELINE_DATE, "%Y-%m-%d").date()
    payload = {
        "by_sku": {},
        "by_order_sku": {},
        "baseline_date": baseline_date.isoformat(),
        "today_iso": today_date.isoformat(),
        "yesterday_iso": yesterday_date.isoformat(),
        "day_before_iso": day_before_date.isoformat(),
        "today_display": today_date.strftime("%d-%b-%Y"),
        "yesterday_display": yesterday_date.strftime("%d-%b-%Y"),
        "day_before_display": day_before_date.strftime("%d-%b-%Y"),
        "source_ok": False,
        "source_rows": 0,
        "counted_rows": 0,
        "source_received_since_aug6": 0,
        "source_received_today": 0,
        "source_received_yesterday": 0,
        "source_received_day_before": 0,
        "error": "",
    }

    def _new_bucket():
        return {
            "received_since_aug6": 0.0,
            "received_today": 0.0,
            "received_yesterday": 0.0,
            "received_day_before": 0.0,
            "latest_date": None,
            "order_nos": set(),
            "daily": {},
            "rows": 0,
        }

    def _accumulate(bucket, receipt_date, qty, order_no):
        bucket["received_since_aug6"] += qty
        day_key = receipt_date.isoformat()
        bucket["daily"][day_key] = bucket["daily"].get(day_key, 0.0) + qty
        if receipt_date == today_date:
            bucket["received_today"] += qty
        elif receipt_date == yesterday_date:
            bucket["received_yesterday"] += qty
        elif receipt_date == day_before_date:
            bucket["received_day_before"] += qty
        if bucket["latest_date"] is None or receipt_date > bucket["latest_date"]:
            bucket["latest_date"] = receipt_date
        if order_no:
            bucket["order_nos"].add(order_no)
        bucket["rows"] += 1

    def _serialize(bucket):
        latest = bucket["latest_date"]
        order_nos = sorted(
            bucket["order_nos"],
            key=lambda x: (_rakhi_prod_order_rank(x) if _rakhi_prod_order_rank(x) is not None else -1, x),
        )
        return {
            "received_since_aug6": int(round(bucket["received_since_aug6"])),
            "received_today": int(round(bucket["received_today"])),
            "received_yesterday": int(round(bucket["received_yesterday"])),
            "received_day_before": int(round(bucket["received_day_before"])),
            "latest_receiving_date": latest.isoformat() if latest else "",
            "latest_receiving_date_display": latest.strftime("%d-%b-%Y") if latest else "",
            "order_nos": order_nos,
            "daily": {k: int(round(v)) for k, v in sorted(bucket["daily"].items())},
            "rows": int(bucket["rows"]),
        }

    try:
        df, source_meta = _fetch_rakhi_receipts_freshest(today_date)
        payload.update(source_meta)
        # Keep the ORIGINAL dataframe column objects/names. find_col() already
        # normalizes case/punctuation/spacing; stripping here would break r.get()
        # when a published CSV header itself contains leading/trailing spaces.
        cols = list(df.columns)
        date_col = find_col(cols, "Date")
        order_col = find_col(cols, "Order No.", "Order No", "Order")
        sku_col = find_col(cols, "SKU No.", "SKU No", "SKU")
        qty_col = find_col(cols, "SUM of Qty.", "SUM of Qty", "Sum Qty", "Qty")
        missing = [
            label for label, col in (("Date", date_col), ("Order No.", order_col), ("SKU No.", sku_col), ("SUM of Qty.", qty_col))
            if not col
        ]
        if missing:
            raise ValueError("Rakhi receiving sheet missing column(s): " + ", ".join(missing))

        payload["source_rows"] = int(len(df))
        work_sku = {}
        work_order_sku = {}
        for _, r in df.iterrows():
            dt = parse_date_any(r.get(date_col))
            if dt is None:
                continue
            receipt_date = dt.date()
            if receipt_date <= baseline_date or receipt_date > today_date:
                continue
            sku = _rakhi_prod_sku_key(r.get(sku_col))
            order_no = _rakhi_prod_order_key(r.get(order_col))
            qty = max(0.0, to_num(r.get(qty_col)))
            if not sku or not order_no or qty <= 0:
                continue

            _accumulate(work_sku.setdefault(sku, _new_bucket()), receipt_date, qty, order_no)
            exact_key = f"{order_no}||{sku}"
            _accumulate(work_order_sku.setdefault(exact_key, _new_bucket()), receipt_date, qty, order_no)
            payload["counted_rows"] += 1

        payload["by_sku"] = {sku: _serialize(g) for sku, g in work_sku.items()}
        payload["by_order_sku"] = {key: _serialize(g) for key, g in work_order_sku.items()}
        # Reconciliation totals from the source itself. Each CSV row belongs to
        # exactly one normalized Order No. + SKU bucket, so summing this view
        # reproduces the published Rakhi sheet total without clipping to plan or
        # current Production balance quantities.
        payload["source_received_since_aug6"] = int(round(sum(g["received_since_aug6"] for g in work_order_sku.values())))
        payload["source_received_today"] = int(round(sum(g["received_today"] for g in work_order_sku.values())))
        payload["source_received_yesterday"] = int(round(sum(g["received_yesterday"] for g in work_order_sku.values())))
        payload["source_received_day_before"] = int(round(sum(g["received_day_before"] for g in work_order_sku.values())))
        payload["source_ok"] = True
    except Exception as exc:
        payload["error"] = str(exc)

    _RAKHI_RECEIPTS_CACHE["payload"] = payload
    _RAKHI_RECEIPTS_CACHE["ts"] = now_ts
    return payload

def _production_has_balance(value):
    """Column K has a pending/difference value whenever it is not zero.

    Negative values are over-receipt differences, not completed rows.  Keeping
    them in the Balance=Yes view also makes the filtered K total reconcile with
    the Production sheet's own K-column total.
    """
    try:
        return abs(float(value or 0)) > 1e-9
    except (TypeError, ValueError):
        return False

def _build_production(channel_filter="", sku_query="", od1="", od2="", dd1="", dd2="", taxon_filter="", type_filter="", balance_only="", order_query="", sort_mode="", cn_query="", row_limit=1000):
    # SKU -> image + taxon + AOV/discount map (compiled data se)
    img_map = {}; tax_map = {}; aov_map = {}; disc_map = {}; stone_map = {}; cn_map = {}
    stock_map = {}; stock_3p_map = {}; wip_map = {}; wip_website_map = {}; wip_designer_map = {}; wip_customer_map = {}; wip_customize_map = {}; wip_sor_map = {}
    try:
        comp = get_data()[0]
        for it in comp:
            sk = str(it.get("sku", "")).strip().upper()
            if not sk:
                continue
            if it.get("image_url"):
                img_map[sk] = it["image_url"]
            if it.get("taxon"):
                tax_map[sk] = it["taxon"]
            aov_map[sk] = it.get("aov_per_piece", 0) or 0
            disc_map[sk] = it.get("discount_pct", 0) or 0
            stone_map[sk] = it.get("stone_color", "") or ""
            cn_map[sk] = it.get("cn_name", "") or ""
            stock_map[sk] = it.get("inv_stock", 0) or 0
            if it.get("inv_stock_3p") is not None:
                stock_3p_map[sk] = it.get("inv_stock_3p", 0) or 0
            wip_map[sk] = it.get("inv_wip", 0) or 0
            wip_website_map[sk] = it.get("inv_wip_website", 0) or 0
            wip_designer_map[sk] = it.get("inv_wip_designer", 0) or 0
            wip_customer_map[sk] = it.get("inv_wip_customer", 0) or 0
            wip_customize_map[sk] = it.get("inv_wip_customize", 0) or 0
            wip_sor_map[sk] = it.get("inv_wip_sor", 0) or 0
    except Exception:
        pass

    def _prod_meta_key(sku):
        key = str(sku or "").strip().upper()
        return _inventory_resolve_key(key, stock_map) or key

    # Production sheet fetch (60 sec live-sync cache; manual Refresh still forces a fresh fetch)
    if _PROD_CACHE["rows"] is not None and (time.time() - _PROD_CACHE["ts"] < 60):
        rows_all = _PROD_CACHE["rows"]
    else:
        df = _fetch_csv_fresh(PRODUCTION_URL)
        cols = list(df.columns)
        def _at(i): return cols[i] if len(cols) > i else None
        C_DATE = _at(0)   # A  Date (order date)
        C_ORD  = _at(1)   # B  Order No.
        C_TYPE = _at(5)   # F  Order Type
        C_CHAN = _at(6)   # G  Channel
        C_SKU  = _at(7)   # H  SKU No.   (E/Image link nahi)
        C_OQTY = _at(8)   # I  Order Qty
        C_RQTY = _at(9)   # J  Recv Qty
        # Balance Qty is authoritative only from physical column K. Do not
        # derive it from Order Qty - Received Qty or fall back to another header.
        C_BQTY = _at(10)  # K  Bal. Qty.
        if C_BQTY is None:
            raise ValueError("Production sheet column K (Balance Qty) is missing")
        C_DELV = _at(11)  # L  Delivery Date
        C_RECV = _at(12)  # M  Receiving Date
        rows_all = []
        _seen_rows = set()
        for _, r in df.iterrows():
            sku = clean(r.get(C_SKU, "")).upper() if C_SKU else ""
            order_no = clean(r.get(C_ORD, "")) if C_ORD else ""
            if not sku and not order_no:
                continue
            dt = parse_date_any(r.get(C_DATE, "")) if C_DATE else None
            dv = parse_date_any(r.get(C_DELV, "")) if C_DELV else None
            rv = parse_date_any(r.get(C_RECV, "")) if C_RECV else None
            row = {
                "date":      dt.strftime("%Y-%m-%d") if dt else "",
                "date_disp": dt.strftime("%d-%b-%Y") if dt else "",
                "order_no":  order_no,
                "sku":       sku,
                "order_type": _marketplace_display_text(r.get(C_TYPE, "")) if C_TYPE else "",
                "channel":   _marketplace_display_text(r.get(C_CHAN, "")) if C_CHAN else "",
                "order_qty": to_num(r.get(C_OQTY, 0)) if C_OQTY else 0.0,
                "recv_qty":  to_num(r.get(C_RQTY, 0)) if C_RQTY else 0.0,
                "bal_qty":   to_num(r.get(C_BQTY, 0)) if C_BQTY else 0.0,
                "delivery_date": dv.strftime("%d-%b-%Y") if dv else "",
                "delivery_iso":  dv.strftime("%Y-%m-%d") if dv else "",
                "receiving_date": rv.strftime("%d-%b-%Y") if rv else "",
                "receiving_iso": rv.strftime("%Y-%m-%d") if rv else "",
            }
            # Exact-duplicate row (same date+order no+sku+everything) — skip repeats
            dedup_key = tuple(row[k] for k in (
                "date", "order_no", "sku", "order_type", "channel",
                "order_qty", "recv_qty", "bal_qty", "delivery_date", "receiving_date"))
            if dedup_key in _seen_rows:
                continue
            _seen_rows.add(dedup_key)
            rows_all.append(row)
        _PROD_CACHE["rows"] = rows_all
        _PROD_CACHE["ts"] = time.time()

    # Taxon har row me daal do (inv map se)
    for r in rows_all:
        r["taxon"] = tax_map.get(_prod_meta_key(r["sku"]), "")

    # Filter dropdown options
    channels = sorted({r["channel"] for r in rows_all if r["channel"]})
    types    = sorted({r["order_type"] for r in rows_all if r["order_type"]})
    taxons   = sorted({r["taxon"] for r in rows_all if r["taxon"]})

    # SKU -> total order history, plus only order numbers having a non-zero
    # balance. The Yes filter is based exclusively on physical column K.
    sku_orders = {}
    sku_pending_orders = {}
    for r in rows_all:
        if r["sku"] and r["order_no"]:
            sku_orders.setdefault(r["sku"], [])
            if r["order_no"] not in sku_orders[r["sku"]]:
                sku_orders[r["sku"]].append(r["order_no"])
            if _production_has_balance(r.get("bal_qty")):
                sku_pending_orders.setdefault(r["sku"], [])
                if r["order_no"] not in sku_pending_orders[r["sku"]]:
                    sku_pending_orders[r["sku"]].append(r["order_no"])

    # SKU -> uss SKU ki saare orders ki Balance Qty jodke total (sab orders mil ke)
    sku_total_balance = {}
    for r in rows_all:
        if r["sku"]:
            sku_total_balance[r["sku"]] = sku_total_balance.get(r["sku"], 0) + (r["bal_qty"] or 0)

    # Filters apply
    cf = channel_filter.strip().lower()
    sq = sku_query.strip().lower()
    oq = order_query.strip().lower()
    cnq = cn_query.strip().lower()
    if isinstance(taxon_filter, (list, tuple, set)):
        txfs = {str(v).strip().lower() for v in taxon_filter if str(v).strip()}
    else:
        txfs = {v.strip().lower() for v in str(taxon_filter or '').split('|||') if v.strip()}
    tyf = type_filter.strip().lower()
    bo = (balance_only or "").strip().lower()   # "yes" = K != 0, "no" = K == 0
    inv_filter_ctx = (cf or tyf).strip()
    def _prod_inv_stock(sku):
        # Blank channel/type filter = normal overall inventory. SOR/3P channels
        # use the All Product sheet's "Inv. Stock _3P" when it exists.
        if inv_filter_ctx and ("sor" in inv_filter_ctx or "marketplace" in inv_filter_ctx or "3p" in inv_filter_ctx):
            k = _prod_meta_key(sku)
            return stock_3p_map.get(k, stock_map.get(k, 0)) or 0
        k = _prod_meta_key(sku)
        return stock_map.get(k, 0) or 0

    def _prod_inv_wip(sku):
        k = _prod_meta_key(sku)
        if inv_filter_ctx:
            if "website" in inv_filter_ctx:
                return wip_website_map.get(k, 0) or 0
            if "designer" in inv_filter_ctx:
                return wip_designer_map.get(k, 0) or 0
            if "customize" in inv_filter_ctx or "customise" in inv_filter_ctx:
                return wip_customize_map.get(k, 0) or 0
            if "customer" in inv_filter_ctx:
                return wip_customer_map.get(k, 0) or 0
            if "sor" in inv_filter_ctx or "marketplace" in inv_filter_ctx or "3p" in inv_filter_ctx:
                return wip_sor_map.get(k, 0) or 0
        return wip_map.get(k, 0) or 0
    rows = []
    for r in rows_all:
        if cf and r["channel"].strip().lower() != cf:
            continue
        if tyf and r["order_type"].strip().lower() != tyf:
            continue
        if txfs and r["taxon"].strip().lower() not in txfs:
            continue
        if bo == "yes" and not _production_has_balance(r.get("bal_qty")):
            continue
        if bo == "no" and _production_has_balance(r.get("bal_qty")):
            continue
        if sq and sq not in r["sku"].lower():
            continue
        if oq and oq not in r["order_no"].lower():
            continue
        if cnq and cnq not in str(cn_map.get(_prod_meta_key(r["sku"]), "")).lower():
            continue
        # Order date range
        if od1 and (not r["date"] or r["date"] < od1):
            continue
        if od2 and (not r["date"] or r["date"] > od2):
            continue
        # Delivery date range
        if dd1 and (not r["delivery_iso"] or r["delivery_iso"] < dd1):
            continue
        if dd2 and (not r["delivery_iso"] or r["delivery_iso"] > dd2):
            continue
        rr = dict(r)
        _meta_key = _prod_meta_key(r["sku"])
        rr["image_url"] = img_map.get(_meta_key, "")
        # Existing frontend/export field name is kept for compatibility, but
        # its contents are intentionally pending-only order numbers.
        rr["all_orders"] = sku_pending_orders.get(r["sku"], [])
        rr["pending_order_count"] = len(sku_pending_orders.get(r["sku"], []))
        rr["sku_total_balance"] = sku_total_balance.get(r["sku"], 0)
        rr["sku_name"] = cn_sku_label(r["sku"])
        rr["cn_name"] = cn_map.get(_meta_key, "")
        rr["stone_color"] = stone_map.get(_meta_key, "")
        rr["inv_stock"] = _prod_inv_stock(r["sku"])
        rr["inv_wip"] = _prod_inv_wip(r["sku"])
        rr["repeat_count"] = len(sku_orders.get(r["sku"], []))   # kitni baar order hua (distinct orders)
        # AOV/Discount% — revenue-sensitive, employee ko 0 (jaisa baaki app me hai)
        if session.get("role") == "employee":
            rr["aov_per_piece"] = 0
            rr["discount_pct"] = 0
        else:
            rr["aov_per_piece"] = aov_map.get(_meta_key, 0)
            rr["discount_pct"] = disc_map.get(_meta_key, 0)
        rows.append(rr)

    # Preserve exact filtered-source totals BEFORE optional grouping and before
    # the API display cap. This keeps KPI cards/export totals identical even
    # when more than 1,000 Production rows match the filters.
    _filtered_source_rows = len(rows)
    _filtered_total_order_qty = sum((r.get("order_qty", 0) or 0) for r in rows)
    _filtered_total_recv_qty = sum((r.get("recv_qty", 0) or 0) for r in rows)
    _filtered_total_bal_qty = sum((r.get("bal_qty", 0) or 0) for r in rows)
    _filtered_pending_rows = sum(1 for r in rows if _production_has_balance(r.get("bal_qty")))
    _filtered_unique_orders = len({r.get("order_no") for r in rows if r.get("order_no")})
    _filtered_unique_skus = len({r.get("sku") for r in rows if r.get("sku")})

    # SORT / GROUP: "top_repeat" = SKU-wise group (ek SKU ek row), uske totals,
    # sabse zyada baar order hue SKU pehle (zyada -> kam).
    if (sort_mode or "").strip().lower() == "top_repeat":
        grp = {}
        for r in rows:
            sk = r["sku"]
            if not sk:
                continue
            g = grp.get(sk)
            if g is None:
                g = grp[sk] = {
                    "sku": sk,
                    "sku_name": r.get("sku_name", ""),
                    "image_url": r.get("image_url", ""),
                    "taxon": r.get("taxon", ""),
                    "stone_color": r.get("stone_color", ""),
                    "order_type": r.get("order_type", ""),
                    "channel": r.get("channel", ""),
                    "aov_per_piece": r.get("aov_per_piece", 0) or 0,
                    "discount_pct": r.get("discount_pct", 0) or 0,
                    "inv_stock": r.get("inv_stock", 0) or 0,
                    "inv_wip": r.get("inv_wip", 0) or 0,
                    "order_qty": 0.0, "recv_qty": 0.0, "bal_qty": 0.0,
                    "all_orders": r.get("all_orders", []),
                    "pending_order_count": r.get("pending_order_count", 0),
                    "sku_total_balance": r.get("sku_total_balance", 0),
                    "repeat_count": r.get("repeat_count", 0),
                    "date": "", "date_disp": "", "order_no": "",
                    "delivery_date": "", "delivery_iso": "",
                    "receiving_date": "", "receiving_iso": "",
                    "_dates": [],
                }
            g["order_qty"] += r.get("order_qty", 0) or 0
            g["recv_qty"]  += r.get("recv_qty", 0) or 0
            g["bal_qty"]   += r.get("bal_qty", 0) or 0
            if r.get("date"):
                g["_dates"].append((r["date"], r.get("date_disp", "")))
        grouped = list(grp.values())
        for g in grouped:
            ds = sorted([x for x in g.pop("_dates", []) if x[0]])
            g["date_disp"] = ds[0][1] if ds else ""   # earliest order date (display)
            g["order_no"] = f'{g["repeat_count"]} orders'
        grouped.sort(key=lambda r: (r.get("repeat_count", 0), r.get("order_qty", 0)), reverse=True)
        rows = grouped

    # KPIs use the complete filtered source set captured before grouping/capping.
    grouped_mode = (sort_mode or "").strip().lower() == "top_repeat"
    if row_limit is None:
        output_rows = rows
    else:
        try:
            safe_limit = max(0, int(row_limit))
        except Exception:
            safe_limit = 1000
        output_rows = rows[:safe_limit]
    return {
        "rows": output_rows,
        "count": len(rows),
        "filtered_source_rows": _filtered_source_rows,
        "returned_count": len(output_rows),
        "grouped": grouped_mode,
        "channels": channels, "types": types, "taxons": taxons,
        "total_order_qty": int(round(_filtered_total_order_qty)),
        "total_recv_qty":  int(round(_filtered_total_recv_qty)),
        "total_bal_qty":   int(round(_filtered_total_bal_qty)),
        "pending_rows": _filtered_pending_rows,
        "unique_orders": _filtered_unique_orders,
        "unique_skus": _filtered_unique_skus,
    }


def _build_rakhi_production_tracker(force_rakhi_receipts=False):
    """Join the supplied Aug-2026 need-by plan to the live Production sheet.

    The supplied file provides the August need-by plan and the 06-Aug Balance
    Qty baseline. Baseline orders count only the subsequent Balance Qty drop;
    newer Rakhi production orders use their live column-J Rec. Qty. Production
    delivery date is taken from column L.
    """
    report = _build_production(row_limit=None)
    live_rows = list(report.get("rows") or [])
    rakhi_receipts = _build_rakhi_receipts_after_aug6(force=force_rakhi_receipts)

    # Snapshot lookup: the uploaded 06-Aug file is the baseline.  For order+SKU
    # rows that already existed in that file, only the Balance Qty drop after
    # the snapshot counts as newly received.  Newer production orders for the
    # same SKU (for example Rakhi repeat orders 1427 / 1428) use their live
    # column-J Rec. Qty because they were not part of the baseline snapshot.
    baseline_balance_by_key = {}
    baseline_latest_order_rank_by_sku = {}
    rakhi_direct_baseline_ranks = []
    for raw in _RAKHI_PRODUCTION_PLAN:
        _od, _ono, _sku, _qty, _baseline_balance, _priority, _need = raw
        _ok = _rakhi_prod_order_key(_ono)
        _sk = _rakhi_prod_sku_key(_sku)
        if not _ok or not _sk:
            continue
        _key = (_ok, _sk)
        baseline_balance_by_key[_key] = max(
            baseline_balance_by_key.get(_key, 0.0), float(_baseline_balance or 0)
        )
        _rank = _rakhi_prod_order_rank(_ono)
        if _rank is not None:
            baseline_latest_order_rank_by_sku[_sk] = max(
                baseline_latest_order_rank_by_sku.get(_sk, _rank), _rank
            )
            if _sk.startswith("RKH"):
                rakhi_direct_baseline_ranks.append(_rank)
    rakhi_direct_baseline_rank = max(rakhi_direct_baseline_ranks) if rakhi_direct_baseline_ranks else None

    # Per-SKU production inflow for the SKU performance table.  Receiving Qty
    # is attributed to its Receiving Date.  Production / Day is the last seven
    # calendar days divided by seven, including zero-receipt days.
    production_by_sku = {}
    today_date = now_ist().date()
    start_7d = today_date - timedelta(days=6)
    for r in live_rows:
        sk = _rakhi_prod_sku_key(r.get("sku", ""))
        if not sk:
            continue
        g = production_by_sku.setdefault(sk, {
            "received_total": 0.0, "received_7d": 0.0, "received_today": 0.0,
            "pending_balance": 0.0, "avg_received_per_day_7d": 0.0,
            "delivery_dates": set(), "receiving_dates": set(),
        })
        try:
            recv_qty = max(0.0, float(r.get("recv_qty") or 0))
        except (TypeError, ValueError):
            recv_qty = 0.0
        # User-confirmed source for received quantity: physical Production column J (Rec. Qty.).
        g["received_total"] += recv_qty
        try:
            g["pending_balance"] += max(0.0, float(r.get("bal_qty") or 0))
        except (TypeError, ValueError):
            pass
        delivery_iso = clean(r.get("delivery_iso", ""))
        delivery_disp = clean(r.get("delivery_date", ""))
        if delivery_iso or delivery_disp:
            g["delivery_dates"].add((delivery_iso, delivery_disp or delivery_iso))
        recv_iso = clean(r.get("receiving_iso", ""))
        recv_disp = clean(r.get("receiving_date", ""))
        if recv_iso or recv_disp:
            g["receiving_dates"].add((recv_iso, recv_disp or recv_iso))
        recv_date = None
        if recv_iso:
            try:
                recv_date = datetime.strptime(recv_iso[:10], "%Y-%m-%d").date()
            except Exception:
                recv_date = None
        if recv_date is not None and start_7d <= recv_date <= today_date:
            g["received_7d"] += recv_qty
        if recv_date == today_date:
            g["received_today"] += recv_qty
    for g in production_by_sku.values():
        g["received_total"] = int(round(g["received_total"]))
        g["received_7d"] = int(round(g["received_7d"]))
        g["received_today"] = int(round(g["received_today"]))
        g["pending_balance"] = int(round(g["pending_balance"]))
        g["avg_received_per_day_7d"] = round(g["received_7d"] / 7.0, 2)
        delivery_pairs = sorted(g.pop("delivery_dates", set()), key=lambda x: (x[0] or "9999-99-99", x[1]))
        g["delivery_dates"] = [d[1] for d in delivery_pairs]
        g["delivery_date_display"] = ", ".join(g["delivery_dates"])
        receiving_pairs = sorted(g.pop("receiving_dates", set()), key=lambda x: (x[0] or "0000-00-00", x[1]))
        g["receiving_dates"] = [d[1] for d in receiving_pairs]
        g["receiving_date_display"] = receiving_pairs[-1][1] if receiving_pairs else ""

    # All Product CN Name is used for display; the plan remains SKU-driven.
    # Image shown in the tracker comes from the uploaded Excel Image Link first;
    # All Product is only a fallback when the Excel image is unavailable.
    cn_map = {}
    master_image_map = {}
    master_sku_display_map = {}
    try:
        for it in get_data()[0]:
            sk = _rakhi_prod_sku_key(it.get("sku", ""))
            if sk:
                cn_map[sk] = clean(it.get("cn_name", ""))
                master_image_map[sk] = clean(it.get("image_url", ""))
                master_sku_display_map[sk] = clean(it.get("sku", "")).upper() or sk
    except Exception:
        pass

    live = {}
    for r in live_rows:
        key = (_rakhi_prod_order_key(r.get("order_no", "")), _rakhi_prod_sku_key(r.get("sku", "")))
        if not key[0] or not key[1]:
            continue
        g = live.setdefault(key, {
            "order_no_display": key[0] if re.fullmatch(r"\d+", key[0]) else (clean(r.get("order_no", "")) or key[0]),
            "sku_display": (f"RKH-{key[1][3:]}" if key[1].startswith("RKH") and key[1][3:].isdigit() else (clean(r.get("sku", "")).upper() or key[1])),
            "balance": 0.0, "recv": 0.0, "order_qty": 0.0, "max_order_qty": 0.0,
            "has_positive_balance": False, "max_positive_balance": 0.0,
            "receiving_dates": set(), "receiving_pairs": set(),
            "delivery_dates": set(), "delivery_pairs": set(),
            "order_dates": set(), "order_types": set(), "channels": set(), "rows": 0,
        })
        try:
            _row_bal = float(r.get("bal_qty") or 0)
        except (TypeError, ValueError):
            _row_bal = 0.0
        try:
            _row_order_qty = max(0.0, float(r.get("order_qty") or 0))
        except (TypeError, ValueError):
            _row_order_qty = 0.0
        g["balance"] += _row_bal
        g["recv"] += float(r.get("recv_qty") or 0)
        g["order_qty"] += _row_order_qty
        g["max_order_qty"] = max(float(g.get("max_order_qty") or 0.0), _row_order_qty)
        if _row_bal > 0:
            g["has_positive_balance"] = True
            g["max_positive_balance"] = max(float(g.get("max_positive_balance") or 0.0), _row_bal)
        g["rows"] += 1
        if r.get("date") or r.get("date_disp"):
            g["order_dates"].add((str(r.get("date") or ""), str(r.get("date_disp") or r.get("date") or "")))
        if r.get("receiving_date"):
            g["receiving_dates"].add(str(r.get("receiving_date")))
        if r.get("receiving_iso") or r.get("receiving_date"):
            g["receiving_pairs"].add((str(r.get("receiving_iso") or ""), str(r.get("receiving_date") or r.get("receiving_iso") or "")))
        if r.get("delivery_date"):
            g["delivery_dates"].add(str(r.get("delivery_date")))
        if r.get("delivery_iso") or r.get("delivery_date"):
            g["delivery_pairs"].add((str(r.get("delivery_iso") or ""), str(r.get("delivery_date") or r.get("delivery_iso") or "")))
        if r.get("order_type"):
            g["order_types"].add(str(r.get("order_type")))
        if r.get("channel"):
            g["channels"].add(str(r.get("channel")))

    # Production Balance Qty for the first tracker is based on physical PPC-WIP
    # column K. If the same SKU appears more than once on the same Order Date,
    # take only that date/SKU's highest positive balance and later divide that
    # single pool across the matching tracker rows. This prevents repeated live
    # quantities (for example 1000 / 1000 / 1000) from being triple-counted.
    production_balance_max_by_date_sku = {}
    for _pr in live_rows:
        _sk = _rakhi_prod_sku_key(_pr.get("sku", ""))
        _dt = clean(_pr.get("date", ""))
        if not _sk or not _dt:
            continue
        try:
            _bal = max(0.0, float(_pr.get("bal_qty") or 0.0))
        except (TypeError, ValueError):
            _bal = 0.0
        _pb_key = (_dt, _sk)
        production_balance_max_by_date_sku[_pb_key] = max(
            production_balance_max_by_date_sku.get(_pb_key, 0.0), _bal
        )

    # Replace historical cumulative Rec. Qty with only post-baseline receipts.
    # Existing baseline orders: new received = baseline Balance - current Balance.
    # Orders absent from the baseline: count live J only when the order number is
    # newer than that SKU's baseline order. For component SKUs that were not in
    # the baseline file, require a Rakhi-labelled production order and compare
    # against the latest direct-Rakhi baseline order. This excludes old customer /
    # Marketplace receipts such as historical rows while automatically including 1427,
    # 1428 and future Rakhi repeat orders.
    post_receipts_by_sku = {}
    for (order_key, sk), lv in live.items():
        post_qty = 0.0
        if (order_key, sk) in baseline_balance_by_key:
            base_bal = max(0.0, float(baseline_balance_by_key.get((order_key, sk), 0.0) or 0.0))
            current_bal = float(lv.get("balance") or 0.0)
            post_qty = max(0.0, base_bal - current_bal)
        else:
            order_rank = _rakhi_prod_order_rank(order_key)
            sku_cutoff = baseline_latest_order_rank_by_sku.get(sk)
            rakhi_text = " ".join(list(lv.get("order_types") or []) + list(lv.get("channels") or [])).casefold()
            is_new_for_known_sku = (
                order_rank is not None and sku_cutoff is not None and order_rank > sku_cutoff
            )
            is_new_rakhi_component = (
                order_rank is not None and sku_cutoff is None
                and rakhi_direct_baseline_rank is not None
                and order_rank > rakhi_direct_baseline_rank
                and "rakhi" in rakhi_text
            )
            if is_new_for_known_sku or is_new_rakhi_component:
                post_qty = max(0.0, float(lv.get("recv") or 0.0))
        if post_qty <= 1e-9:
            continue
        pg = post_receipts_by_sku.setdefault(sk, {
            "received_total": 0.0, "received_7d": 0.0, "received_today": 0.0,
            "receiving_pairs": set(), "order_nos": set(),
        })
        pg["received_total"] += post_qty
        pg["order_nos"].add(order_key)
        pairs = sorted(lv.get("receiving_pairs") or set(), key=lambda x: (x[0] or "0000-00-00", x[1]))
        if pairs:
            latest_pair = pairs[-1]
            pg["receiving_pairs"].add(latest_pair)
            try:
                rec_date = datetime.strptime(latest_pair[0][:10], "%Y-%m-%d").date() if latest_pair[0] else None
            except Exception:
                rec_date = None
            if rec_date is not None and start_7d <= rec_date <= today_date:
                pg["received_7d"] += post_qty
            if rec_date == today_date:
                pg["received_today"] += post_qty

    # Overwrite only the receipt-related fields; keep existing delivery/pending
    # calculations unchanged.
    for sk, g in production_by_sku.items():
        pg = post_receipts_by_sku.get(sk)
        if not pg:
            g["received_total"] = 0
            g["received_7d"] = 0
            g["received_today"] = 0
            g["avg_received_per_day_7d"] = 0.0
            g["receiving_dates"] = []
            g["receiving_date_display"] = ""
            g["received_order_nos"] = []
            continue
        g["received_total"] = int(round(pg["received_total"]))
        g["received_7d"] = int(round(pg["received_7d"]))
        g["received_today"] = int(round(pg["received_today"]))
        g["avg_received_per_day_7d"] = round(g["received_7d"] / 7.0, 2)
        pairs = sorted(pg["receiving_pairs"], key=lambda x: (x[0] or "0000-00-00", x[1]))
        g["receiving_dates"] = [p[1] for p in pairs]
        g["receiving_date_display"] = pairs[-1][1] if pairs else ""
        g["received_order_nos"] = sorted(pg["order_nos"], key=lambda x: (_rakhi_prod_order_rank(x) or -1, x))

    groups = {}
    for seq, raw in enumerate(_RAKHI_PRODUCTION_PLAN):
        order_date, order_no, sku, qty_required, baseline_balance, priority, need_by_text = raw
        need_iso = _rakhi_prod_need_by_iso(need_by_text)
        key = (_rakhi_prod_order_key(order_no), _rakhi_prod_sku_key(sku))
        # First Rakhi Production tracker: every direct RKH SKU is due on 13-Aug-2026.
        if key[1].startswith("RKH"):
            need_iso = "2026-08-13"
            need_by_text = "Need By 13th"
        if not key[0] or not key[1] or not need_iso:
            continue
        g = groups.setdefault(key, {
            "order_no": str(order_no), "sku": str(sku).upper(),
            "baseline_balance": 0.0, "plan_total": 0.0, "parts": [],
        })
        g["baseline_balance"] = max(g["baseline_balance"], float(baseline_balance or 0))
        g["plan_total"] += max(0.0, float(qty_required or 0))
        g["parts"].append({
            "seq": seq, "order_date": str(order_date or ""),
            "qty_required": max(0.0, float(qty_required or 0)),
            "priority": str(priority or ""), "need_by_text": str(need_by_text or ""),
            "need_by_iso": need_iso, "source": "plan",
        })

    # Keep every supplied Production Data plan row, then add every LIVE PPC-WIP
    # order+SKU not already in that file when physical column K has a positive
    # Balance Qty. This is intentionally not RKH-only: other running production
    # orders are also visible. RKH rows are due 13-Aug; non-RKH rows through
    # Order No. 1435 are due 31-Aug; later order numbers have blank Need By.
    live_rakhi_added = 0
    live_other_added = 0
    for key, lv in live.items():
        order_key, sku_key = key
        if key in groups or not order_key or not sku_key:
            continue
        if not bool(lv.get("has_positive_balance")):
            continue
        try:
            live_order_qty = max(0.0, float(lv.get("max_order_qty") or 0.0))
        except (TypeError, ValueError):
            live_order_qty = 0.0
        try:
            live_positive_balance = max(0.0, float(lv.get("max_positive_balance") or 0.0))
        except (TypeError, ValueError):
            live_positive_balance = 0.0
        # For rows that are NOT in the supplied Production Data Excel, Qty Required
        # must represent the CURRENT outstanding production requirement. Therefore
        # use physical PPC-WIP Balance Qty (column K), not the original Order Qty.
        live_required_qty = live_positive_balance
        if live_required_qty <= 1e-9:
            continue

        order_pairs = sorted(
            lv.get("order_dates") or set(),
            key=lambda x: (x[0] or "9999-99-99", x[1]),
        )
        order_date_iso = order_pairs[0][0] if order_pairs else ""
        need_iso, need_text = _rakhi_prod_live_need_by(sku_key, order_key)
        is_rakhi = sku_key.startswith("RKH")
        seq_offset = live_rakhi_added + live_other_added
        groups[key] = {
            "order_no": clean(lv.get("order_no_display", "")) or order_key,
            "sku": clean(lv.get("sku_display", "")).upper() or sku_key,
            "baseline_balance": 0.0,
            "plan_total": live_required_qty,
            "parts": [{
                "seq": 1000000 + seq_offset,
                "order_date": order_date_iso,
                "qty_required": live_required_qty,
                "priority": "Live Production",
                "need_by_text": need_text,
                "need_by_iso": need_iso,
                "source": "live_production",
            }],
        }
        if is_rakhi:
            live_rakhi_added += 1
        else:
            live_other_added += 1

    # A receiving row can belong to an order/SKU that is no longer pending in
    # PPC-WIP (Balance Qty has already reached 0) and may also be absent from the
    # supplied planning Excel. Those receipts were previously dropped from the
    # first table, which made daily totals smaller than the authoritative Rakhi
    # receiving sheet. Add a zero-requirement receipt-only tracker row for every
    # such exact normalized Order No. + SKU so Today/Yesterday/Day Before always
    # reconcile to the source. Existing plan/live rows are never duplicated.
    exact_receipts = rakhi_receipts.get("by_order_sku") or {}
    receipt_only_rows_added = 0
    for _receipt_key, _rc in exact_receipts.items():
        _receipt_key = clean(_receipt_key)
        if "||" not in _receipt_key:
            continue
        _order_key, _sku_key = _receipt_key.split("||", 1)
        _order_key = _rakhi_prod_order_key(_order_key)
        _sku_key = _rakhi_prod_sku_key(_sku_key)
        _key = (_order_key, _sku_key)
        if not _order_key or not _sku_key or _key in groups:
            continue
        if float((_rc or {}).get("received_since_aug6") or 0) <= 0:
            continue
        _lv = live.get(_key)
        _order_pairs = sorted(
            (_lv.get("order_dates") or set()) if _lv else set(),
            key=lambda x: (x[0] or "9999-99-99", x[1]),
        )
        _order_date_iso = _order_pairs[0][0] if _order_pairs else ""
        _need_iso, _need_text = _rakhi_prod_live_need_by(_sku_key, _order_key)
        _order_display = (clean(_lv.get("order_no_display", "")) if _lv else "") or _order_key
        _sku_display = (clean(_lv.get("sku_display", "")).upper() if _lv else "") or master_sku_display_map.get(_sku_key, _sku_key)
        groups[_key] = {
            "order_no": _order_display,
            "sku": _sku_display,
            "baseline_balance": 0.0,
            "plan_total": 0.0,
            "parts": [{
                "seq": 2000000 + receipt_only_rows_added,
                "order_date": _order_date_iso,
                "qty_required": 0.0,
                "priority": "Received / Completed",
                "need_by_text": _need_text,
                "need_by_iso": _need_iso,
                "source": "receipt_only",
            }],
        }
        receipt_only_rows_added += 1

    out = []
    today_iso = now_ist().date().isoformat()
    receipt_meta = {k: v for k, v in rakhi_receipts.items() if k not in ("by_sku", "by_order_sku")}
    exact_receipts = rakhi_receipts.get("by_order_sku") or {}
    receipt_source_ok = bool(rakhi_receipts.get("source_ok"))
    today_receipt_iso = clean(rakhi_receipts.get("today_iso", ""))
    yesterday_receipt_iso = clean(rakhi_receipts.get("yesterday_iso", ""))
    day_before_receipt_iso = clean(rakhi_receipts.get("day_before_iso", ""))

    for key, g in groups.items():
        lv = live.get(key)
        source_found = lv is not None
        live_balance = float(lv.get("balance") or 0) if lv else 0.0
        parts = sorted(g["parts"], key=lambda p: (p.get("need_by_iso") or "9999-12-31", p["seq"]))

        # The live Rakhi receiving sheet is authoritative for arrivals in this
        # first table. Match by exact normalized Order No. + SKU, then allocate
        # each receipt day to the earliest still-open need-by tranche. This keeps
        # repeated order/SKU plan rows from displaying the same receipt twice.
        receipt_key = f"{key[0]}||{key[1]}"
        rc = exact_receipts.get(receipt_key) or {}
        part_stats = [
            {"arrived": 0.0, "today": 0.0, "yesterday": 0.0, "day_before": 0.0, "latest_iso": ""}
            for _ in parts
        ]
        if receipt_source_ok:
            for receipt_iso, raw_qty in sorted((rc.get("daily") or {}).items()):
                try:
                    remaining_day_qty = max(0.0, float(raw_qty or 0))
                except (TypeError, ValueError):
                    remaining_day_qty = 0.0
                if remaining_day_qty <= 0:
                    continue
                for idx, p in enumerate(parts):
                    capacity = max(0.0, float(p["qty_required"] or 0) - part_stats[idx]["arrived"])
                    if capacity <= 1e-9:
                        continue
                    take = min(capacity, remaining_day_qty)
                    if take <= 0:
                        continue
                    part_stats[idx]["arrived"] += take
                    if receipt_iso == today_receipt_iso:
                        part_stats[idx]["today"] += take
                    elif receipt_iso == yesterday_receipt_iso:
                        part_stats[idx]["yesterday"] += take
                    elif receipt_iso == day_before_receipt_iso:
                        part_stats[idx]["day_before"] += take
                    if receipt_iso > part_stats[idx]["latest_iso"]:
                        part_stats[idx]["latest_iso"] = receipt_iso
                    remaining_day_qty -= take
                    if remaining_day_qty <= 1e-9:
                        break
                # Never discard valid source receipts just because the current
                # plan/balance capacity is smaller (or zero after completion).
                # Put any over-receipt / already-completed remainder on the last
                # tranche so the sum of displayed receipt columns equals the
                # published Rakhi receiving sheet exactly.
                if remaining_day_qty > 1e-9 and part_stats:
                    _idx = len(part_stats) - 1
                    part_stats[_idx]["arrived"] += remaining_day_qty
                    if receipt_iso == today_receipt_iso:
                        part_stats[_idx]["today"] += remaining_day_qty
                    elif receipt_iso == yesterday_receipt_iso:
                        part_stats[_idx]["yesterday"] += remaining_day_qty
                    elif receipt_iso == day_before_receipt_iso:
                        part_stats[_idx]["day_before"] += remaining_day_qty
                    if receipt_iso > part_stats[_idx]["latest_iso"]:
                        part_stats[_idx]["latest_iso"] = receipt_iso
        else:
            # Source outage fallback only: preserve the old baseline Balance-drop
            # logic so the tracker remains usable, but daily buckets stay blank/0.
            fallback_received = max(0.0, g["baseline_balance"] - live_balance) if source_found else 0.0
            fallback_received = min(fallback_received, g["plan_total"])
            remaining_fallback = fallback_received
            for idx, p in enumerate(parts):
                take = min(float(p["qty_required"] or 0), remaining_fallback)
                part_stats[idx]["arrived"] = max(0.0, take)
                remaining_fallback = max(0.0, remaining_fallback - take)

        prod_delivery_dates = ", ".join(sorted(lv.get("delivery_dates") or [])) if lv else ""
        cn_name = cn_map.get(key[1], "")
        for idx, p in enumerate(parts):
            qty = p["qty_required"]
            ps = part_stats[idx]
            arrived = min(qty, max(0.0, ps["arrived"]))
            coming = max(0.0, qty - arrived)
            if not source_found and not receipt_source_ok:
                status_key, status = "missing", "Not found in Production"
            elif coming <= 1e-9:
                status_key, status = "arrived", "Arrived"
            elif p.get("need_by_iso") and p["need_by_iso"] < today_iso:
                status_key, status = "overdue", "Overdue / Coming"
            elif arrived > 1e-9:
                status_key, status = "partial", "Partly Arrived"
            else:
                status_key, status = "coming", "Coming"
            try:
                nd = datetime.strptime(p["need_by_iso"], "%Y-%m-%d")
                need_disp = nd.strftime("%d-%b-%Y")
            except Exception:
                need_disp = p["need_by_text"]
            try:
                od = datetime.strptime(p["order_date"], "%Y-%m-%d")
                order_disp = od.strftime("%d-%b-%Y")
            except Exception:
                order_disp = p["order_date"]
            latest_receiving_display = ""
            if ps["latest_iso"]:
                try:
                    latest_receiving_display = datetime.strptime(ps["latest_iso"], "%Y-%m-%d").strftime("%d-%b-%Y")
                except Exception:
                    latest_receiving_display = ps["latest_iso"]
            out.append({
                "need_by_iso": p["need_by_iso"], "need_by_display": need_disp, "need_by_text": p["need_by_text"],
                "order_date": p["order_date"], "order_date_display": order_disp,
                "order_no": g["order_no"], "sku": g["sku"], "cn_name": cn_name, "priority": p["priority"],
                "row_source": p.get("source", "plan"),
                "image_url": _RAKHI_PRODUCTION_IMAGE_BY_KEY.get(key, "") or master_image_map.get(key[1], ""),
                "qty_required": int(round(qty)),
                "production_order_qty": int(round(float(lv.get("order_qty") or 0))) if lv else 0,
                "production_balance_qty": 0,
                "arrived_qty": int(round(arrived)), "coming_qty": int(round(coming)),
                "received_since_aug6": int(round(max(0.0, ps["arrived"]))),
                "received_today": int(round(ps["today"])),
                "received_yesterday": int(round(ps["yesterday"])),
                "received_day_before": int(round(ps["day_before"])),
                "latest_receiving_date": ps["latest_iso"],
                "latest_receiving_date_display": latest_receiving_display,
                "receipt_source_ok": receipt_source_ok,
                "baseline_balance_qty": int(round(g["baseline_balance"])),
                "live_balance_qty": int(round(live_balance)) if source_found else None,
                "receiving_dates": latest_receiving_display,
                "production_delivery_dates": prod_delivery_dates,
                "source_found": source_found, "status_key": status_key, "status": status,
            })

    # Divide the highest live Production Balance Qty (column K) once across all
    # tracker rows sharing the same Order Date + SKU. Integer remainder is given
    # to the earliest rows, so 1000 across 3 rows becomes 334, 333, 333 and the
    # displayed sum remains exactly 1000.
    _out_balance_groups = {}
    for _idx, _row in enumerate(out):
        _bkey = (clean(_row.get("order_date", "")), _rakhi_prod_sku_key(_row.get("sku", "")))
        if _bkey[0] and _bkey[1]:
            _out_balance_groups.setdefault(_bkey, []).append(_idx)
    for _bkey, _indices in _out_balance_groups.items():
        _pool = int(round(max(0.0, production_balance_max_by_date_sku.get(_bkey, 0.0))))
        _n = len(_indices)
        if _n <= 0:
            continue
        _base, _rem = divmod(_pool, _n)
        for _pos, _idx in enumerate(_indices):
            out[_idx]["production_balance_qty"] = _base + (1 if _pos < _rem else 0)

    # Rows discovered only from LIVE PPC-WIP were not present in the supplied
    # Production Data Excel. For these rows, Qty Required must always equal the
    # displayed Production Balance Qty. Since Balance Qty is already the current
    # remaining quantity after production receipts, do not subtract received qty
    # from it again when calculating Still Coming.
    for _row in out:
        if _row.get("row_source") != "live_production":
            continue
        _bal_req = max(0, int(round(float(_row.get("production_balance_qty") or 0))))
        _row["qty_required"] = _bal_req
        _row["coming_qty"] = _bal_req
        if _bal_req <= 0:
            _row["status_key"], _row["status"] = "arrived", "Arrived"
        elif int(_row.get("arrived_qty") or 0) > 0:
            _row["status_key"], _row["status"] = "partial", "Partly Arrived"
        else:
            _row["status_key"], _row["status"] = "coming", "Coming"

    # Backend reconciliation guard: the unfiltered first table must reproduce
    # the authoritative post-06-Aug Rakhi receiving totals exactly. These fields
    # are diagnostics for the UI/API and make future source-shape issues visible
    # instead of silently under-counting receipts.
    _tracker_received_since = int(round(sum(float(r.get("received_since_aug6") or 0) for r in out)))
    _tracker_today = int(round(sum(float(r.get("received_today") or 0) for r in out)))
    _tracker_yesterday = int(round(sum(float(r.get("received_yesterday") or 0) for r in out)))
    _tracker_day_before = int(round(sum(float(r.get("received_day_before") or 0) for r in out)))
    rakhi_receipts["tracker_received_since_aug6"] = _tracker_received_since
    rakhi_receipts["tracker_received_today"] = _tracker_today
    rakhi_receipts["tracker_received_yesterday"] = _tracker_yesterday
    rakhi_receipts["tracker_received_day_before"] = _tracker_day_before
    rakhi_receipts["receipt_only_rows_added"] = int(receipt_only_rows_added)
    rakhi_receipts["receipt_reconciled"] = bool(
        not receipt_source_ok or (
            _tracker_received_since == int(rakhi_receipts.get("source_received_since_aug6") or 0) and
            _tracker_today == int(rakhi_receipts.get("source_received_today") or 0) and
            _tracker_yesterday == int(rakhi_receipts.get("source_received_yesterday") or 0) and
            _tracker_day_before == int(rakhi_receipts.get("source_received_day_before") or 0)
        )
    )

    # Newly discovered live RKH orders are placed first so fresh order numbers
    # (1422/1423/1427/1428/future) are visible immediately; plan rows retain
    # their existing need-by ordering after that.
    out.sort(key=lambda r: (
        0 if r.get("row_source") == "live_production" else 1,
        -(_rakhi_prod_order_rank(r.get("order_no")) or -1) if r.get("row_source") == "live_production" else 0,
        r.get("need_by_iso") or "9999-12-31",
        r.get("sku", ""),
        r.get("order_no", ""),
    ))
    return {
        "rows": out, "baseline_date": _RAKHI_PRODUCTION_BASELINE_DATE,
        "count": len(out), "unique_skus": len({r["sku"] for r in out}),
        "planned_qty": int(round(sum(r["qty_required"] for r in out))),
        "arrived_qty": int(round(sum(r["arrived_qty"] for r in out))),
        "coming_qty": int(round(sum(r["coming_qty"] for r in out))),
        "missing_rows": sum(1 for r in out if not r["source_found"]),
        "live_rakhi_rows_added": int(live_rakhi_added),
        "live_other_rows_added": int(live_other_added),
        "live_pending_rows_added": int(live_rakhi_added + live_other_added),
        "receipt_only_rows_added": int(receipt_only_rows_added),
        "production_by_sku": production_by_sku,
        "rakhi_receipts_by_sku": rakhi_receipts.get("by_sku") or {},
        "rakhi_receipts_by_order_sku": rakhi_receipts.get("by_order_sku") or {},
        "rakhi_receipts_meta": {k: v for k, v in rakhi_receipts.items() if k not in ("by_sku", "by_order_sku")},
    }

def _build_target_report(month_filter="", stake_filter="", channel_filter=""):
    """Target vs Actual + Achievement Forecast + Stakeholder Leaderboard.
    Default: present month. Stake Holder ↔ COSA Customer, Channel ↔ COSA Type."""
    if _is_amazon_fba_value(channel_filter):
        channel_filter = "Amazon"
    targets = _fetch_target_rows()
    data = get_data()
    comp = data[0]
    today = now_ist()
    cur_month = today.strftime("%Y-%m")

    # months available
    months_set = set(t["month"] for t in targets)
    stakes_set = set(t["stakeholder"] for t in targets)
    channels_set = set(t["channel"] for t in targets if t.get("channel"))

    # Default month = present month (agar available ho), warna latest.
    if not month_filter:
        month_filter = cur_month if cur_month in months_set else (sorted(months_set, reverse=True)[0] if months_set else cur_month)

    # Forecast factor: mahine me kitne din beet gaye (pace projection).
    import calendar
    y, mo = int(month_filter[:4]), int(month_filter[5:7])
    days_in_month = calendar.monthrange(y, mo)[1]
    if month_filter == cur_month:
        day_elapsed = today.day
    elif month_filter < cur_month:
        day_elapsed = days_in_month     # past month — pura ho chuka
    else:
        day_elapsed = 0                 # future month
    pace = (days_in_month / day_elapsed) if day_elapsed > 0 else 0.0

    # Actual ko (month, channel/type) par aggregate karo. Target Achievement
    # aur isi tab ka Daily Revenue Glimpse dono Order Date basis use karte hain,
    # taaki same month/channel ke KPIs aapas me mismatch na karein. Dispatch-Date
    # rows sirf source-outage fallback hain.
    # Target ka "Channel Type" (Marketplace, Website, Purchase…) = COSA ka "Type".
    # Target tab canonical rule: Amazon and all legacy Amazon-FBA spellings are
    # one Amazon family and also contribute to Marketplace/SOR actuals.
    act = {}
    for it in comp:
        _target_entries = it.get("orderdate_sales_entries") or it.get("sales_entries", [])
        for e in _target_entries:
            d = e.get("date")
            if not d or d == "N/A":
                continue
            mk = d[:7]
            typ = _marketplace_display_text(e.get("type") or "").strip().lower()
            sub = _marketplace_display_text(e.get("sub_channel") or "").strip().lower()
            cust = _marketplace_display_text(e.get("customer") or "").strip().lower()
            entry_keys = {typ}
            amazon_family = (
                sub == "amazon" or cust == "amazon"
                or _is_amazon_fba_value(e.get("sub_channel"), e.get("customer"), e.get("type"))
            )
            if amazon_family:
                # Target tab treats Amazon + legacy Amazon FBA as one Amazon bucket.
                # Amazon also belongs to Mahesh's Marketplace/SOR actual, even if a
                # source row happens to arrive with Ecom/other type text.
                entry_keys.add("amazon")
                entry_keys.add("marketplace")
            if sub in {"flipkart", "myntra", "nykaa", "ajio", "tata cliq", "tata"}:
                entry_keys.add("tata" if sub == "tata cliq" else sub)
            for entry_key in entry_keys:
                if not entry_key:
                    continue
                k = (mk, entry_key)
                slot = act.setdefault(k, {"rev": 0.0, "qty": 0.0})
                slot["rev"] += float(e.get("rev") or 0)
                slot["qty"] += float(e.get("qty") or 0)

    rows = []
    lb = {}   # stakeholder -> aggregated
    for t in targets:
        mk = t["month"]
        if mk != month_filter:
            continue
        if stake_filter and t["stakeholder"].strip().lower() != stake_filter.strip().lower():
            continue
        if channel_filter and (t.get("channel") or "").strip().lower() != channel_filter.strip().lower():
            continue
        a = act.get((mk, t["channel"].strip().lower()), {"rev": 0.0, "qty": 0.0})
        actual_rev = a["rev"]; actual_qty = a["qty"]
        sp_short  = t["sp_target"] - actual_rev
        qty_short = t["qty_target"] - actual_qty
        pct = round((actual_rev / t["sp_target"] * 100), 1) if t["sp_target"] else 0.0
        # Forecast: current pace se mahine ke end tak projected revenue + %.
        proj_rev = actual_rev * pace if pace else actual_rev
        proj_pct = round((proj_rev / t["sp_target"] * 100), 1) if t["sp_target"] else 0.0
        rows.append({
            "month": mk, "month_label": t["month_label"],
            "stakeholder": t["stakeholder"], "channel": t["channel"],
            "qty_target": t["qty_target"], "qty_actual": actual_qty, "qty_short": qty_short,
            "sp_target": t["sp_target"], "sp_actual": actual_rev, "sp_short": sp_short,
            "pct_achieved": pct, "proj_rev": proj_rev, "proj_pct": proj_pct,
        })
        # leaderboard aggregate (per stakeholder, all channels)
        L = lb.setdefault(t["stakeholder"], {"stakeholder": t["stakeholder"], "channels": set(),
              "sp_target":0.0,"sp_actual":0.0,"qty_target":0.0,"qty_actual":0.0,"proj_rev":0.0})
        if t.get("channel"):
            L["channels"].add(t["channel"])
        L["sp_target"] += t["sp_target"]; L["sp_actual"] += actual_rev
        L["qty_target"] += t["qty_target"]; L["qty_actual"] += actual_qty
        L["proj_rev"] += proj_rev

    # Totals
    tot = {"qty_target":0.0,"qty_actual":0.0,"qty_short":0.0,
           "sp_target":0.0,"sp_actual":0.0,"sp_short":0.0,"proj_rev":0.0}
    for r in rows:
        for k in ("qty_target","qty_actual","qty_short","sp_target","sp_actual","sp_short","proj_rev"):
            tot[k] += r[k]
    tot["pct_achieved"] = round((tot["sp_actual"]/tot["sp_target"]*100),1) if tot["sp_target"] else 0.0
    tot["proj_pct"] = round((tot["proj_rev"]/tot["sp_target"]*100),1) if tot["sp_target"] else 0.0

    # Leaderboard finalize + rank (by % achieved)
    leaderboard = []
    for L in lb.values():
        L["pct_achieved"] = round((L["sp_actual"]/L["sp_target"]*100),1) if L["sp_target"] else 0.0
        L["proj_pct"] = round((L["proj_rev"]/L["sp_target"]*100),1) if L["sp_target"] else 0.0
        L["sp_short"] = L["sp_target"] - L["sp_actual"]
        L["channel"] = ", ".join(sorted(L.pop("channels"))) if L.get("channels") else "—"
        leaderboard.append(L)
    leaderboard.sort(key=lambda x: x["pct_achieved"], reverse=True)
    for i, L in enumerate(leaderboard): L["rank"] = i + 1

    return {
        "rows": rows, "totals": tot, "leaderboard": leaderboard,
        "month_selected": month_filter,
        "month_label": (rows[0]["month_label"] if rows else month_filter),
        "days_in_month": days_in_month, "day_elapsed": day_elapsed,
        "is_current_month": (month_filter == cur_month),
        "months": sorted(months_set, reverse=True),
        "stakeholders": sorted(stakes_set),
        "channels": sorted(channels_set),
    }

@app.route("/api/target")
def api_target():
    if session.get("role") not in ("admin", "employee"):
        return jsonify({"error": "login required"}), 401
    mf = request.args.get("month", "").strip()
    sf = request.args.get("stake", "").strip()
    chf = request.args.get("channel", "").strip()
    try:
        rep = _build_target_report(mf, sf, chf)
        return jsonify(rep)
    except Exception as e:
        return jsonify({"error": f"target build failed: {e}"}), 500


_OPS_INVENTORY_CACHE = {"rows": None, "ts": 0.0, "meta": {}}
_OPS_INVENTORY_TTL = 120
_OPS_INVENTORY_LOCK = threading.Lock()

def _build_operations_inventory(force=False):
    """Fresh All Product stock payload used only by Operations.

    Blocked Qty is read from physical column U and remains a separate field in
    this payload. The browser combines it with Inv Stock only inside the CMB
    build planner; no shared dashboard inventory value is mutated.
    """
    now = time.time()
    cached = _OPS_INVENTORY_CACHE.get("rows")
    if (not force and cached is not None
            and now - float(_OPS_INVENTORY_CACHE.get("ts") or 0) < _OPS_INVENTORY_TTL):
        return cached, dict(_OPS_INVENTORY_CACHE.get("meta") or {})

    with _OPS_INVENTORY_LOCK:
        now = time.time()
        cached = _OPS_INVENTORY_CACHE.get("rows")
        if (not force and cached is not None
                and now - float(_OPS_INVENTORY_CACHE.get("ts") or 0) < _OPS_INVENTORY_TTL):
            return cached, dict(_OPS_INVENTORY_CACHE.get("meta") or {})

        inv = _fetch_csv_fresh(INV_URL)
        inv.columns = [str(c).strip() for c in inv.columns]
        cols = list(inv.columns)
        # Live All Product source keeps SKU in physical column B. Header match
        # remains primary; B is the safe fallback (A is S. No.).
        sku_col = find_col(cols, "SKU") or (cols[1] if len(cols) > 1 else (cols[0] if cols else None))

        stock_candidates = [
            c for c in cols
            if "inv" in c.lower() and "stock" in c.lower()
            and "3p" not in c.lower() and "web" not in c.lower() and "myntr" not in c.lower()
        ]
        stock_col = stock_candidates[0] if stock_candidates else find_col(cols, "Inv. Stock", "Inv Stock", "stock")

        wip_exact = [c for c in cols if re.sub(r"[^a-z0-9]", "", c.lower()) == "invwip"]
        if wip_exact:
            wip_col = wip_exact[0]
        else:
            wip_candidates = [
                c for c in cols if "wip" in c.lower()
                and "website" not in c.lower() and "designer" not in c.lower()
                and "customer" not in c.lower() and "customize" not in c.lower()
                and "customise" not in c.lower() and "sor" not in c.lower()
            ]
            wip_col = wip_candidates[0] if wip_candidates else find_col(cols, "Inv (WIP)", "wip")

        # User-confirmed source: physical column U, not a fuzzy header match.
        blocked_col = cols[20] if len(cols) > 20 else find_col(cols, "Blocked Qty", "blocked qty")
        if not sku_col or not stock_col or not blocked_col:
            raise ValueError(
                f"All Product columns missing: SKU={sku_col}, Inv Stock={stock_col}, column U={blocked_col}"
            )

        by_sku = {}
        duplicate_skus = set()
        for row in _df_chunks(inv, 3000):
            sku = clean(row.get(sku_col, "")).strip().upper()
            if not sku:
                continue
            rec = {
                "sku": sku,
                "inv_stock": max(0, to_int(row.get(stock_col, 0))),
                "blocked_qty": max(0, to_int(row.get(blocked_col, 0))),
                "inv_wip": max(0, to_int(row.get(wip_col, 0))) if wip_col else 0,
            }
            if sku in by_sku:
                duplicate_skus.add(sku)
                # Do not sum duplicate master rows. Taking the highest observed
                # field prevents a later/earlier blank duplicate from erasing
                # valid column-U stock without double-counting the SKU.
                old = by_sku[sku]
                old["inv_stock"] = max(old["inv_stock"], rec["inv_stock"])
                old["blocked_qty"] = max(old["blocked_qty"], rec["blocked_qty"])
                old["inv_wip"] = max(old["inv_wip"], rec["inv_wip"])
            else:
                by_sku[sku] = rec

        rows = list(by_sku.values())
        meta = {
            "source": "All Product",
            "sku_column": str(sku_col),
            "stock_column": str(stock_col),
            "blocked_column": str(blocked_col),
            "blocked_column_letter": "U",
            "wip_column": str(wip_col or ""),
            "sku_count": len(rows),
            "blocked_sku_count": sum(1 for r in rows if r["blocked_qty"] > 0),
            "duplicate_sku_count": len(duplicate_skus),
            "checked_at": datetime.now(TZ).isoformat(),
        }
        _OPS_INVENTORY_CACHE.update({"rows": rows, "ts": time.time(), "meta": meta})
        return rows, meta

@app.route("/api/operations-inventory")
def api_operations_inventory():
    if session.get("role") not in ("admin", "employee"):
        return jsonify({"error": "login required"}), 401
    try:
        fresh = request.args.get("fresh", "0").strip().lower() in ("1", "true", "yes")
        rows, meta = _build_operations_inventory(force=fresh)
        return jsonify({"rows": rows, "meta": meta})
    except Exception as e:
        return jsonify({"error": f"Operations inventory load failed: {e}"}), 500


@app.route("/api/ops-support")
def api_ops_support():
    """Small support payload for Smart Alerts and Inventory Ageing.

    Production rows are aggregated server-side from the full PPC-WIP cache so
    the client is not limited by the Production tab's 1,000-row display cap.
    """
    if session.get("role") not in ("admin", "employee"):
        return jsonify({"error": "login required"}), 401
    try:
        fresh = request.args.get("fresh", "0").strip().lower() in ("1", "true", "yes")
        if fresh:
            _PROD_CACHE["rows"] = None
            _PROD_CACHE["ts"] = 0
            _TARGET_CACHE["rows"] = None
            _TARGET_CACHE["ts"] = 0

        # Populates _PROD_CACHE with all source rows. Returned rows may be capped,
        # therefore we intentionally read the underlying cache afterwards.
        _build_production()
        rows_all = list(_PROD_CACHE.get("rows") or [])

        pending = {}
        latest_receipts = {}
        for r in rows_all:
            sku = str(r.get("sku") or "").strip().upper()
            if not sku:
                continue

            recv_raw = r.get("receiving_date") or ""
            recv_dt = parse_date_any(recv_raw) if recv_raw else None
            if recv_dt is not None:
                recv_iso = recv_dt.strftime("%Y-%m-%d")
                if recv_iso > latest_receipts.get(sku, ""):
                    latest_receipts[sku] = recv_iso

            bal = float(r.get("bal_qty") or 0)
            if bal <= 0:
                continue
            p = pending.setdefault(sku, {
                "sku": sku, "balance_qty": 0.0, "order_qty": 0.0,
                "recv_qty": 0.0, "oldest_order_date": "",
                "latest_delivery_date": "", "order_nos": [],
                "channels": [], "order_types": [],
            })
            p["balance_qty"] += bal
            p["order_qty"] += float(r.get("order_qty") or 0)
            p["recv_qty"] += float(r.get("recv_qty") or 0)
            od = str(r.get("date") or "")
            if od and (not p["oldest_order_date"] or od < p["oldest_order_date"]):
                p["oldest_order_date"] = od
            dd = str(r.get("delivery_iso") or "")
            if dd and dd > p["latest_delivery_date"]:
                p["latest_delivery_date"] = dd
            ono = str(r.get("order_no") or "").strip()
            if ono and ono not in p["order_nos"]:
                p["order_nos"].append(ono)
            ch = str(r.get("channel") or "").strip()
            if ch and ch not in p["channels"]:
                p["channels"].append(ch)
            typ = str(r.get("order_type") or "").strip()
            if typ and typ not in p["order_types"]:
                p["order_types"].append(typ)

        target = _build_target_report()
        return jsonify({
            "today": now_ist().strftime("%Y-%m-%d"),
            "production_pending": list(pending.values()),
            "latest_receipts": [
                {"sku": sku, "latest_receiving_date": dt}
                for sku, dt in sorted(latest_receipts.items())
            ],
            "target_rows": target.get("rows", []),
            "target_totals": target.get("totals", {}),
            "target_month": target.get("month_selected", ""),
        })
    except Exception as e:
        return jsonify({"error": f"ops support build failed: {e}"}), 500

# ════════════════════════════════════════════════════════════════
#  📊 DAILY REPORTING — Order-Date management report (admin only)
#  New standalone tab. No existing tab uses these adjusted revenues.
# ════════════════════════════════════════════════════════════════
def _daily_reporting_month_bounds(anchor_dt, month_offset):
    base_index = anchor_dt.year * 12 + (anchor_dt.month - 1) + int(month_offset)
    year, month0 = divmod(base_index, 12)
    month = month0 + 1
    start = datetime(year, month, 1)
    if month == 12:
        next_start = datetime(year + 1, 1, 1)
    else:
        next_start = datetime(year, month + 1, 1)
    return start, next_start - timedelta(days=1)


def _build_daily_reporting():
    # The main sync already parsed COSA Order Date + exact order source sheets.
    # Reuse those compact caches here so opening this tab does not trigger a
    # second multi-sheet download and does not slow down the dashboard.
    if CACHE.get("data") is None:
        get_data(False)
    daily = CACHE.get("daily_reporting_daily", {}) or {}
    order_daily = CACHE.get("daily_reporting_orders", {}) or {}
    website_order_daily = CACHE.get("daily_reporting_website_orders", {}) or {}
    marketplace_order_daily = CACHE.get("daily_reporting_marketplace_orders", {}) or {}
    qcommerce_order_daily = CACHE.get("daily_reporting_qcommerce_orders", {}) or {}

    today_dt = now_ist().replace(hour=0, minute=0, second=0, microsecond=0, tzinfo=None)
    # Management report uses completed order days only. On 11-Aug this means
    # Aug 1-10; on 12-Aug it automatically becomes Aug 1-11.
    completed_through = today_dt - timedelta(days=1)
    cur_start = today_dt.replace(day=1)
    p1_start, p1_end = _daily_reporting_month_bounds(today_dt, -1)
    p2_start, p2_end = _daily_reporting_month_bounds(today_dt, -2)
    ly1_start, ly1_end = _daily_reporting_month_bounds(today_dt, -13)
    ly2_start, ly2_end = _daily_reporting_month_bounds(today_dt, -14)

    periods = [
        ("prev_month", p1_start, p1_end, p1_start.strftime("%B")),
        ("prev_2_month", p2_start, p2_end, p2_start.strftime("%B")),
        ("mtd", cur_start, completed_through, f"{today_dt.strftime('%b')} 1-{completed_through.day}"),
        ("last_year_prev", ly1_start, ly1_end, f"Last Year {ly1_start.strftime('%B')}"),
        ("last_year_prev_2", ly2_start, ly2_end, f"Last Year {ly2_start.strftime('%B')}"),
    ]

    def _one_period(key, start, end, label):
        start_iso, end_iso = start.strftime("%Y-%m-%d"), end.strftime("%Y-%m-%d")
        dtc = marketplace = qcommerce = 0.0
        # AOV numerator is accumulated only for source-days that have an exact
        # order identity feed. This matters for Q-Commerce: the current
        # cossa_orderdate sheet has revenue rows but no Order ID column.
        aov_revenue = 0.0
        order_keys = set()
        peak_date = ""
        peak_amount = None
        for day, vals in daily.items():
            ds = str(day or "")
            if not (start_iso <= ds <= end_iso):
                continue
            day_dtc = float(vals.get("dtc") or 0)
            day_marketplace = float(vals.get("marketplace") or 0)
            day_qcommerce = float(vals.get("qcommerce") or 0)
            dtc += day_dtc
            marketplace += day_marketplace
            qcommerce += day_qcommerce
            if website_order_daily.get(ds):
                aov_revenue += day_dtc
            if marketplace_order_daily.get(ds):
                aov_revenue += day_marketplace
            if qcommerce_order_daily.get(ds):
                aov_revenue += day_qcommerce
            day_total = float(vals.get("total") or 0)
            if peak_amount is None or day_total > peak_amount or (day_total == peak_amount and ds < peak_date):
                peak_amount = day_total
                peak_date = ds
        for day, keys in order_daily.items():
            ds = str(day or "")
            if start_iso <= ds <= end_iso:
                order_keys.update(keys or set())
        total = dtc + marketplace + qcommerce
        orders = len(order_keys)
        aov = aov_revenue / orders if orders else 0.0
        if not peak_date or peak_amount is None or peak_amount == 0:
            peak_date_label = ""
            peak_amount = 0.0
        else:
            try:
                peak_date_label = datetime.strptime(peak_date, "%Y-%m-%d").strftime("%d-%b-%Y")
            except Exception:
                peak_date_label = peak_date
        return {
            "key": key, "label": label,
            "from": start_iso, "to": end_iso,
            "total_revenue": total,
            "dtc_revenue": dtc,
            "marketplace_revenue": marketplace,
            "qcommerce_revenue": qcommerce,
            "orders": orders,
            "aov": aov,
            "aov_revenue": aov_revenue,
            "peak_revenue_date": peak_date_label,
            "peak_revenue_amount": float(peak_amount or 0),
        }

    built = [_one_period(*p) for p in periods]
    return {
        "periods": built,
        "as_of": completed_through.strftime("%d-%b-%Y"),
        "source_note": "Data basis: completed Order Date. Website = Display Order Code (column A) only; marketplaces = native exact Order IDs. AOV uses only revenue from source-days with exact order identities, so numerator and order denominator always match.",
        "revenue_note": "Daily Reporting only: Return Amount gets +6% for every channel; Website also gets +6% on Net Revenue.",
        "order_note": "Orders are unique source identities: Website = Display Order Code (column A) only (Website J/Invoice Code is ignored); Myntra H = Order id; Ajio F = FWD Seller Order NO; Amazon/Flipkart H = Order id (their J identifies marketplace); Nykaa D = orderno; Tata D = OrderId. cossa_orderdate fallback is used only for Q-Commerce.",
    }


@app.route("/api/daily-reporting")
def api_daily_reporting():
    if session.get("role") != "admin":
        return jsonify({"error": "admin login required"}), 403
    try:
        return jsonify(_build_daily_reporting())
    except Exception as e:
        return jsonify({"error": f"daily reporting build failed: {e}"}), 500


@app.route("/api/daily-reporting/export.xlsx")
def api_daily_reporting_export_xlsx():
    if session.get("role") != "admin":
        return jsonify({"error": "admin login required"}), 403
    try:
        import openpyxl
        from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
        from openpyxl.utils import get_column_letter

        rep = _build_daily_reporting()
        periods = rep["periods"]
        headers = ["Metric"] + [p["label"] for p in periods]
        metrics = [
            ("Total Revenue", "total_revenue", "money"),
            ("DTC Revenue", "dtc_revenue", "money"),
            ("Marketplace Revenue", "marketplace_revenue", "money"),
            ("Q-Commerce Revenue (Blinkit + Instamart)", "qcommerce_revenue", "money"),
            ("Orders", "orders", "integer"),
            ("AOV", "aov", "money"),
            ("", "", "blank"),
            ("Peak Revenue Date", "peak_revenue_date", "text"),
            ("Peak Revenue Amount", "peak_revenue_amount", "money"),
        ]

        wb = openpyxl.Workbook()
        ws = wb.active
        ws.title = "Daily Reporting"
        max_col = len(headers)

        top_fill = PatternFill("solid", fgColor="F3F3F3")
        head_fill = PatternFill("solid", fgColor="FFFFFF")
        head_font = Font(bold=True, size=11, color="111111")
        title_font = Font(bold=True, size=11, color="333333")
        thin = Side(style="thin", color="D9D9D9")
        border = Border(left=thin, right=thin, top=thin, bottom=thin)
        center = Alignment(horizontal="center", vertical="center", wrap_text=True)
        left = Alignment(horizontal="left", vertical="center", wrap_text=True)
        money_fmt = '₹#,##0.00'
        int_fmt = '#,##0'

        ws.merge_cells(start_row=1, start_column=1, end_row=1, end_column=max_col)
        ws.cell(1, 1, rep["source_note"]).font = title_font
        ws.cell(1, 1).alignment = center
        for c in range(1, max_col + 1):
            ws.cell(1, c).fill = top_fill
            ws.cell(1, c).border = border

        for c, h in enumerate(headers, 1):
            cell = ws.cell(2, c, h)
            cell.font = head_font
            cell.fill = head_fill
            cell.alignment = center
            cell.border = border

        row_no = 3
        for label, key, kind in metrics:
            if kind == "blank":
                row_no += 1
                continue
            first = ws.cell(row_no, 1, label)
            first.alignment = left
            first.border = border
            for idx, period in enumerate(periods, 2):
                val = period.get(key, "")
                cell = ws.cell(row_no, idx, val)
                cell.alignment = center
                cell.border = border
                if kind == "money":
                    cell.number_format = money_fmt
                elif kind == "integer":
                    cell.number_format = int_fmt
            row_no += 1

        ws.freeze_panes = "B3"
        ws.column_dimensions["A"].width = 38
        for c in range(2, max_col + 1):
            ws.column_dimensions[get_column_letter(c)].width = 18
        ws.row_dimensions[1].height = 24
        ws.row_dimensions[2].height = 30

        # Formula rules/source notes below the mirrored table, kept outside the
        # requested shape so the visible report remains exactly management-ready.
        note_row = row_no + 1
        ws.merge_cells(start_row=note_row, start_column=1, end_row=note_row, end_column=max_col)
        ws.cell(note_row, 1, rep["revenue_note"]).font = Font(italic=True, size=9, color="666666")
        ws.cell(note_row, 1).alignment = left
        ws.merge_cells(start_row=note_row + 1, start_column=1, end_row=note_row + 1, end_column=max_col)
        ws.cell(note_row + 1, 1, rep["order_note"]).font = Font(italic=True, size=9, color="666666")
        ws.cell(note_row + 1, 1).alignment = left

        bio = io.BytesIO()
        wb.save(bio)
        bio.seek(0)
        fname = f"daily_reporting_{now_ist().strftime('%Y-%m-%d')}.xlsx"
        resp = app.response_class(
            bio.read(),
            mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        )
        resp.headers["Content-Disposition"] = f"attachment; filename={fname}"
        return resp
    except Exception as e:
        return jsonify({"error": f"daily reporting excel export failed: {e}"}), 500

# ════════════════════════════════════════════════════════════════
#  📅 DAILY REVENUE GLIMPSE  (admin/employee) — Target tab ka 2nd
#  table. Channel-wise: Last Month, Day Before, Yesterday, MTD,
#  MTD Target (Target sheet se), MTD Achievement %.
#
#  Rows/Buckets: Website(DTC), Amazon, Flipkart, Myntra, Nykaa, Ajio,
#  Tata, Blinkit, Instamart, Other Marketplace Channels, Others (Purchase,
#  Exhibition, Bulk).
#
#  Channel logic (COSA "Type" + "Customer" par based):
#    - Amazon/Flipkart/Myntra/Nykaa/Ajio/Tata: COSA me "Type" = Marketplace
#      hota hai, asli channel Customer naam se pehchana jata hai
#      (calc_channel/calc_sub_channel already yeh kar chuke hain —
#      entry ka "channel"="Ecom" + "sub_channel"="Myntra"/"Nykaa"/
#      "Amazon"/"Flipkart"/"AJIO"/"Tata CLiQ" use karte hain).
#    - Website (DTC): COSA "Type" = Website/Online → channel="D2C".
#    - Blinkit/Instamart: COSA "Type" me seedhe waisa hi likha
#      hota hai (abhi sheet me data nahi hai to 0 hi aayega, jaise
#      hi data aayega apne aap bharna shuru ho jayega).
#    - Other Marketplace Channels: Type=Marketplace ho lekin marketplace na ho (na
#      Myntra/Nykaa/Amazon/Flipkart/Ajio/Tata), ya koi aur chhoti
#      marketplace (FNP/Fern/Mirraw).
#    - Others (Purchase, Exhibition, Bulk): sirf in teeno Type ka
#      data, + koi bhi truly unclassified row (safety net, taaki
#      TOTAL hamesha grand actual revenue se match kare).
#
#  Type/word matching poori tarah case-insensitive hai (Website/
#  WEBSITE/website, Marketplace/SOR/sor — sab ek jaisa treat hota hai) aur
#  date parsing already parse_date_any() se hoti hai jo string/int/
#  date/datetime — sab format handle karta hai.
# ════════════════════════════════════════════════════════════════
_DRG_ROWS_ORDER = ["Website", "Amazon", "Flipkart", "Myntra", "Nykaa", "Ajio", "Tata",
                   "Blinkit", "Instamart",
                   "Other Marketplace Channels", "Others (Purchase, Exhibition, Bulk)"]
_DRG_LABELS = {"Website": "Website (DTC)"}

# Target sheet ki "Channel Type" ko in row-buckets se match karne ke
# liye aliases (case-insensitive). Jo match na ho wo bhi "Others
# (Purchase, Exhibition, Bulk)" me chala jata hai — isse MTD Target
# ka total bhi Target sheet ke total se match karta hai.
_DRG_TARGET_ALIASES = {
    "Website":                          {"website", "d2c", "online"},
    "Amazon":                           {"amazon", "amazon fba", "amazon-fba", "amazon_fba", "amazonfba"},
    "Flipkart":                         {"flipkart"},
    "Myntra":                           {"myntra"},
    "Nykaa":                            {"nykaa"},
    "Ajio":                             {"ajio"},
    "Tata":                             {"tata", "tata cliq"},
    "Blinkit":                          {"blinkit"},
    "Instamart":                        {"instamart", "swiggy instamart", "swiggy"},
    "Other Marketplace Channels":       {"sor", "marketplace"},
    "Others (Purchase, Exhibition, Bulk)": {"purchase", "bulk", "exhibition"},
}
_DRG_OTHER_BUCKET = "Others (Purchase, Exhibition, Bulk)"

# Daily Revenue Glimpse source mix:
#   • Standard Amazon: original Amazon/Flipkart sheet (J marketplace;
#     W Payout to Seller for Net Revenue, R Selling value for Marketplace view).
#   • Amazon FBA: cossa_orderdate (I Net Revenue / H Selling Price), separate row.
#   • Remaining channels: their existing approved source logic.
# COSA_ORDERDATE_URL is configured with the main sheet URLs near the top so
# Rakhi and the order-date tables share the same dedicated source.

@app.route("/api/festival-sales/export.xlsx", methods=["POST"])
def api_festival_sales_export_xlsx():
    role = session.get("role")
    if role not in ("admin", "employee"):
        return jsonify({"error": "login required"}), 401
    try:
        payload = request.get_json(silent=True) or {}
        festival = re.sub(r"[^a-z]", "", str(payload.get("festival", "")).casefold())
        configs = {
            "janmashtami": ("Last Year Janmashtami", "16-Jul-2025", "16-Aug-2025", "janmashtami_last_year_product_sales.xlsx"),
            "ganesh": ("Last Ganesh Chaturthi", "27-Jul-2025", "27-Aug-2025", "ganesh_chaturthi_last_year_product_sales.xlsx"),
        }
        if festival not in configs:
            return jsonify({"error": "invalid festival"}), 400
        title, date_from, date_to, filename = configs[festival]
        channel_filter = str(payload.get("channel", "All") or "All").strip() or "All"
        rows = payload.get("rows") or []
        if not isinstance(rows, list) or not rows:
            return jsonify({"error": "no rows to export"}), 400
        if len(rows) > 25000:
            return jsonify({"error": "too many rows"}), 400

        import openpyxl
        from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
        from openpyxl.utils import get_column_letter

        wb = openpyxl.Workbook()
        ws = wb.active
        ws.title = "Janmashtami" if festival == "janmashtami" else "Ganesh Chaturthi"
        include_revenue = role == "admin"
        headers = ["Rank", "SKU", "CN Name", "Product Name", "Individual Sold", "In CMBs Sold"]
        if include_revenue:
            headers.append("Net Revenue")
        headers += ["Where Sold", "Top 3 Cities", "Image Link"]
        max_col = len(headers)

        title_fill = PatternFill("solid", fgColor="1D1D26")
        title_font = Font(bold=True, color="FFFFFF", size=14)
        sub_fill = PatternFill("solid", fgColor="F5E9CC")
        head_fill = PatternFill("solid", fgColor="E7D19A")
        head_font = Font(bold=True, color="2B2419", size=10)
        thin = Side(style="thin", color="D9D2C4")
        border = Border(left=thin, right=thin, top=thin, bottom=thin)
        center = Alignment(horizontal="center", vertical="center", wrap_text=True)
        left = Alignment(horizontal="left", vertical="center", wrap_text=True)

        ws.merge_cells(start_row=1, start_column=1, end_row=1, end_column=max_col)
        c = ws.cell(1, 1, title)
        c.fill = title_fill; c.font = title_font; c.alignment = center
        for col in range(1, max_col + 1):
            ws.cell(1, col).fill = title_fill
        ws.merge_cells(start_row=2, start_column=1, end_row=2, end_column=max_col)
        channel_note = "All Channels" if channel_filter.casefold() == "all" else channel_filter
        c = ws.cell(2, 1, f"Order Date: {date_from} to {date_to} | Channel: {channel_note}")
        c.fill = sub_fill; c.font = Font(bold=True, color="6F4D10", size=10); c.alignment = center
        for col in range(1, max_col + 1):
            ws.cell(2, col).fill = sub_fill

        for col, header in enumerate(headers, 1):
            c = ws.cell(4, col, header)
            c.fill = head_fill; c.font = head_font; c.alignment = center; c.border = border

        row_no = 5
        for idx, row in enumerate(rows, 1):
            values = [
                int(to_num(row.get("rank", idx))) or idx,
                str(row.get("sku", "") or ""),
                str(row.get("cn_name", "") or ""),
                str(row.get("sku_name", "") or ""),
                float(to_num(row.get("sold_qty", 0))),
                float(to_num(row.get("cmb_sold_qty", 0))),
            ]
            if include_revenue:
                values.append(float(to_num(row.get("net_revenue", 0))))
            values += [
                str(row.get("where_sold", "") or ""),
                str(row.get("top_cities", "") or ""),
                str(row.get("image_url", "") or ""),
            ]
            for col, value in enumerate(values, 1):
                c = ws.cell(row_no, col, value)
                c.border = border
                c.alignment = center if col in (1, 5, 6) else left
            ws.cell(row_no, 5).number_format = '#,##0.00'
            ws.cell(row_no, 6).number_format = '#,##0.00'
            if include_revenue:
                ws.cell(row_no, 7).number_format = 'Rs #,##0.00'
                image_col = 10
            else:
                image_col = 9
            img_cell = ws.cell(row_no, image_col)
            if str(img_cell.value or "").startswith(("http://", "https://")):
                img_cell.hyperlink = str(img_cell.value)
                img_cell.style = "Hyperlink"
            ws.row_dimensions[row_no].height = 34
            row_no += 1

        ws.freeze_panes = "A5"
        ws.auto_filter.ref = f"A4:{get_column_letter(max_col)}{row_no-1}"
        widths = [8, 18, 34, 42, 14, 14]
        if include_revenue:
            widths.append(18)
        widths += [32, 38, 50]
        for col, width in enumerate(widths, 1):
            ws.column_dimensions[get_column_letter(col)].width = width
        ws.row_dimensions[1].height = 28
        ws.row_dimensions[2].height = 22
        ws.row_dimensions[4].height = 28

        bio = io.BytesIO()
        wb.save(bio); bio.seek(0)
        resp = app.response_class(
            bio.read(),
            mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        )
        resp.headers["Content-Disposition"] = f"attachment; filename={filename}"
        return resp
    except Exception as e:
        return jsonify({"error": f"festival sales excel export failed: {e}"}), 500

_DRG_SRC_CACHE = {"rows": None, "ts": 0}

def _fetch_drg_source_rows(force=False):
    """Daily Revenue Glimpse ke normalized Net Revenue rows.

    Most channels come from cossa_orderdate. In the Target tab, Amazon is read
    as one consolidated family from cossa_orderdate (standard Amazon + former
    Amazon FBA) so no Amazon component can be lost after label normalization.
    Date/word values may be text, numbers or date-times and are
    normalized through parse_date_any()/norm_type()/norm_cust()."""
    if (not force and _DRG_SRC_CACHE["rows"] is not None
            and time.time() - _DRG_SRC_CACHE["ts"] < 600):
        return _DRG_SRC_CACHE["rows"]
    df = _fetch_csv_fresh(COSA_ORDERDATE_URL)
    df.columns = [str(c).strip() for c in df.columns]
    cols = list(df.columns)
    def _at(i): return cols[i] if len(cols) > i else None

    C_DATE = (find_col(df.columns, "Order Date", "order date", "orderdate")
              or _at(0) or find_col(df.columns, "Dispatch Date", "date"))
    C_QTY  = (find_col(df.columns, "Final Qty", "final quantity", "final_qty")
              or _at(6) or find_col(df.columns, "qty", "quantity") or _at(5))
    # User-approved mapping for cosa_order/cossa_orderdate: H = Selling Price.
    # Physical H is authoritative; header matching is only a compatibility fallback.
    C_SP   = _at(7) or find_col(df.columns, "Selling Price", "selling price", "unit price")
    C_REV  = _at(8)  or find_col(df.columns, "Net Revenue", "net rev", "revenue")
    C_CUST = _at(9)  or find_col(df.columns, "Customer Name", "customer", "client", "party")
    C_TYPE = _at(10) or find_col(df.columns, "Type", "channel", "mode")

    out = []
    for _, r in df.iterrows():
        dt = parse_date_any(r.get(C_DATE, "")) if C_DATE else None
        if dt is None:
            continue
        rev = to_num(r.get(C_REV, 0)) if C_REV else 0.0
        selling_price = to_num(r.get(C_SP, 0)) if C_SP else 0.0
        raw_cust_value = r.get(C_CUST, "Unknown") if C_CUST else "Unknown"
        raw_type_value = r.get(C_TYPE, "Regular") if C_TYPE else "Regular"
        raw_amazon_fba = _is_amazon_fba_value(raw_cust_value, raw_type_value)
        cust = norm_cust(raw_cust_value)
        raw_typ = norm_type(raw_type_value)
        legacy_amazon_source = bool(raw_amazon_fba or _is_amazon_fba_value(cust, raw_typ))
        cust, typ = _merge_amazon_identity(cust, raw_typ)
        # Blinkit is sourced separately from the main COSA Net Revenue column I
        # below, so skip its cossa_orderdate copy here to prevent double count.
        if "blinkit" in str(cust or "").casefold():
            continue
        channel = calc_channel(cust, typ)
        sub_channel = calc_sub_channel(cust, channel, typ)
        # Target-tab rule: cossa_orderdate is already the consolidated Amazon
        # family source. Do not drop rows merely because the source no longer
        # preserves a separate "Amazon FBA" label; every Amazon row belongs to
        # the single Amazon bucket here.
        target_amazon_merged = (str(sub_channel or "").strip().casefold() == "amazon")
        out.append({
            "date": dt.strftime("%Y-%m-%d"),
            "rev": rev,
            "sp": selling_price,
            "channel": channel,
            "sub_channel": sub_channel,
            "type": typ,
            # Keep Customer Name so the marketplace-source variant can identify
            # Amazon FBA and exclude Blinkit from its cossa_orderdate fallback.
            "customer": cust,
            "legacy_amazon_source": bool(legacy_amazon_source),
            "target_amazon_merged": bool(target_amazon_merged),
        })

    # Amazon is intentionally NOT appended again from the combined
    # Amazon/Flipkart tracker in the Target tab. cossa_orderdate already holds
    # the consolidated Amazon family (standard Amazon + former Amazon FBA), so
    # adding the tracker here would double-count standard Amazon.

    # Blinkit for the NET-REVENUE table: COSA A=Dispatch Date,
    # I=Net Revenue, J=Customer Name. Customer matching is case-insensitive.
    try:
        bdf = _fetch_csv_fresh(
            COSA_URL,
            select_groups=[
                ("Dispatch Date", "Date"),
                ("Net Revenue", "NetRevenue", "net rev", "Revenue"),
                ("Customer Name", "Customer", "Client", "Party"),
            ],
            select_positions=[0, 8, 9],
        )
        bdf.columns = [str(c).strip() for c in bdf.columns]
        b_date = _drg_source_position_col(bdf, 0) or find_col(bdf.columns, "Dispatch Date", "Date")
        b_rev = find_col(bdf.columns, "Net Revenue", "NetRevenue", "net rev", "Revenue") or _drg_source_position_col(bdf, 8)
        b_cust = find_col(bdf.columns, "Customer Name", "Customer", "Client", "Party") or _drg_source_position_col(bdf, 9)
        for row in _df_chunks(bdf):
            customer = clean(row.get(b_cust, "")) if b_cust else ""
            if "blinkit" not in customer.casefold():
                continue
            dt = parse_date_any(row.get(b_date, "")) if b_date else None
            if dt is None:
                continue
            rev = to_num(row.get(b_rev, 0)) if b_rev else 0.0
            if rev == 0:
                continue
            out.append({
                "date": dt.strftime("%Y-%m-%d"), "rev": float(rev),
                "channel": "", "sub_channel": "", "type": "Blinkit", "customer": customer,
            })
    except Exception:
        pass

    _DRG_SRC_CACHE["rows"] = out
    _DRG_SRC_CACHE["ts"] = time.time()
    return out

def _drg_bucket(channel, sub_channel, typ):
    """Har normalized entry ko Daily Revenue Glimpse ke row-bucket me daalta hai.
    Legacy FBA spellings are recognized defensively and always merged into Amazon."""
    ch_l  = str(channel or "").strip().lower()
    sub_l = str(sub_channel or "").strip().lower()
    t_l   = str(typ or "").strip().lower()
    if _is_amazon_fba_value(ch_l, sub_l, t_l):
        return "Amazon"
    if ch_l == "ecom":
        if sub_l == "myntra":    return "Myntra"
        if sub_l == "nykaa":     return "Nykaa"
        if sub_l == "amazon":    return "Amazon"
        if sub_l == "flipkart":  return "Flipkart"
        if sub_l == "ajio":      return "Ajio"
        if sub_l == "tata cliq": return "Tata"
        return "Other Marketplace Channels"     # FNP / Fern / Mirraw / Other Marketplace
    if ch_l == "d2c":
        return "Website"
    if ch_l in ("sor", "marketplace"):
        return "Other Marketplace Channels"     # Marketplace type, koi named marketplace nahi
    if t_l == "blinkit":   return "Blinkit"
    if t_l == "instamart": return "Instamart"
    if t_l in ("purchase", "bulk", "exhibition"):
        return _DRG_OTHER_BUCKET
    return _DRG_OTHER_BUCKET            # koi bhi leftover — safety net (total hamesha match kare)


# Source-sheet version of Daily Revenue Glimpse. Named DTC/Ecom channels use
# the exact user-approved price columns from their approved source tabs.
# Flipkart keeps the combined Amazon/Flipkart source. Amazon is intentionally
# read once from consolidated cossa_orderdate A=Order Date + H=Selling Price
# (standard Amazon + former Amazon FBA). Blinkit uses COSA H.
# Only the remaining buckets keep the existing cossa_orderdate Net Revenue feed.
_DRG_MARKETPLACE_SOURCE_CACHE = {"rows": None, "meta": None, "ts": 0}
_DRG_MARKETPLACE_SOURCE_TTL = 300


def _drg_source_position_col(frame, index):
    try:
        return (frame.attrs.get("source_position_columns") or {}).get(index)
    except Exception:
        return None


def _fetch_drg_marketplace_source_rows(force=False):
    if (not force and _DRG_MARKETPLACE_SOURCE_CACHE["rows"] is not None
            and time.time() - _DRG_MARKETPLACE_SOURCE_CACHE["ts"] < _DRG_MARKETPLACE_SOURCE_TTL):
        return _DRG_MARKETPLACE_SOURCE_CACHE["rows"], (_DRG_MARKETPLACE_SOURCE_CACHE["meta"] or {})

    specs = [
        {
            "key": "Website", "sheet": "Website", "url": RAKHI_WEBSITE_ADDR_URL,
            "price_pos": 18, "price_letter": "S", "price_label": "Total Price",
            "fixed_bucket": "Website", "date_names": ("Order_Date", "Order Date", "OrderDate", "Created"),
            "status_names": ("Sale Order Status", "Order Status", "Status"),
            "qty_names": ("Qty", "Quantity"), "cancel_qty_groups": (), "cancel_date_names": (),
        },
        {
            "key": "Flipkart", "sheet": "Amazon/Flipkart", "url": AMAZON_FLIPKART_SALES_URL,
            "price_pos": 17, "price_letter": "R", "price_label": "Selling value",
            "fixed_bucket": "", "allowed_buckets": ("Flipkart",),
            "platform_pos": 9, "platform_names": ("Channel", "Marketplace", "Status", "Type"),
            "date_names": ("Order_Date", "Order Date", "OrderDate", "Created On", "Packed On"),
            "status_names": (), "qty_names": ("Qty.", "Qty", "Quantity"),
            "cancel_qty_groups": (), "cancel_date_names": (),
        },
        {
            "key": "Nykaa", "sheet": "Nykaa", "url": NYKAA_SALES_URL,
            "price_pos": 44, "price_letter": "AS", "price_label": "SellingPrice",
            "fixed_bucket": "Nykaa", "date_names": ("OrderDate", "Order_Date", "Order Date", "upddate"),
            "status_names": ("Status", "Order Status"), "qty_names": ("Order Qty", "Shipped Qty", "Qty"),
            "cancel_qty_groups": (), "cancel_date_names": ("CancelledDate", "Cancelled Date"),
        },
        {
            "key": "Tata", "sheet": "Tata", "url": TATA_SALES_URL,
            "price_pos": 13, "price_letter": "N", "price_label": "Price",
            "fixed_bucket": "Tata", "date_names": ("Order_Date", "Order Date", "OrderDate", "Order Allocate Date"),
            "status_names": ("OrderStatus", "Order Status", "Status"), "qty_names": ("Order Qty", "Qty", "Net Qty"),
            "cancel_qty_groups": (), "cancel_date_names": (),
        },
        {
            "key": "Ajio", "sheet": "Ajio", "url": AJIO_SALES_URL,
            "price_pos": 32, "price_letter": "AG", "price_label": "Selling Price",
            "fixed_bucket": "Ajio", "date_names": ("Order_Date", "Order Date", "Cust Order Date", "FWD PO Date"),
            "status_names": ("Status", "Order Status"), "qty_names": ("Order Qty", "Shipped QTY", "Qty"),
            "cancel_qty_groups": (("Cancelled Qty",), ("Customer Cancelled QTY",), ("Seller Cancelled QTY",)),
            "cancel_date_names": (),
        },
        {
            "key": "Myntra", "sheet": "Myntra", "url": MYNTRA_SALES_URL,
            "price_pos": 38, "price_letter": "AM", "price_label": "Seller Price",
            "fixed_bucket": "Myntra", "date_names": ("Order_Date", "Order Date", "OrderDate", "Created On", "Packed On"),
            "status_names": ("Status", "Order Status"), "qty_names": ("Qty.", "Qty", "Quantity"),
            "cancel_qty_groups": (), "cancel_date_names": (),
        },
    ]

    out = []
    meta = {}
    named_buckets = {"Website", "Amazon", "Flipkart", "Myntra", "Nykaa", "Ajio", "Tata", "Blinkit"}

    for spec in specs:
        source_meta = {
            "sheet": spec["sheet"], "price_column": spec["price_letter"],
            "price_label": spec["price_label"], "rows_total": 0, "rows_used": 0,
            "date_column": "", "error": "",
        }
        meta[spec["key"]] = source_meta
        try:
            groups = [spec["date_names"]]
            if spec.get("platform_names"):
                groups.append(spec["platform_names"])
            if spec.get("status_names"):
                groups.append(spec["status_names"])
            if spec.get("qty_names"):
                groups.append(spec["qty_names"])
            if spec.get("cancel_date_names"):
                groups.append(spec["cancel_date_names"])
            groups.extend(spec.get("cancel_qty_groups") or ())
            positions = [spec["price_pos"]]
            if spec.get("platform_pos") is not None:
                positions.append(spec["platform_pos"])

            frame = _fetch_csv_fresh(spec["url"], select_groups=groups, select_positions=positions)
            frame.columns = [str(c).strip() for c in frame.columns]
            source_meta["rows_total"] = len(frame)

            price_col = _drg_source_position_col(frame, spec["price_pos"])
            if not price_col or price_col not in frame.columns:
                price_col = find_col(frame.columns, spec["price_label"], "Selling Price", "SellingPrice", "Selling value", "Total Price", "Price", "Seller Price")
            date_col = find_col(frame.columns, *spec["date_names"])
            status_col = find_col(frame.columns, *spec.get("status_names", ())) if spec.get("status_names") else None
            qty_col = find_col(frame.columns, *spec.get("qty_names", ())) if spec.get("qty_names") else None
            cancel_date_col = find_col(frame.columns, *spec.get("cancel_date_names", ())) if spec.get("cancel_date_names") else None
            cancel_qty_cols = []
            for cg in spec.get("cancel_qty_groups") or ():
                cc = find_col(frame.columns, *cg)
                if cc and cc not in cancel_qty_cols:
                    cancel_qty_cols.append(cc)

            platform_col = None
            if spec.get("platform_names"):
                platform_col = find_col(frame.columns, "Channel", "Marketplace")
                if not platform_col:
                    pc = _drg_source_position_col(frame, spec.get("platform_pos"))
                    platform_col = pc if pc in frame.columns else find_col(frame.columns, *spec["platform_names"])

            source_meta["date_column"] = str(date_col or "")
            source_meta["price_header"] = str(price_col or "")
            source_meta["platform_column"] = str(platform_col or "")
            if not price_col:
                raise ValueError("price column not found")
            if not date_col:
                raise ValueError("order date column not found")

            for row in _df_chunks(frame):
                dt = parse_date_any(row.get(date_col, ""))
                if dt is None:
                    continue

                if status_col:
                    status = str(row.get(status_col, "") or "").strip().casefold()
                    if any(tok in status for tok in ("cancel", "void", "failed")):
                        continue
                if cancel_date_col and clean(row.get(cancel_date_col, "")):
                    continue

                if qty_col and cancel_qty_cols:
                    gross_qty = max(0.0, to_num(row.get(qty_col, 0)))
                    cancelled_qty = sum(max(0.0, to_num(row.get(c, 0))) for c in cancel_qty_cols)
                    if gross_qty > 0 and cancelled_qty >= gross_qty:
                        continue

                rev = to_num(row.get(price_col, 0))
                if rev == 0:
                    continue

                bucket = spec.get("fixed_bucket") or ""
                if not bucket:
                    raw_platform = str(row.get(platform_col, "") if platform_col else "").strip().casefold()
                    if "amazon" in raw_platform:
                        bucket = "Amazon"
                    elif "flipkart" in raw_platform:
                        bucket = "Flipkart"
                    else:
                        continue

                allowed_buckets = set(spec.get("allowed_buckets") or ())
                if allowed_buckets and bucket not in allowed_buckets:
                    continue

                out.append({"date": dt.strftime("%Y-%m-%d"), "rev": float(rev), "bucket": bucket})
                source_meta["rows_used"] += 1
        except Exception as e:
            source_meta["error"] = str(e)[:240]

    # Amazon for this Target-tab table comes ONLY from consolidated
    # cossa_orderdate, using A=Order Date and H=Selling Price. This is already
    # the merged Amazon family, so old Amazon-FBA labels are not required.
    orderdate_rows = []
    orderdate_error = ""
    try:
        orderdate_rows = _fetch_drg_source_rows(force=force)
    except Exception as e:
        orderdate_error = str(e)[:240]

    amazon_extra_meta = {
        "sheet": "cossa_orderdate", "price_column": "H",
        "price_label": "Selling Price", "rows_total": len(orderdate_rows),
        "rows_used": 0, "date_column": "A / Order Date",
        "customer_column": "J / Customer Name", "error": orderdate_error,
    }
    meta["Amazon (merged cossa_orderdate)"] = amazon_extra_meta
    for entry in orderdate_rows:
        if _drg_bucket(entry.get("channel"), entry.get("sub_channel"), entry.get("type")) != "Amazon":
            continue
        dt_iso = str(entry.get("date") or "")
        selling_price = float(to_num(entry.get("sp", 0)))
        if not dt_iso or selling_price == 0:
            continue
        out.append({"date": dt_iso, "rev": selling_price, "bucket": "Amazon"})
        amazon_extra_meta["rows_used"] += 1

    # Blinkit is intentionally sourced from the main COSA sheet, not from
    # cossa_orderdate. The approved mapping is exact: A = Dispatch Date,
    # H = Selling Price, J = Customer Name; any Customer Name containing
    # "blinkit" (case-insensitive) belongs to the Blinkit bucket.
    blinkit_meta = {
        "sheet": "cossa", "price_column": "H", "price_label": "Selling Price",
        "rows_total": 0, "rows_used": 0, "date_column": "", "customer_column": "",
        "error": "",
    }
    meta["Blinkit"] = blinkit_meta
    try:
        blinkit_frame = _fetch_csv_fresh(
            COSA_URL,
            select_groups=[
                ("Dispatch Date", "Date"),
                ("Selling Price", "selling price", "SP"),
                ("Customer Name", "Customer", "Client", "Party"),
            ],
            select_positions=[0, 7, 9],
        )
        blinkit_frame.columns = [str(c).strip() for c in blinkit_frame.columns]
        blinkit_meta["rows_total"] = len(blinkit_frame)

        b_date = _drg_source_position_col(blinkit_frame, 0)
        if not b_date or b_date not in blinkit_frame.columns:
            b_date = find_col(blinkit_frame.columns, "Dispatch Date", "Date")
        b_price = _drg_source_position_col(blinkit_frame, 7)
        if not b_price or b_price not in blinkit_frame.columns:
            b_price = find_col(blinkit_frame.columns, "Selling Price", "selling price", "SP", "Unit Price")
        b_customer = _drg_source_position_col(blinkit_frame, 9)
        if not b_customer or b_customer not in blinkit_frame.columns:
            b_customer = find_col(blinkit_frame.columns, "Customer Name", "Customer", "Client", "Party")

        blinkit_meta["date_column"] = str(b_date or "")
        blinkit_meta["price_header"] = str(b_price or "")
        blinkit_meta["customer_column"] = str(b_customer or "")
        if not b_date:
            raise ValueError("COSA Dispatch Date column A not found")
        if not b_price:
            raise ValueError("COSA Selling Price column H not found")
        if not b_customer:
            raise ValueError("COSA Customer Name column J not found")

        for row in _df_chunks(blinkit_frame):
            customer = clean(row.get(b_customer, ""))
            if "blinkit" not in customer.casefold():
                continue
            dt = parse_date_any(row.get(b_date, ""))
            if dt is None:
                continue
            rev = to_num(row.get(b_price, 0))
            if rev == 0:
                continue
            out.append({"date": dt.strftime("%Y-%m-%d"), "rev": float(rev), "bucket": "Blinkit"})
            blinkit_meta["rows_used"] += 1
    except Exception as e:
        blinkit_meta["error"] = str(e)[:240]

    # Channels not represented by dedicated source sheets keep the old
    # cossa_orderdate revenue logic exactly as before. Blinkit rows are skipped
    # here even if the old bucket logic would call Quick Com / Blinkit "Others",
    # preventing double counting after the dedicated COSA-H mapping above.
    fallback_used = 0
    for e in orderdate_rows:
        if "blinkit" in str(e.get("customer") or "").casefold():
            continue
        bucket = _drg_bucket(e.get("channel"), e.get("sub_channel"), e.get("type"))
        if bucket in named_buckets:
            continue
        out.append({"date": e.get("date", ""), "rev": float(e.get("rev") or 0), "bucket": bucket})
        fallback_used += 1
    meta["Remaining channels"] = {
        "sheet": "cossa_orderdate", "price_column": "existing Net Revenue",
        "price_label": "existing Daily Revenue Glimpse logic", "rows_total": fallback_used,
        "rows_used": fallback_used, "date_column": "Order Date", "error": orderdate_error,
    }

    _DRG_MARKETPLACE_SOURCE_CACHE.update({"rows": out, "meta": meta, "ts": time.time()})
    return out, meta


def _build_daily_revenue_glimpse_marketplace(force=False):
    src_rows, source_meta = _fetch_drg_marketplace_source_rows(force=force)
    targets = _fetch_target_rows()

    today_dt = now_ist().replace(hour=0, minute=0, second=0, microsecond=0, tzinfo=None)
    yest_dt = today_dt - timedelta(days=1)
    dbef_dt = today_dt - timedelta(days=2)
    cm_start = today_dt.replace(day=1)
    cur_month = today_dt.strftime("%Y-%m")
    lm_end = cm_start - timedelta(days=1)
    lm_start = lm_end.replace(day=1)
    fy_label, fy_start_dt, _fy_end_dt = fy_bounds(today_dt.replace(tzinfo=TZ))

    fy_start_iso = fy_start_dt.strftime("%Y-%m-%d")
    yest_iso = yest_dt.strftime("%Y-%m-%d")
    dbef_iso = dbef_dt.strftime("%Y-%m-%d")
    lm_start_iso = lm_start.strftime("%Y-%m-%d")
    lm_end_iso = lm_end.strftime("%Y-%m-%d")
    cm_start_iso = cm_start.strftime("%Y-%m-%d")
    today_iso = today_dt.strftime("%Y-%m-%d")

    buckets = {b: {"ytd": 0.0, "last_month": 0.0, "day_before": 0.0, "yesterday": 0.0, "mtd": 0.0}
               for b in _DRG_ROWS_ORDER}
    for e in src_rows:
        d = e.get("date")
        b = e.get("bucket")
        if _is_amazon_fba_value(b):
            b = "Amazon"
        if not d or b not in buckets:
            continue
        rev = float(e.get("rev") or 0)
        slot = buckets[b]
        if fy_start_iso <= d <= today_iso:
            slot["ytd"] += rev
        if d == yest_iso:
            slot["yesterday"] += rev
        if d == dbef_iso:
            slot["day_before"] += rev
        if lm_start_iso <= d <= lm_end_iso:
            slot["last_month"] += rev
        if cm_start_iso <= d <= today_iso:
            slot["mtd"] += rev

    tgt = {b: 0.0 for b in _DRG_ROWS_ORDER}
    for t in targets:
        if t.get("month") != cur_month:
            continue
        ch = str(t.get("channel") or "").strip().lower()
        matched = None
        for b, aliases in _DRG_TARGET_ALIASES.items():
            if ch in aliases:
                matched = b
                break
        tgt[matched if matched else _DRG_OTHER_BUCKET] += (t.get("sp_target") or 0.0)

    rows = []
    tot = {"ytd": 0.0, "last_month": 0.0, "day_before": 0.0, "yesterday": 0.0, "mtd": 0.0, "mtd_target": 0.0}
    for b in _DRG_ROWS_ORDER:
        slot = buckets[b]
        mtd_target = tgt.get(b, 0.0)
        ach = round((slot["mtd"] / mtd_target * 100), 1) if mtd_target else 0.0
        rows.append({
            "channel": _DRG_LABELS.get(b, b), "ytd": slot["ytd"],
            "last_month": slot["last_month"], "day_before": slot["day_before"],
            "yesterday": slot["yesterday"], "mtd": slot["mtd"],
            "mtd_target": mtd_target, "mtd_achievement": ach,
        })
        for key in ("ytd", "last_month", "day_before", "yesterday", "mtd"):
            tot[key] += slot[key]
        tot["mtd_target"] += mtd_target
    tot["mtd_achievement"] = round((tot["mtd"] / tot["mtd_target"] * 100), 1) if tot["mtd_target"] else 0.0
    rows.sort(key=lambda r: r["ytd"], reverse=True)

    source_errors = [f"{name}: {m.get('error')}" for name, m in source_meta.items() if m.get("error")]
    return {
        "rows": rows, "totals": tot, "fy_label": fy_label,
        "month_label": today_dt.strftime("%b %Y"),
        "yesterday_label": yest_dt.strftime("%d-%b"),
        "day_before_label": dbef_dt.strftime("%d-%b"),
        "last_month_label": lm_start.strftime("%b %Y"),
        "title_date": today_dt.strftime("%d - %b - %Y"),
        "source_meta": source_meta, "source_errors": source_errors,
    }


@app.route("/api/daily_revenue_glimpse_marketplace")
def api_daily_revenue_glimpse_marketplace():
    if session.get("role") not in ("admin", "employee"):
        return jsonify({"error": "login required"}), 401
    try:
        fresh = request.args.get("fresh", "0").strip().lower() in ("1", "true", "yes")
        return jsonify(_build_daily_revenue_glimpse_marketplace(force=fresh))
    except Exception as e:
        return jsonify({"error": f"marketplace daily revenue glimpse build failed: {e}"}), 500


def _build_daily_revenue_glimpse(force=False):
    """Daily Revenue Glimpse: channel-wise YTD / Last Month / This Month / Day
    Before / Yesterday / This Month Target / Achievement %. In the Target tab,
    Amazon is one consolidated cossa_orderdate bucket (standard Amazon + former
    Amazon FBA); remaining channels keep their approved
    sources. Rows are sorted by YTD revenue descending."""
    src_rows = _fetch_drg_source_rows(force=force)
    targets = _fetch_target_rows()

    today_dt = now_ist().replace(hour=0, minute=0, second=0, microsecond=0, tzinfo=None)
    yest_dt  = today_dt - timedelta(days=1)
    dbef_dt  = today_dt - timedelta(days=2)
    cm_start = today_dt.replace(day=1)
    cur_month = today_dt.strftime("%Y-%m")

    lm_end   = cm_start - timedelta(days=1)
    lm_start = lm_end.replace(day=1)

    fy_label, fy_start_dt, _fy_end_dt = fy_bounds(today_dt.replace(tzinfo=TZ))
    fy_start_iso = fy_start_dt.strftime("%Y-%m-%d")

    yest_iso     = yest_dt.strftime("%Y-%m-%d")
    dbef_iso     = dbef_dt.strftime("%Y-%m-%d")
    lm_start_iso = lm_start.strftime("%Y-%m-%d")
    lm_end_iso   = lm_end.strftime("%Y-%m-%d")
    cm_start_iso = cm_start.strftime("%Y-%m-%d")
    today_iso    = today_dt.strftime("%Y-%m-%d")

    buckets = {b: {"ytd": 0.0, "last_month": 0.0, "day_before": 0.0, "yesterday": 0.0, "mtd": 0.0}
               for b in _DRG_ROWS_ORDER}

    for e in src_rows:
        d = e.get("date")
        if not d or d == "N/A":
            continue
        rev = float(e.get("rev") or 0)
        b = e.get("bucket") or _drg_bucket(e.get("channel"), e.get("sub_channel"), e.get("type"))
        if _is_amazon_fba_value(b):
            b = "Amazon"
        slot = buckets[b]
        if fy_start_iso <= d <= today_iso:
            slot["ytd"] += rev
        if d == yest_iso:
            slot["yesterday"] += rev
        if d == dbef_iso:
            slot["day_before"] += rev
        if lm_start_iso <= d <= lm_end_iso:
            slot["last_month"] += rev
        if cm_start_iso <= d <= today_iso:
            slot["mtd"] += rev

    # MTD Target: current month ke Target sheet rows ko bucket ke hisaab se jodo
    tgt = {b: 0.0 for b in _DRG_ROWS_ORDER}
    for t in targets:
        if t["month"] != cur_month:
            continue
        ch = (t.get("channel") or "").strip().lower()
        matched = None
        for b, aliases in _DRG_TARGET_ALIASES.items():
            if ch in aliases:
                matched = b
                break
        tgt[matched if matched else _DRG_OTHER_BUCKET] += (t.get("sp_target") or 0.0)

    rows = []
    tot = {"ytd": 0.0, "last_month": 0.0, "day_before": 0.0, "yesterday": 0.0, "mtd": 0.0, "mtd_target": 0.0}
    for b in _DRG_ROWS_ORDER:
        slot = buckets[b]
        mtd_target = tgt.get(b, 0.0)
        ach = round((slot["mtd"] / mtd_target * 100), 1) if mtd_target else 0.0
        rows.append({
            "channel": _DRG_LABELS.get(b, b),
            "ytd": slot["ytd"],
            "last_month": slot["last_month"], "day_before": slot["day_before"],
            "yesterday": slot["yesterday"], "mtd": slot["mtd"],
            "mtd_target": mtd_target, "mtd_achievement": ach,
        })
        tot["ytd"]        += slot["ytd"]
        tot["last_month"] += slot["last_month"]; tot["day_before"] += slot["day_before"]
        tot["yesterday"]  += slot["yesterday"];  tot["mtd"]        += slot["mtd"]
        tot["mtd_target"] += mtd_target
    tot["mtd_achievement"] = round((tot["mtd"] / tot["mtd_target"] * 100), 1) if tot["mtd_target"] else 0.0

    # Max revenue wale channel sabse upar (YTD ke hisaab se descending sort)
    rows.sort(key=lambda r: r["ytd"], reverse=True)

    return {
        "rows": rows, "totals": tot,
        "fy_label": fy_label,
        "month_label": today_dt.strftime("%b %Y"),
        "yesterday_label": yest_dt.strftime("%d-%b"),
        "day_before_label": dbef_dt.strftime("%d-%b"),
        "last_month_label": lm_start.strftime("%b %Y"),
        "title_date": today_dt.strftime("%d - %b - %Y"),
    }

@app.route("/api/daily_revenue_glimpse")
def api_daily_revenue_glimpse():
    if session.get("role") not in ("admin", "employee"):
        return jsonify({"error": "login required"}), 401
    try:
        fresh = request.args.get("fresh", "0").strip().lower() in ("1", "true", "yes")
        rep = _build_daily_revenue_glimpse(force=fresh)
        return jsonify(rep)
    except Exception as e:
        return jsonify({"error": f"daily revenue glimpse build failed: {e}"}), 500

# ── RAKHI — State/UT-wise Sold Qty ──
# Source: "Website" order sheet (same workbook, gid=682845871) — har row
# ek order-line hai jisme SKU, Qty aur "Final Billing Address" hoti hai.
# Final Billing Address hamesha "...,,CITYNAME-PINCODE" format me khatam
# hoti hai — us 6-digit PIN se State/UT nikalte hain (India Post ke
# standard PIN-region ranges par based). Matching seedha SKU se hoti hai:
# sirf wahi rows count hoti hain jinka SKU curated Rakhi SKU list me hai —
# yeh check client-side (Rakhi tab JS, _rkhInWhitelist) hota hai.
RAKHI_WEBSITE_ADDR_URL = ("https://docs.google.com/spreadsheets/d/e/2PACX-1vSFHmWRlOplM6iDI4JYJA6gB8Un"
                           "AJliu-Nuo3av_f2hThuOItMlhhaTA_qiyAo8tbClJLiwsYrC12I-/pub?gid=682845871&single=true&output=csv")
_RKH_CITY_CACHE = {"rows": None, "ts": 0}

# Complete list of all 28 States + 8 UTs of India — Rakhi State/UT table
# hamesha inhi 36 naamon ko dikhata hai (0 Sold Qty wale bhi), taaki
# "jitne bhi India ke States/UT hain sab aane chaiye" poora ho.
INDIA_STATES_UTS = [
    "Andhra Pradesh", "Arunachal Pradesh", "Assam", "Bihar", "Chhattisgarh",
    "Goa", "Gujarat", "Haryana", "Himachal Pradesh", "Jharkhand", "Karnataka",
    "Kerala", "Madhya Pradesh", "Maharashtra", "Manipur", "Meghalaya",
    "Mizoram", "Nagaland", "Odisha", "Punjab", "Rajasthan", "Sikkim",
    "Tamil Nadu", "Telangana", "Tripura", "Uttar Pradesh", "Uttarakhand",
    "West Bengal",
    "Andaman & Nicobar Islands", "Chandigarh",
    "Dadra & Nagar Haveli and Daman & Diu", "Delhi", "Jammu & Kashmir",
    "Ladakh", "Lakshadweep", "Puducherry"
]

def _pincode_to_state(pin):
    """Return the Indian State/UT for a 6-digit PIN.

    The old implementation used a few very broad carve-outs (notably
    605xxx/609xxx for Puducherry and 813xxx-835xxx for Jharkhand) that could
    place valid Tamil Nadu/Bihar orders in the wrong State.  This version
    keeps the broad India Post postal regions, but applies only conservative
    and well-known 3/6-digit exceptions at shared boundaries.
    """
    digits = re.sub(r"\D", "", str(pin or ""))
    if len(digits) < 6:
        return ""
    try:
        p = int(digits[:6])
    except Exception:
        return ""
    if not (100000 <= p <= 899999):
        return ""  # 9xxxxx is APS / non-State postal routing

    d2 = p // 10000
    d3 = p // 1000

    # Union Territories and shared postal-region exceptions.
    if 110001 <= p <= 110099:
        return "Delhi"
    # 160055/59/62/70 etc. are Mohali (Punjab), so do not classify every
    # 160xxx PIN as Chandigarh.
    if 160001 <= p <= 160047 or 160101 <= p <= 160103:
        return "Chandigarh"
    # Ladakh primarily uses 194xxx; 193xxx belongs to J&K postal districts.
    if 194001 <= p <= 194999:
        return "Ladakh"

    # Uttarakhand shares the UP postal region. Use conservative sub-ranges
    # instead of treating all 246-249 and 262-263 as Uttarakhand.
    if 244700 <= p <= 244799:
        return "Uttarakhand"
    if 246000 <= p <= 246999:
        return "Uttarakhand"
    if 247600 <= p <= 247699:
        return "Uttarakhand"
    if 248000 <= p <= 249999:
        return "Uttarakhand"
    if 262500 <= p <= 262599 or 263000 <= p <= 263999:
        return "Uttarakhand"

    if 396191 <= p <= 396240 or 362520 <= p <= 362599:
        return "Dadra & Nagar Haveli and Daman & Diu"
    if 403001 <= p <= 403899:
        return "Goa"

    # AP/Telangana split.
    if 500000 <= p <= 509999:
        return "Telangana"
    if 510000 <= p <= 535999:
        return "Andhra Pradesh"

    # Puducherry has small enclaves inside TN/AP/Kerala postal regions.
    # Keep this intentionally precise; the previous 605001-605649 and
    # 609601-609816 ranges incorrectly swallowed many Tamil Nadu PINs.
    puducherry_pins = {
        *range(605001, 605015),
        605101, 605102, 605104, 605105, 605106, 605107, 605110, 605111,
        605501, 605502,
        *range(609601, 609610),
        533464,  # Yanam
        673310,  # Mahe
    }
    if p in puducherry_pins:
        return "Puducherry"
    if 682551 <= p <= 682559:
        return "Lakshadweep"
    if 737001 <= p <= 737139:
        return "Sikkim"
    if 744101 <= p <= 744304:
        return "Andaman & Nicobar Islands"

    # North-East 79x split.
    if d2 == 79:
        if 790 <= d3 <= 792:
            return "Arunachal Pradesh"
        if 793 <= d3 <= 794:
            return "Meghalaya"
        if d3 == 795:
            return "Manipur"
        if d3 == 796:
            return "Mizoram"
        if 797 <= d3 <= 798:
            return "Nagaland"
        if d3 == 799:
            return "Tripura"
        return ""

    # Bihar/Jharkhand share 80-85. 813 is Bhagalpur/Banka (Bihar), while
    # Jharkhand uses the following district prefixes.
    if 800 <= d3 <= 855:
        jharkhand_prefixes = {
            814, 815, 816, 822,
            825, 826, 827, 828, 829,
            831, 832, 833, 834, 835,
        }
        return "Jharkhand" if d3 in jharkhand_prefixes else "Bihar"

    d2_state = {
        11: "Delhi", 12: "Haryana", 13: "Haryana",
        14: "Punjab", 15: "Punjab", 16: "Punjab",
        17: "Himachal Pradesh",
        18: "Jammu & Kashmir", 19: "Jammu & Kashmir",
        20: "Uttar Pradesh", 21: "Uttar Pradesh", 22: "Uttar Pradesh",
        23: "Uttar Pradesh", 24: "Uttar Pradesh", 25: "Uttar Pradesh",
        26: "Uttar Pradesh", 27: "Uttar Pradesh", 28: "Uttar Pradesh",
        30: "Rajasthan", 31: "Rajasthan", 32: "Rajasthan",
        33: "Rajasthan", 34: "Rajasthan",
        36: "Gujarat", 37: "Gujarat", 38: "Gujarat", 39: "Gujarat",
        40: "Maharashtra", 41: "Maharashtra", 42: "Maharashtra",
        43: "Maharashtra", 44: "Maharashtra",
        45: "Madhya Pradesh", 46: "Madhya Pradesh", 47: "Madhya Pradesh",
        48: "Madhya Pradesh", 49: "Chhattisgarh",
        56: "Karnataka", 57: "Karnataka", 58: "Karnataka", 59: "Karnataka",
        60: "Tamil Nadu", 61: "Tamil Nadu", 62: "Tamil Nadu",
        63: "Tamil Nadu", 64: "Tamil Nadu", 65: "Tamil Nadu", 66: "Tamil Nadu",
        67: "Kerala", 68: "Kerala", 69: "Kerala",
        70: "West Bengal", 71: "West Bengal", 72: "West Bengal",
        73: "West Bengal", 74: "West Bengal",
        75: "Odisha", 76: "Odisha", 77: "Odisha",
        78: "Assam",
    }
    return d2_state.get(d2, "")


def _geo_key(value):
    """Case/punctuation-insensitive key for State and city validation."""
    s = str(value or "").casefold().replace("&", " and ")
    s = re.sub(r"\b(dist(?:rict)?|city|urban|rural)\b", " ", s)
    return re.sub(r"[^a-z0-9]+", " ", s).strip()


# State aliases seen in free-form addresses.
_STATE_KEY_TO_NAME = {_geo_key(s): s for s in INDIA_STATES_UTS}
_STATE_KEY_TO_NAME.update({
    "orissa": "Odisha", "pondicherry": "Puducherry",
    "uttaranchal": "Uttarakhand", "nct delhi": "Delhi",
    "jammu kashmir": "Jammu & Kashmir", "j and k": "Jammu & Kashmir",
    "andaman nicobar": "Andaman & Nicobar Islands",
    "dadra nagar haveli daman diu": "Dadra & Nagar Haveli and Daman & Diu",
})


# Known unambiguous Indian city aliases.  This is used only as a validation
# guard: when the address says a known city from State A but the PIN belongs
# to State B, PIN wins and a PIN-area/city hint replaces the bad source city.
_CITY_STATE_ALIASES = {}
def _register_city(state, canonical, *aliases):
    for alias in (canonical,) + aliases:
        _CITY_STATE_ALIASES[_geo_key(alias)] = (state, canonical)

