def _pincode_city_hint(pin, state):
    digits = re.sub(r"\D", "", str(pin or ""))
    if len(digits) < 3:
        return ""
    prefix = int(digits[:3])
    hint = _PIN3_CITY_HINTS.get(prefix)
    if hint and hint[0] == state:
        return hint[1]
    if state == "Delhi":
        return "New Delhi"
    if state == "Chandigarh":
        return "Chandigarh"
    return f"PIN {prefix} Area"


def _extract_city_pin_from_address(addr):
    """Extract city + PIN from Website column E (Final Billing Address).

    The Website source is free-form text.  Prefer the city immediately before
    the final Indian PIN (for example ``MUMBAI-400071``), then fall back to a
    known city alias or the last meaningful comma-delimited address token when
    a PIN is missing.  This keeps festival city reporting usable across
    uppercase/lowercase/mixed text, line breaks and minor punctuation changes.
    """
    s = str(addr or "")
    try:
        import unicodedata
        s = unicodedata.normalize("NFKC", s)
    except Exception:
        pass
    s = s.replace("\u00a0", " ").strip()
    if not s:
        return "", ""

    matches = list(re.finditer(r"(?<!\d)([1-8]\d{5})(?!\d)", s))
    pin = matches[-1].group(1) if matches else ""
    prefix = s[:matches[-1].start()] if matches else s
    prefix = prefix.strip(" \t\r\n,;:-–—/")

    # Strongest Website pattern: the city is written directly before the PIN,
    # e.g. MUMBAI-400071 / PUNE 411006 / BANGALORE-560033.
    if pin:
        tail_match = re.search(
            r"(?:^|[,;\n])\s*([A-Za-z][A-Za-z .&'()/-]{1,60}?)\s*[-–— ]\s*$",
            prefix, re.I
        )
        if tail_match:
            candidate = re.sub(r"\s+", " ", tail_match.group(1)).strip(" .,-–—/")
            # If the captured tail contains a state token after the city, the
            # generic cleanup below will reduce it safely.
            if candidate:
                prefix = prefix[:tail_match.start(1)] + candidate

    parts = [re.sub(r"\s+", " ", p).strip(" .;:-–—/")
             for p in re.split(r"[,;\n]+", prefix)]
    parts = [p for p in parts if p]

    pin_state = _pincode_to_state(pin) if pin else ""
    while parts and _geo_key(parts[-1]) in {"india", "bharat"}:
        parts.pop()
    while len(parts) > 1 and _geo_key(parts[-1]) in _STATE_KEY_TO_NAME:
        tail_key = _geo_key(parts[-1])
        city_alias = _CITY_STATE_ALIASES.get(tail_key)
        if city_alias and (not pin_state or city_alias[0] == pin_state):
            break
        parts.pop()

    city = parts[-1] if parts else ""
    if city:
        chunks = [c.strip() for c in re.split(r"\s*[-–—/]\s*", city) if c.strip()]
        while len(chunks) > 1 and _geo_key(chunks[-1]) in _STATE_KEY_TO_NAME:
            tail_key = _geo_key(chunks[-1])
            city_alias = _CITY_STATE_ALIASES.get(tail_key)
            if city_alias and (not pin_state or city_alias[0] == pin_state):
                break
            chunks.pop()
        city = chunks[-1] if chunks else city
        city = re.sub(r"\b(?:district|dist\.?|near)\b.*$", "", city, flags=re.I)
        city = re.sub(r"\s+", " ", city).strip(" .,-")

    # PIN-less fallback: scan the full address for the last known city alias.
    # Prefer that alias even when the last comma token also contains a State
    # name (for example "Bangalore Karnataka").  When a PIN exists, PIN/state
    # validation remains authoritative.
    if not pin:
        hay = _geo_key(s)
        best = None
        for alias_key, (alias_state, canonical) in _CITY_STATE_ALIASES.items():
            m = list(re.finditer(r"(?:^| )" + re.escape(alias_key) + r"(?: |$)", hay))
            if m:
                pos = m[-1].start()
                if best is None or pos > best[0]:
                    best = (pos, alias_state, canonical)
        if best:
            city = best[2]

    return (city.title() if city else ""), pin


def _extract_pin_from_address(addr):
    """Backward-compatible PIN-only helper."""
    return _extract_city_pin_from_address(addr)[1]


def _normalize_city_for_state(city, state, pin=""):
    """Validate address city against PIN-derived State and correct mismatch.

    A known cross-State city never remains under the wrong State.  When the
    source city conflicts with the PIN, a conservative PIN-prefix hint is
    used (for example a 302xxx Rajasthan address becomes Jaipur rather than
    showing Darjeeling under Rajasthan).
    """
    city = re.sub(r"\s+", " ", str(city or "")).strip(" .,-")
    state = _STATE_KEY_TO_NAME.get(_geo_key(state), str(state or "").strip())
    if not state:
        return city.title()

    key = _geo_key(city)
    known = _CITY_STATE_ALIASES.get(key)
    if not city or key in {"india", "bharat"}:
        return _pincode_city_hint(pin, state)
    # Puducherry, Delhi and Chandigarh can be both State/UT and city names.
    # Treat them as cities when the PIN-derived State agrees.
    if key in _STATE_KEY_TO_NAME and not (known and known[0] == state):
        return _pincode_city_hint(pin, state)

    if known:
        known_state, canonical = known
        if known_state != state:
            return _pincode_city_hint(pin, state)
        city = canonical

    if state == "Delhi" and key in {
        "north", "south", "east", "west", "north east", "north west",
        "south east", "south west", "central"
    }:
        city = f"{city} Delhi"
    return city.title()


def _fetch_rkh_sku_city_rows(force=False):
    """Build validated multi-channel city rows for Rakhi and concentration.

    PIN-derived State is authoritative. Cancelled/failed and explicit
    zero/negative-quantity rows are excluded. If no Qty column exists, one
    row is treated as one sold unit. Diagnostics expose how many source city
    labels were corrected so data quality can be monitored.
    """
    if (not force and _RKH_CITY_CACHE["rows"] is not None
            and (time.time() - _RKH_CITY_CACHE["ts"] < 600)):
        return _RKH_CITY_CACHE["rows"], _RKH_CITY_CACHE.get("diag", {})
    out = []
    diag = {
        "rows_total": 0, "rows_used": 0, "columns_found": False,
        "rows_cancelled": 0, "rows_nonpositive_qty": 0,
        "city_labels_corrected": 0, "error": None,
    }
    try:
        df = _fetch_csv_fresh(RAKHI_WEBSITE_ADDR_URL)
        df.columns = [str(c).strip() for c in df.columns]
        cols = list(df.columns)
        diag["rows_total"] = len(df)
        diag["all_columns"] = cols[:20]
        C_SKU = find_col(cols, "New SKU", "SKU", "sku code", "product sku", "item sku") \
                or (cols[0] if len(cols) > 0 else None)
        qty_keys = {
            "finalqty", "finalquantity", "soldqty", "saleqty",
            "orderqty", "orderedqty", "totalqty", "quantity", "qty"
        }
        C_QTY = next((c for c in cols if re.sub(r"[^a-z0-9]", "", c.lower()) in qty_keys), None)
        # Website city/address source is the physical E column.  Keep header
        # matching only as fallback for short/malformed exports.
        C_ADDR = ((cols[4] if len(cols) > 4 else None)
                  or find_col(cols, "Final Billing Address", "billing address",
                              "final address", "address"))
        C_STATUS = find_col(cols, "Sale Order Status", "Order Status", "status")
        C_DATE = find_col(cols, "Order_Date", "Order Date", "Display Order Date",
                          "Created", "Created At", "Dispatch Date", "Date")
        C_RTO = find_col(cols, "RTO Qty", "Return Qty", "Returned Qty")
        C_REV = find_col(cols, "Total Price W/O GST", "Net Revenue", "Final Revenue",
                         "Line Revenue", "Total Price", "Order Value", "Total Amount")
        C_SP = find_col(cols, "Selling Price", "Sale Price", "Unit Selling Price", "Unit Price")
        diag["sku_col"] = C_SKU
        diag["qty_col"] = C_QTY
        diag["addr_col"] = C_ADDR
        diag["status_col"] = C_STATUS
        diag["return_qty_col"] = C_RTO
        diag["revenue_col"] = C_REV
        if C_SKU and C_ADDR:
            diag["columns_found"] = True
            for _, r in df.iterrows():
                status = str(r.get(C_STATUS, "") or "").strip().casefold() if C_STATUS else ""
                if status and any(x in status for x in ("cancel", "void", "failed")):
                    diag["rows_cancelled"] += 1
                    continue
                sku = str(r.get(C_SKU, "") or "").strip()
                if not sku:
                    continue
                raw_city, pin = _extract_city_pin_from_address(r.get(C_ADDR, ""))
                if not pin:
                    continue
                state = _pincode_to_state(pin)
                if not state:
                    continue
                city = _normalize_city_for_state(raw_city, state, pin)
                if _geo_key(city) != _geo_key(raw_city):
                    diag["city_labels_corrected"] += 1
                gross_qty = to_num(r.get(C_QTY, 0)) if C_QTY else 1.0
                return_qty = max(0.0, to_num(r.get(C_RTO, 0))) if C_RTO else 0.0
                qty = max(0.0, gross_qty - return_qty)
                if C_QTY and qty <= 0:
                    diag["rows_nonpositive_qty"] += 1
                    continue
                if not C_QTY:
                    qty = 1.0
                revenue = to_num(r.get(C_REV, 0)) if C_REV else 0.0
                if revenue <= 0 and C_SP:
                    revenue = to_num(r.get(C_SP, 0)) * qty
                elif revenue > 0 and gross_qty > 0 and qty < gross_qty:
                    revenue *= qty / gross_qty
                dt_value = parse_date_any(r.get(C_DATE, "")) if C_DATE else None
                out.append({
                    "sku": sku, "qty": float(qty), "state": state,
                    "city": city, "pin": pin, "source": "Website",
                    "type": "Website", "channel": "D2C",
                    "date": dt_value.strftime("%Y-%m-%d") if dt_value else "",
                    "revenue": round(float(revenue), 2) if revenue > 0 else 0.0,
                })
                diag["rows_used"] += 1
        else:
            diag["error"] = "Could not find SKU / Final Billing Address columns in the sheet."
    except Exception as e:
        diag["error"] = str(e)[:300]
        print("Rakhi SKU-city rows fetch failed:", str(e)[:160])

    # Myntra source: SKU No., Qty., Destination pincode and Destination City.
    # PIN remains authoritative for State; the supplied city is validated
    # against it before being exposed to Rakhi and concentration views.
    diag.update({"myntra_rows_total": 0, "myntra_rows_used": 0,
                 "myntra_columns_found": False, "myntra_error": None})
    try:
        mdf = _fetch_csv_fresh(MYNTRA_SALES_URL)
        mdf.columns = [str(c).strip() for c in mdf.columns]
        mcols = list(mdf.columns)
        diag["myntra_rows_total"] = len(mdf)
        diag["myntra_all_columns"] = mcols[:24]
        M_SKU = find_col(mcols, "SKU No.", "SKU No", "Seller_sku", "Seller SKU", "SKU", "Item Code")
        M_QTY = find_col(mcols, "Qty.", "Qty", "Quantity", "Sold Qty")
        M_NET_QTY = find_col(mcols, "Net Qty", "Final Qty", "Sold Qty")
        M_RETURN_QTY = find_col(mcols, "Return Qty", "Returned Qty")
        M_PIN = find_col(mcols, "Destination pincode", "Destination Pincode", "Destination PIN", "Pincode")
        M_CITY = find_col(mcols, "Destination City", "City")
        M_DATE = find_col(mcols, "Order_Date", "Order Date", "OrderDate",
                          "Created", "Created At", "Packed On", "Date")
        M_STATUS = find_col(mcols, "Status", "Order Status")
        M_REV = find_col(mcols, "Selling value", "Net Amount", "Net Revenue",
                         "Seller Price", "Payout to Seller", "Selling Price")
        diag["myntra_resolved"] = {"sku": M_SKU, "qty": M_QTY,
                                   "net_qty": M_NET_QTY, "return_qty": M_RETURN_QTY,
                                   "pin": M_PIN, "city": M_CITY, "date": M_DATE,
                                   "status": M_STATUS, "revenue": M_REV}
        if M_SKU and M_PIN and M_CITY:
            diag["myntra_columns_found"] = True
            for _, r in mdf.iterrows():
                status = str(r.get(M_STATUS, "") or "").strip().casefold() if M_STATUS else ""
                if status and any(x in status for x in ("cancel", "void", "failed", "return")):
                    continue
                sku = clean(r.get(M_SKU, ""))
                pin = re.sub(r"\D", "", str(r.get(M_PIN, "") or ""))[:6]
                if not sku or len(pin) != 6:
                    continue
                state = _pincode_to_state(pin)
                if not state:
                    continue
                raw_city = clean(r.get(M_CITY, ""))
                city = _normalize_city_for_state(raw_city, state, pin)
                gross_qty = to_num(r.get(M_QTY, 0)) if M_QTY else 1.0
                if M_NET_QTY:
                    qty = to_num(r.get(M_NET_QTY, 0))
                else:
                    qty = gross_qty - (to_num(r.get(M_RETURN_QTY, 0)) if M_RETURN_QTY else 0.0)
                if qty <= 0:
                    continue
                dt = parse_date_any(r.get(M_DATE, "")) if M_DATE else None
                revenue = to_num(r.get(M_REV, 0)) if M_REV else 0.0
                if revenue > 0 and gross_qty > 0 and qty < gross_qty:
                    revenue *= qty / gross_qty
                out.append({"sku": sku, "qty": float(qty), "state": state,
                            "city": city, "pin": pin, "source": "Myntra",
                            "type": "Marketplace", "channel": "Ecom",
                            "date": dt.strftime("%Y-%m-%d") if dt else "",
                            "revenue": round(float(revenue), 2) if revenue > 0 else 0.0})
                diag["myntra_rows_used"] += 1
        else:
            diag["myntra_error"] = "Could not find SKU / Destination pincode / Destination City columns."
    except Exception as e:
        diag["myntra_error"] = str(e)[:300]
        print("Myntra SKU-city rows fetch failed:", str(e)[:160])

    # Remaining marketplace city feeds. Published schemas differ, so every
    # source resolves its own SKU/qty/date/city/state/PIN columns. Ajio is not
    # included because its published sheet currently has no customer city/PIN.
    marketplace_city_sources = [
        {
            "key": "amazon_flipkart", "url": AMAZON_FLIPKART_SALES_URL,
            "fixed_source": "", "platform_names": ("Channel", "Type", "Marketplace", "Status"),
            "sku_names": ("SKU No.", "SKU No", "SKU", "Seller_sku_code"),
            "qty_names": ("Net Qty", "Final Qty", "Sold Qty"),
            "gross_qty_names": ("Qty.", "Qty", "Order Qty", "Quantity"),
            "return_qty_names": ("Return Qty", "Returned Qty"),
            "geo_sets": ({
                "city_names": ("Destination City", "City"),
                "state_names": ("Destination state", "Destination State", "State"),
                "pin_names": ("Destination pincode", "Destination Pincode", "Pincode"),
            },),
            "date_names": ("Order_Date", "Order Date", "Packed On"),
            "revenue_names": ("Selling value", "Seller Price", "Payout to Seller"),
            "revenue_is_net": False,
            "status_names": (),
        },
        {
            "key": "nykaa", "url": NYKAA_SALES_URL,
            "fixed_source": "Nykaa", "platform_names": (),
            "sku_names": ("SKU", "SKUCode", "SKU Code"),
            "qty_names": ("Net Qty", "Final Qty", "Sold Qty"),
            "gross_qty_names": ("Order Qty", "Shipped Qty", "Qty"),
            "return_qty_names": ("Return Qty", "Returned Qty"),
            "geo_sets": ({
                "city_names": ("city", "City"),
                "state_names": ("State",),
                "pin_names": ("Pincode", "PIN Code"),
            },),
            "date_names": ("Order_Date", "Order Date", "OrderDate"),
            "revenue_names": ("Net Amount", "LineItem Total", "SellingPrice"),
            "revenue_is_net": True,
            "status_names": (),
        },
        {
            "key": "tata", "url": TATA_SALES_URL,
            "fixed_source": "Tata", "platform_names": (),
            "sku_names": ("SKU", "Item Code"),
            "qty_names": ("Net Qty", "Final Qty", "Sold Qty"),
            "gross_qty_names": ("Order Qty", "Qty"),
            "return_qty_names": ("Return Qty", "Returned Qty"),
            # Tata changed its current-period population: older rows use
            # Shipping* while recent rows populate BillingCity/BillingPincode.
            # Materialize and test both row-wise instead of resolving only the
            # first header and silently dropping all current Tata cities.
            "geo_sets": (
                {
                    "city_names": ("ShippingCity", "Shipping City"),
                    "state_names": ("ShippingState", "Shipping State"),
                    "pin_names": ("ShippingPincode", "Shipping Pincode"),
                },
                {
                    "city_names": ("BillingCity", "Billing City"),
                    "state_names": ("BillingState", "Billing State"),
                    "pin_names": ("BillingPincode", "Billing Pincode"),
                },
            ),
            "date_names": ("Order_Date", "Order Date", "OrderDate"),
            "revenue_names": ("Net Amount", "Final Invoice Amount", "Customer Collected Amount"),
            "revenue_is_net": True,
            "status_names": ("OrderStatus", "Order Status"),
        },
    ]
    for spec in marketplace_city_sources:
        frame = None
        key = spec["key"]
        source_diag = {"rows_total": 0, "rows_used": 0, "columns_found": False, "error": None}
        diag[key] = source_diag
        try:
            groups = [spec["sku_names"], spec["qty_names"],
                      spec["gross_qty_names"], spec["return_qty_names"],
                      spec["date_names"], spec["revenue_names"]]
            for geo_set in spec["geo_sets"]:
                groups.extend((geo_set["city_names"], geo_set["state_names"], geo_set["pin_names"]))
            if spec["platform_names"]:
                groups.append(spec["platform_names"])
            if spec["status_names"]:
                groups.append(spec["status_names"])
            frame = _fetch_csv_fresh(spec["url"], select_groups=groups)
            frame.columns = [str(c).strip() for c in frame.columns]
            cols = list(frame.columns)
            source_diag["rows_total"] = len(frame)
            C_SKU = find_col(cols, *spec["sku_names"])
            C_QTY = find_col(cols, *spec["qty_names"])
            C_GROSS_QTY = find_col(cols, *spec["gross_qty_names"])
            C_RETURN_QTY = find_col(cols, *spec["return_qty_names"])
            C_DATE = find_col(cols, *spec["date_names"])
            C_REV = find_col(cols, *spec["revenue_names"])
            C_PLATFORM = find_col(cols, *spec["platform_names"]) if spec["platform_names"] else None
            C_STATUS = find_col(cols, *spec["status_names"]) if spec["status_names"] else None
            GEO_COLS = []
            for geo_set in spec["geo_sets"]:
                resolved_geo = {
                    "city": find_col(cols, *geo_set["city_names"]),
                    "state": find_col(cols, *geo_set["state_names"]),
                    "pin": find_col(cols, *geo_set["pin_names"]),
                }
                if resolved_geo["city"] or resolved_geo["pin"]:
                    GEO_COLS.append(resolved_geo)
            source_diag["resolved"] = {
                "sku": C_SKU, "qty": C_QTY, "gross_qty": C_GROSS_QTY,
                "return_qty": C_RETURN_QTY, "geo_sets": GEO_COLS,
                "date": C_DATE, "revenue": C_REV,
                "platform": C_PLATFORM, "status": C_STATUS,
            }
            if not C_SKU or not GEO_COLS:
                raise ValueError("required SKU/city/PIN columns not found")
            source_diag["columns_found"] = True
            for row in _df_chunks(frame):
                status = str(row.get(C_STATUS, "") or "").strip().casefold() if C_STATUS else ""
                if status and any(flag in status for flag in ("cancel", "void", "failed")):
                    continue
                sku = clean(row.get(C_SKU, ""))
                gross_qty = to_num(row.get(C_GROSS_QTY, 0)) if C_GROSS_QTY else None
                if C_QTY:
                    qty = to_num(row.get(C_QTY, 0))
                elif gross_qty is not None:
                    qty = gross_qty - (to_num(row.get(C_RETURN_QTY, 0)) if C_RETURN_QTY else 0.0)
                else:
                    qty = 1.0
                if not sku or qty <= 0:
                    continue
                source = spec["fixed_source"]
                if not source:
                    platform_token = re.sub(r"[^a-z0-9]", "", str(row.get(C_PLATFORM, "") or "").casefold())
                    source = "Amazon" if "amazon" in platform_token else "Flipkart" if "flipkart" in platform_token else ""
                if not source:
                    continue
                pin = raw_state = raw_city = state = ""
                for geo in GEO_COLS:
                    candidate_pin = re.sub(r"\D", "", str(row.get(geo["pin"], "") or ""))[:6] if geo["pin"] else ""
                    candidate_state = clean(row.get(geo["state"], "")) if geo["state"] else ""
                    candidate_city = clean(row.get(geo["city"], "")) if geo["city"] else ""
                    candidate_state = (_pincode_to_state(candidate_pin)
                                       if len(candidate_pin) == 6 else
                                       _STATE_KEY_TO_NAME.get(_geo_key(candidate_state), candidate_state.title()))
                    if not candidate_state:
                        continue
                    # A valid PIN is enough to keep the row. If the source's
                    # city is empty (or contains only a State label), the PIN
                    # normalizer supplies a conservative city/area label.
                    if not candidate_city:
                        candidate_city = candidate_state
                    pin, raw_state, raw_city, state = (
                        candidate_pin, candidate_state, candidate_city, candidate_state
                    )
                    break
                if not state:
                    continue
                city = _normalize_city_for_state(raw_city, state, pin)
                dt = parse_date_any(row.get(C_DATE, "")) if C_DATE else None
                revenue = to_num(row.get(C_REV, 0)) if C_REV else 0.0
                if (revenue > 0 and not spec.get("revenue_is_net")
                        and gross_qty is not None and gross_qty > 0 and qty < gross_qty):
                    revenue *= qty / gross_qty
                out.append({
                    "sku": sku, "qty": float(qty), "state": state, "city": city,
                    "pin": pin, "source": source,
                    "type": "Marketplace", "channel": "Ecom",
                    "date": dt.strftime("%Y-%m-%d") if dt else "",
                    "revenue": round(float(revenue), 2) if revenue > 0 else 0.0,
                })
                source_diag["rows_used"] += 1
        except Exception as e:
            source_diag["error"] = str(e)[:300]
            print(f"{key} SKU-city rows fetch failed:", str(e)[:160])
        finally:
            if frame is not None:
                del frame
            _gc.collect()
    _RKH_CITY_CACHE["rows"] = out
    _RKH_CITY_CACHE["diag"] = diag
    _RKH_CITY_CACHE["ts"] = time.time()
    return out, diag

@app.route("/api/rakhi-cities")
def api_rakhi_cities():
    if session.get("role") not in ("admin", "employee"):
        return jsonify({"error": "login required"}), 401
    try:
        force = str(request.args.get("force", "")).strip().lower() in ("1", "true", "yes")
        rows, diag = _fetch_rkh_sku_city_rows(force=force)
        return jsonify({"rows": rows, "count": len(rows), "diag": diag, "all_states_uts": INDIA_STATES_UTS})
    except Exception as e:
        return jsonify({"error": f"rakhi city rows build failed: {e}"}), 500

@app.route("/api/rakhi-child-cmb-sales/export.xlsx", methods=["POST"])
def api_rakhi_child_cmb_sales_export_xlsx():
    """Export Rakhi child sales in Sheet 1 and CMB-wise sales in Sheet 2."""
    if session.get("role") not in ("admin", "employee"):
        return jsonify({"error": "login required"}), 401
    try:
        import openpyxl
        from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
        from openpyxl.utils import get_column_letter

        payload = request.get_json(silent=True) or {}
        raw_rows = payload.get("rows") or []
        raw_cmb_rows = payload.get("cmb_rows") or []
        raw_individual_rows = payload.get("individual_rows") or []
        if (not isinstance(raw_rows, list) or not isinstance(raw_cmb_rows, list)
                or not isinstance(raw_individual_rows, list)):
            return jsonify({"error": "invalid export rows"}), 400
        if len(raw_rows) > 5000 or len(raw_cmb_rows) > 5000 or len(raw_individual_rows) > 5000:
            return jsonify({"error": "too many export rows"}), 400
        type_label = str(payload.get("type") or "All").strip() or "All"

        def _safe_excel_text(value):
            text = str(value or "")
            # Prevent spreadsheet formula injection in exported text cells.
            if text.startswith(("=", "+", "-", "@")):
                text = "'" + text
            return text

        # -------------------------
        # Sheet 2 source of truth
        # -------------------------
        # Recompute every child-via-CMB quantity from:
        # CMB sold qty × pieces of that exact child required in one CMB.
        # This is what fixes 2x/3x use of the same child inside one parent CMB.
        cmb_rows = []
        cmb_child_totals = {}
        child_parent_labels = {}
        child_parent_breakdowns = {}
        for raw in raw_cmb_rows:
            if not isinstance(raw, dict):
                continue
            cmb_sku = clean(raw.get("sku", "")).upper()
            if not cmb_sku:
                continue
            cmb_sold = to_num(raw.get("cmb_sold", 0))
            raw_children = raw.get("children") or []
            if not isinstance(raw_children, list):
                raw_children = []

            children = []
            seen_child = set()
            for child in raw_children:
                if not isinstance(child, dict):
                    continue
                child_sku = clean(child.get("sku", "")).upper()
                if not child_sku or child_sku in seen_child:
                    continue
                seen_child.add(child_sku)
                pieces = max(1, int(round(to_num(child.get("pieces_per_cmb", 1)) or 1)))
                child_units_sold = cmb_sold * pieces
                child_name = clean(child.get("sku_name", ""))
                children.append({
                    "sku": child_sku,
                    "sku_name": child_name,
                    "cn_name": clean(child.get("cn_name", "")),
                    "pieces_per_cmb": pieces,
                    "child_units_sold": child_units_sold,
                })
                cmb_child_totals[child_sku] = cmb_child_totals.get(child_sku, 0.0) + child_units_sold
                child_parent_labels.setdefault(child_sku, []).append(
                    f"{cmb_sku} x{pieces}" if pieces > 1 else cmb_sku
                )
                child_parent_breakdowns.setdefault(child_sku, []).append(
                    f"{cmb_sku}: {cmb_sold:g} x {pieces} = {child_units_sold:g}"
                )

            children.sort(key=lambda x: x["sku"])
            child_pieces_per_cmb = sum(int(c["pieces_per_cmb"]) for c in children)
            child_units_total = sum(float(c["child_units_sold"]) for c in children)
            cmb_rows.append({
                "sku": cmb_sku,
                "sku_name": clean(raw.get("sku_name", "")),
                "cn_name": clean(raw.get("cn_name", "")),
                "cmb_sold": cmb_sold,
                "distinct_child_skus": len(children),
                "child_pieces_per_cmb": child_pieces_per_cmb,
                "child_units_sold": child_units_total,
                "child_composition": " | ".join(
                    f'{c["sku"]} x {c["pieces_per_cmb"]}' for c in children
                ),
                "child_sales_breakdown": " | ".join(
                    f'{c["sku"]}: {cmb_sold:g} x {c["pieces_per_cmb"]} = {c["child_units_sold"]:g}'
                    for c in children
                ),
            })

        cmb_rows.sort(key=lambda x: (-float(x["cmb_sold"]), x["sku"]))

        # Direct/standalone Rakhi sales for the second section of Sheet 2.
        # These are commercial RKH SKU sales only; CMB child-consumption units
        # deliberately do not enter this section.
        individual_rows = []
        seen_individual = set()
        for raw in raw_individual_rows:
            if not isinstance(raw, dict):
                continue
            sku = clean(raw.get("sku", "")).upper()
            if not sku or sku in seen_individual:
                continue
            sold = to_num(raw.get("individual_sold", raw.get("sold", 0)))
            if sold <= 0:
                continue
            seen_individual.add(sku)
            individual_rows.append({
                "sku": sku,
                "sku_name": clean(raw.get("sku_name", "")),
                "cn_name": clean(raw.get("cn_name", "")),
                "individual_sold": sold,
                "image_url": clean(raw.get("image_url", "")),
            })
        individual_rows.sort(key=lambda x: (-float(x["individual_sold"]), x["sku"]))

        # Backward compatibility for an older cached browser: at minimum use
        # the child rows' own individual sales rather than leaving section 2 blank.
        if not individual_rows:
            for raw in raw_rows:
                if not isinstance(raw, dict):
                    continue
                sku = clean(raw.get("sku", "")).upper()
                sold = to_num(raw.get("individual_sold", 0))
                if not sku or sold <= 0 or sku in seen_individual:
                    continue
                seen_individual.add(sku)
                individual_rows.append({
                    "sku": sku,
                    "sku_name": clean(raw.get("sku_name", "")),
                    "individual_sold": sold,
                    "image_url": clean(raw.get("image_url", "")),
                })
            individual_rows.sort(key=lambda x: (-float(x["individual_sold"]), x["sku"]))

        # -------------------------
        # Sheet 1 child SKU sales
        # -------------------------
        rows = []
        for raw in raw_rows:
            if not isinstance(raw, dict):
                continue
            sku = clean(raw.get("sku", "")).upper()
            if not sku:
                continue
            individual = to_num(raw.get("individual_sold", 0))
            # When Sheet 2 details are present, derive In CMBs Sold only from
            # the server-recomputed CMB breakdown so both sheets reconcile.
            if raw_cmb_rows:
                in_cmb = to_num(cmb_child_totals.get(sku, 0))
                parent_labels = ", ".join(child_parent_labels.get(sku, []))
                parent_breakdown = " | ".join(child_parent_breakdowns.get(sku, []))
                cmb_count = len(child_parent_labels.get(sku, []))
            else:
                # Backward compatibility for an older cached browser client.
                in_cmb = to_num(raw.get("in_cmb_sold", raw.get("total_cmb_sold", 0)))
                parent_labels = clean(raw.get("parent_cmbs", ""))
                parent_breakdown = clean(raw.get("parent_cmb_breakdown", ""))
                cmb_count = max(0, int(to_num(raw.get("cmb_count", 0))))
            rows.append({
                "sku": sku,
                "sku_name": clean(raw.get("sku_name", "")),
                "cn_name": clean(raw.get("cn_name", "")),
                "individual_sold": individual,
                "in_cmb_sold": in_cmb,
                "total_sold": individual + in_cmb,
                "cmb_count": cmb_count,
                "parent_cmbs": parent_labels,
                "parent_cmb_breakdown": parent_breakdown,
                "image_url": clean(raw.get("image_url", "")),
            })

        if not rows:
            return jsonify({"error": "no Rakhi child sales rows to export"}), 400

        wb = openpyxl.Workbook()
        ws = wb.active
        ws.title = "Child SKU Sales"

        title_fill = PatternFill("solid", fgColor="F5E8BE")
        header_fill = PatternFill("solid", fgColor="E6C766")
        header_font = Font(bold=True, color="2B2110")
        total_fill = PatternFill("solid", fgColor="F5E8BE")
        thin = Side(style="thin", color="D9CBA7")
        border = Border(left=thin, right=thin, top=thin, bottom=thin)
        center = Alignment(horizontal="center", vertical="center", wrap_text=True)
        left = Alignment(horizontal="left", vertical="center", wrap_text=True)

        def _style_title_and_headers(sheet, title_text, headers):
            sheet.merge_cells(start_row=1, start_column=1, end_row=1, end_column=len(headers))
            title = sheet.cell(1, 1, title_text)
            title.font = Font(bold=True, size=12, color="2B2110")
            title.fill = title_fill
            title.alignment = center
            for col in range(1, len(headers) + 1):
                sheet.cell(1, col).fill = title_fill
                sheet.cell(1, col).border = border
            for col, header in enumerate(headers, 1):
                cell = sheet.cell(2, col, header)
                cell.font = header_font
                cell.fill = header_fill
                cell.alignment = center
                cell.border = border

        # ===== Sheet 1: Child SKU Sales =====
        child_headers = [
            "Child Rakhi SKU", "CN Name", "SKU Name", "Individual Sold", "In CMBs Sold",
            "Total Sold Qty", "Used In Rakhi CMBs", "Parent Rakhi CMB SKUs (x pieces/CMB)",
            "CMB Sales Breakdown", "Image Link"
        ]
        _style_title_and_headers(
            ws,
            f"Rakhi Child SKU Sales | Type: {type_label} | FY 2026-27",
            child_headers,
        )

        for r_idx, row in enumerate(rows, 3):
            values = [
                _safe_excel_text(row["sku"]),
                _safe_excel_text(row.get("cn_name", "")),
                _safe_excel_text(row["sku_name"]),
                float(row["individual_sold"]),
                float(row["in_cmb_sold"]),
                float(row["total_sold"]),
                int(row["cmb_count"]),
                _safe_excel_text(row["parent_cmbs"]),
                _safe_excel_text(row["parent_cmb_breakdown"]),
                _safe_excel_text(row["image_url"]),
            ]
            for col, value in enumerate(values, 1):
                cell = ws.cell(r_idx, col, value)
                cell.border = border
                cell.alignment = center if col in (4, 5, 6, 7) else left
                if col in (4, 5, 6, 7):
                    cell.number_format = '#,##0.##'
            image_url = str(row["image_url"] or "").strip()
            if image_url.lower().startswith(("http://", "https://")):
                cell = ws.cell(r_idx, 10)
                cell.hyperlink = image_url
                cell.style = "Hyperlink"

        child_data_last_row = ws.max_row
        child_total_row = child_data_last_row + 2
        ws.merge_cells(start_row=child_total_row, start_column=1, end_row=child_total_row, end_column=2)
        label = ws.cell(child_total_row, 1, "TOTAL SOLD QTY")
        label.font = Font(bold=True)
        label.fill = total_fill
        label.alignment = center
        total_individual = sum(float(r["individual_sold"]) for r in rows)
        total_in_cmb = sum(float(r["in_cmb_sold"]) for r in rows)
        total_sold = total_individual + total_in_cmb
        for col, value in ((4, total_individual), (5, total_in_cmb), (6, total_sold)):
            cell = ws.cell(child_total_row, col, value)
            cell.font = Font(bold=True)
            cell.fill = total_fill
            cell.alignment = center
            cell.number_format = '#,##0.##'
        for col in range(1, len(child_headers) + 1):
            ws.cell(child_total_row, col).border = border
            if col not in (1, 4, 5, 6):
                ws.cell(child_total_row, col).fill = total_fill

        ws.freeze_panes = "A3"
        ws.auto_filter.ref = f"A2:{get_column_letter(len(child_headers))}{max(2, child_data_last_row)}"
        child_widths = [22, 34, 34, 17, 17, 18, 20, 48, 70, 55]
        for i, width in enumerate(child_widths, 1):
            ws.column_dimensions[get_column_letter(i)].width = width
        ws.row_dimensions[1].height = 26
        ws.row_dimensions[2].height = 32

        # ===== Sheet 2: CMB sales first, then standalone Rakhi sales =====
        ws2 = wb.create_sheet("CMB Wise Sales")
        section_headers = ["SKU", "CN Name", "SKU Name", "Sold Qty"]
        _style_title_and_headers(
            ws2,
            f"Rakhi CMB Sales | Type: {type_label} | FY 2026-27",
            section_headers,
        )

        # Section 1: actual commercial CMB sold quantity — one row per CMB.
        r_idx = 3
        for row in cmb_rows:
            values = [
                _safe_excel_text(row["sku"]),
                _safe_excel_text(row.get("cn_name", "")),
                _safe_excel_text(row["sku_name"]),
                float(row["cmb_sold"]),
            ]
            for col, value in enumerate(values, 1):
                cell = ws2.cell(r_idx, col, value)
                cell.border = border
                cell.alignment = center if col == 4 else left
                if col == 4:
                    cell.number_format = '#,##0.##'
            r_idx += 1

        cmb_total_row = r_idx + 1
        ws2.merge_cells(start_row=cmb_total_row, start_column=1, end_row=cmb_total_row, end_column=3)
        cmb_label = ws2.cell(cmb_total_row, 1, "TOTAL CMB SOLD QTY")
        cmb_label.font = Font(bold=True)
        cmb_label.fill = total_fill
        cmb_label.alignment = center
        cmb_total = ws2.cell(cmb_total_row, 4, sum(float(r["cmb_sold"]) for r in cmb_rows))
        cmb_total.font = Font(bold=True)
        cmb_total.fill = total_fill
        cmb_total.alignment = center
        cmb_total.number_format = '#,##0.##'
        for col in range(1, 5):
            ws2.cell(cmb_total_row, col).border = border
            ws2.cell(cmb_total_row, col).fill = total_fill

        # Section 2: after all CMB rows, show every RKH SKU sold individually.
        ind_title_row = cmb_total_row + 3
        ws2.merge_cells(start_row=ind_title_row, start_column=1, end_row=ind_title_row, end_column=4)
        ind_title = ws2.cell(ind_title_row, 1, f"Individual Rakhi Sales | Type: {type_label} | FY 2026-27")
        ind_title.font = Font(bold=True, size=12, color="2B2110")
        ind_title.fill = title_fill
        ind_title.alignment = center
        for col in range(1, 5):
            ws2.cell(ind_title_row, col).fill = title_fill
            ws2.cell(ind_title_row, col).border = border

        ind_header_row = ind_title_row + 1
        for col, header in enumerate(section_headers, 1):
            cell = ws2.cell(ind_header_row, col, header)
            cell.font = header_font
            cell.fill = header_fill
            cell.alignment = center
            cell.border = border

        r_idx = ind_header_row + 1
        for row in individual_rows:
            values = [
                _safe_excel_text(row["sku"]),
                _safe_excel_text(row.get("cn_name", "")),
                _safe_excel_text(row["sku_name"]),
                float(row["individual_sold"]),
            ]
            for col, value in enumerate(values, 1):
                cell = ws2.cell(r_idx, col, value)
                cell.border = border
                cell.alignment = center if col == 4 else left
                if col == 4:
                    cell.number_format = '#,##0.##'
            r_idx += 1

        ind_total_row = r_idx + 1
        ws2.merge_cells(start_row=ind_total_row, start_column=1, end_row=ind_total_row, end_column=3)
        ind_label = ws2.cell(ind_total_row, 1, "TOTAL INDIVIDUAL RAKHI SOLD QTY")
        ind_label.font = Font(bold=True)
        ind_label.fill = total_fill
        ind_label.alignment = center
        ind_total = ws2.cell(ind_total_row, 4, sum(float(r["individual_sold"]) for r in individual_rows))
        ind_total.font = Font(bold=True)
        ind_total.fill = total_fill
        ind_total.alignment = center
        ind_total.number_format = '#,##0.##'
        for col in range(1, 5):
            ws2.cell(ind_total_row, col).border = border
            ws2.cell(ind_total_row, col).fill = total_fill

        ws2.freeze_panes = "A3"
        for i, width in enumerate([22, 34, 40, 18], 1):
            ws2.column_dimensions[get_column_letter(i)].width = width
        ws2.row_dimensions[1].height = 26
        ws2.row_dimensions[2].height = 30
        ws2.row_dimensions[ind_title_row].height = 26
        ws2.row_dimensions[ind_header_row].height = 30

        bio = io.BytesIO()
        wb.save(bio)
        bio.seek(0)
        fname = f"rakhi_child_sku_and_cmb_sales_{now_ist().strftime('%Y-%m-%d')}.xlsx"
        resp = app.response_class(
            bio.read(),
            mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        )
        resp.headers["Content-Disposition"] = f"attachment; filename={fname}"
        return resp
    except Exception as e:
        return jsonify({"error": f"Rakhi child/CMB sales Excel export failed: {e}"}), 500



@app.route("/api/daily_revenue_glimpse_marketplace/export.xlsx")
def api_daily_revenue_glimpse_marketplace_export_xlsx():
    if session.get("role") not in ("admin", "employee"):
        return jsonify({"error": "login required"}), 401
    try:
        import openpyxl
        from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
        from openpyxl.utils import get_column_letter

        rep = _build_daily_revenue_glimpse_marketplace(force=False)
        rows = rep["rows"]
        tot = rep["totals"]
        today_dt = now_ist().replace(hour=0, minute=0, second=0, microsecond=0, tzinfo=None)
        title_txt = today_dt.strftime("%d - %b - %Y")
        headers = ["Channel", "YTD", "Last Month", "This Month", "Day Before",
                   "Yesterday", "This Month Target", "Achievement %"]
        n_cols = len(headers)
        NUM_FMT = "[>=10000000]##\\,##\\,##\\,##0;[>=100000]##\\,##\\,##0;##,##0"

        wb = openpyxl.Workbook()
        ws = wb.active
        ws.title = "Marketplace Revenue"
        title_fill = PatternFill("solid", fgColor="000000")
        title_font = Font(bold=True, color="FFFFFF", size=12)
        head_fill = PatternFill("solid", fgColor="C9DAF8")
        head_font = Font(bold=True)
        total_fill = PatternFill("solid", fgColor="C9DAF8")
        total_font = Font(bold=True)
        thin = Side(style="thin", color="CCCCCC")
        border = Border(left=thin, right=thin, top=thin, bottom=thin)
        center = Alignment(horizontal="center", vertical="center")

        ws.merge_cells(start_row=1, start_column=1, end_row=1, end_column=n_cols)
        c = ws.cell(row=1, column=1, value=title_txt)
        c.fill = title_fill; c.font = title_font; c.alignment = center
        for col in range(1, n_cols + 1):
            ws.cell(row=1, column=col).fill = title_fill
        for col, h in enumerate(headers, start=1):
            c = ws.cell(row=2, column=col, value=h)
            c.fill = head_fill; c.font = head_font; c.alignment = center; c.border = border

        r_idx = 3
        for r in rows:
            ws.cell(row=r_idx, column=1, value=r["channel"]).font = Font(bold=True)
            ws.cell(row=r_idx, column=2, value=round(r["ytd"])).number_format = NUM_FMT
            ws.cell(row=r_idx, column=3, value=round(r["last_month"])).number_format = NUM_FMT
            ws.cell(row=r_idx, column=4, value=round(r["mtd"])).number_format = NUM_FMT
            ws.cell(row=r_idx, column=5, value=round(r["day_before"])).number_format = NUM_FMT
            ws.cell(row=r_idx, column=6, value=round(r["yesterday"])).number_format = NUM_FMT
            if r["mtd_target"]:
                ws.cell(row=r_idx, column=7, value=round(r["mtd_target"])).number_format = NUM_FMT
                ws.cell(row=r_idx, column=8, value=r["mtd_achievement"])
            else:
                ws.cell(row=r_idx, column=7, value="NA")
                ws.cell(row=r_idx, column=8, value="")
            for col in range(1, n_cols + 1):
                ws.cell(row=r_idx, column=col).border = border
            r_idx += 1

        ws.cell(row=r_idx, column=1, value="TOTAL")
        ws.cell(row=r_idx, column=2, value=round(tot["ytd"])).number_format = NUM_FMT
        ws.cell(row=r_idx, column=3, value=round(tot["last_month"])).number_format = NUM_FMT
        ws.cell(row=r_idx, column=4, value=round(tot["mtd"])).number_format = NUM_FMT
        ws.cell(row=r_idx, column=5, value=round(tot["day_before"])).number_format = NUM_FMT
        ws.cell(row=r_idx, column=6, value=round(tot["yesterday"])).number_format = NUM_FMT
        if tot["mtd_target"]:
            ws.cell(row=r_idx, column=7, value=round(tot["mtd_target"])).number_format = NUM_FMT
            ws.cell(row=r_idx, column=8, value=tot["mtd_achievement"])
        else:
            ws.cell(row=r_idx, column=7, value="NA")
            ws.cell(row=r_idx, column=8, value="")
        for col in range(1, n_cols + 1):
            cell = ws.cell(row=r_idx, column=col)
            cell.fill = total_fill; cell.font = total_font; cell.border = border

        widths = [26, 14, 14, 14, 12, 12, 16, 14]
        for i, width in enumerate(widths, start=1):
            ws.column_dimensions[get_column_letter(i)].width = width

        bio = io.BytesIO()
        wb.save(bio); bio.seek(0)
        fname = f"daily_revenue_glimpse_marketplace_{today_dt.strftime('%Y-%m-%d')}.xlsx"
        resp = app.response_class(bio.read(), mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")
        resp.headers["Content-Disposition"] = f"attachment; filename={fname}"
        return resp
    except Exception as e:
        return jsonify({"error": f"marketplace excel export failed: {e}"}), 500


