# ════════════════════════════════════════════════════════════════
#  📤 OVERALL DETAILS EXPORT (Customer/Date drill-down)
#  Jab Overall Details tab me Customer/Date se search karke
#  Transactions + Pivot (SKU-wise summary) table dikhti hai, wahan
#  ke Export Excel / Export PDF buttons yahan hit karte hain.
#  Frontend jo bhi filtered rows (already filters lagi hui) bhejta
#  hai wahi export hoti hai — image_url "Image Link" column me
#  (Excel) ya photo ke roop me (PDF) shamil hota hai.
# ════════════════════════════════════════════════════════════════
_OVERALL_NUM_FMT = "[>=10000000]##\\,##\\,##\\,##0;[>=100000]##\\,##\\,##0;##,##0"

@app.route("/api/overall_export/xlsx", methods=["POST"])
def api_overall_export_xlsx():
    if session.get("role") not in ("admin", "employee"):
        return jsonify({"error": "login required"}), 401
    try:
        import openpyxl
        from openpyxl.styles import Font, PatternFill

        payload = request.get_json(force=True) or {}
        kind  = payload.get("kind", "transactions")
        rows  = payload.get("rows") or []
        title = (payload.get("title") or "overall_details").strip() or "overall_details"
        show_rev = bool(rows) and rows[0].get("revenue") is not None
        month_mode = bool(rows) and bool(rows[0].get("month_mode"))
        month_keys = sorted({str(k) for r in rows for k in ((r.get("month_qty") or {}).keys()) if re.match(r"^\d{4}-\d{2}$", str(k))}) if month_mode else []
        month_headers = [datetime.strptime(k, "%Y-%m").strftime("%B %Y") + " Total Sold Qty" for k in month_keys]

        wb = openpyxl.Workbook()
        ws = wb.active
        ws.title = "Pivot" if kind == "pivot" else "Transactions"

        if kind == "pivot":
            headers = ["SKU", "CN Name", "Customers", "Customer Count", "Individual Sold", "In CMBs Sold"] \
                      + (["Total Sold Qty", "Last 1 Year Sold Qty"] if month_mode else []) \
                      + (["Net Revenue"] if show_rev else []) + ["Inv Stock", "Inv (WIP)", "Image Link"]
        else:
            if month_mode:
                headers = ["SKU", "Taxon"] + month_headers + ["Selected Months Sold Qty", "Last 3 Months Sold Qty", "Last 1 Year Sold Qty", "CN Name"] \
                          + (["Net Revenue"] if show_rev else []) + ["Inv Stock", "Inv (WIP)", "Blocked Qty", "Image Link", "Used in CMBs", "Best Sold in This CMB", "Best CMB Image Link"]
            else:
                headers = ["Dispatch Date", "SKU", "CN Name", "Customer", "Type", "Individual Sold", "In CMBs Sold"] + (["Net Revenue"] if show_rev else []) \
                          + ["Inv Stock", "Inv (WIP)", "Blocked Qty", "Image Link"]

        ws.append(headers)
        for c in ws[1]:
            c.font = Font(bold=True, color="FFFFFF")
            c.fill = PatternFill("solid", fgColor="8C7A42")

        num_cols = {"Customer Count", "Individual Sold", "In CMBs Sold", "Total Sold Qty", "Selected Months Sold Qty", "Last 3 Months Sold Qty", "Last 1 Year Sold Qty", "Net Revenue", "Inv Stock", "Inv (WIP)", "Blocked Qty"} | set(month_headers)
        for r in rows:
            if kind == "pivot":
                line = [r.get("sku", ""), r.get("cn_name", ""), r.get("customers", ""), r.get("customer_count", 0), r.get("qty", 0), r.get("combo_qty", 0)]
                if month_mode:
                    line += [r.get("total_qty", 0), r.get("last_1y_qty", 0)]
                if show_rev:
                    line.append(r.get("revenue", 0))
                line += [r.get("inv_stock", 0), r.get("inv_wip", 0), r.get("image_url", "") or ""]
            else:
                if month_mode:
                    mq = r.get("month_qty") or {}
                    line = [r.get("sku", ""), r.get("taxon", "")] + [mq.get(k, 0) for k in month_keys] \
                           + [r.get("selected_months_qty", 0), r.get("last_3m_qty", 0), r.get("last_1y_qty", 0), r.get("cn_name", "")]
                    if show_rev:
                        line.append(r.get("revenue", 0))
                    line += [r.get("inv_stock", 0), r.get("inv_wip", 0), r.get("blocked_qty", 0), r.get("image_url", "") or "",
                             ", ".join(r.get("cmbs") or []), (str(r.get("best_cmb", "") or "") + ((" · " + str(r.get("best_cmb_name", ""))) if r.get("best_cmb_name") else "")), r.get("best_cmb_image_url", "") or ""]
                else:
                    line = [r.get("date", ""), r.get("sku", ""), r.get("cn_name", ""), r.get("customer", ""), _marketplace_display_text(r.get("type", "")), r.get("qty", 0), r.get("combo_qty", 0)]
                    if show_rev:
                        line.append(r.get("revenue", 0))
                    line += [r.get("inv_stock", 0), r.get("inv_wip", 0), r.get("blocked_qty", 0), r.get("image_url", "") or ""]
            ws.append(line)

        for col_idx, h in enumerate(headers, start=1):
            if h in num_cols:
                for row_i in range(2, ws.max_row + 1):
                    ws.cell(row=row_i, column=col_idx).number_format = _OVERALL_NUM_FMT
            if h in {"Image Link", "Best CMB Image Link"}:
                for row_i in range(2, ws.max_row + 1):
                    cell = ws.cell(row=row_i, column=col_idx)
                    val = str(cell.value or "").strip()
                    if val.startswith(("http://", "https://")):
                        cell.hyperlink = val
                        cell.style = "Hyperlink"

        for col_cells in ws.columns:
            length = max((len(str(c.value)) for c in col_cells if c.value is not None), default=10)
            ws.column_dimensions[col_cells[0].column_letter].width = min(max(length + 2, 10), 60)

        bio = io.BytesIO()
        wb.save(bio)
        bio.seek(0)
        safe_title = re.sub(r"[^A-Za-z0-9_-]+", "_", title)
        resp = app.response_class(
            bio.read(),
            mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        )
        resp.headers["Content-Disposition"] = f"attachment; filename={safe_title}_{kind}.xlsx"
        return resp
    except Exception as e:
        return jsonify({"error": f"excel export failed: {e}"}), 500

@app.route("/api/overall_export/pdf", methods=["POST"])
def api_overall_export_pdf():
    if session.get("role") not in ("admin", "employee"):
        return jsonify({"error": "login required"}), 401
    try:
        try:
            from reportlab.lib import colors
            from reportlab.lib.pagesizes import A4, A3, landscape
            from reportlab.lib.units import mm
            from reportlab.platypus import SimpleDocTemplate, Table, TableStyle, Paragraph, Spacer, Image as RLImage
            from reportlab.lib.styles import getSampleStyleSheet
        except ImportError:
            return jsonify({"error": "PDF export ke liye 'reportlab' package deploy me install nahi hai — "
                                      "requirements.txt me 'reportlab' add karke Railway par redeploy karein."}), 500
        from concurrent.futures import ThreadPoolExecutor, as_completed

        payload = request.get_json(force=True) or {}
        kind  = payload.get("kind", "transactions")
        rows  = payload.get("rows") or []
        title = payload.get("title") or "Overall Details"
        show_rev = bool(rows) and rows[0].get("revenue") is not None
        month_mode = bool(rows) and bool(rows[0].get("month_mode"))
        month_keys = sorted({str(k) for r in rows for k in ((r.get("month_qty") or {}).keys()) if re.match(r"^\d{4}-\d{2}$", str(k))}) if month_mode else []
        month_headers = [datetime.strptime(k, "%Y-%m").strftime("%B %Y") + " Sold" for k in month_keys]

        # ── Photos: sirf UNIQUE URLs download karo (Transactions me ek hi SKU
        #    baar baar aata hai), parallel me, chhota timeout, aur ek limit
        #    taaki bahut zyada rows ho to bhi PDF hang na ho / gunicorn
        #    timeout na maare. Limit se upar wale rows me photo blank rahega. ──
        MAX_PDF_IMAGES = 100
        IMG_TIMEOUT = 2.0

        def _download_thumb(url):
            try:
                ir = requests.get(url, timeout=IMG_TIMEOUT)
                ir.raise_for_status()
                raw = ir.content
                if PIL_AVAILABLE:
                    im = Image.open(io.BytesIO(raw)).convert("RGB")
                    im.thumbnail((90, 90))
                    out = io.BytesIO()
                    im.save(out, format="JPEG", quality=78)
                    out.seek(0)
                    return out.read()
                return raw
            except Exception:
                return None

        unique_urls = []
        seen = set()
        for r in rows:
            u = r.get("image_url")
            if u and u not in seen:
                seen.add(u)
                unique_urls.append(u)
            if len(unique_urls) >= MAX_PDF_IMAGES:
                break

        img_bytes_cache = {}
        if unique_urls:
            with ThreadPoolExecutor(max_workers=8) as ex:
                futs = {ex.submit(_download_thumb, u): u for u in unique_urls}
                for fut in as_completed(futs):
                    u = futs[fut]
                    try:
                        img_bytes_cache[u] = fut.result()
                    except Exception:
                        img_bytes_cache[u] = None

        def _img_flowable(url):
            raw = img_bytes_cache.get(url)
            if not raw:
                return ""
            try:
                return RLImage(io.BytesIO(raw), width=13 * mm, height=13 * mm)
            except Exception:
                return ""

        def _link_flowable(url, label="Open Image"):
            u = str(url or "").strip()
            if not u.startswith(("http://", "https://")):
                return ""
            safe_u = html.escape(u, quote=True)
            return Paragraph(f'<link href="{safe_u}" color="#1d4ed8">{html.escape(label)}</link>', getSampleStyleSheet()["BodyText"])

        styles = getSampleStyleSheet()
        elements = [Paragraph(str(title).replace("_", " "), styles["Heading2"]), Spacer(1, 8)]
        if len(rows) > 1500:
            elements.append(Paragraph(f"({len(rows)} rows — showing all; photos limited to first "
                                       f"{MAX_PDF_IMAGES} unique SKUs for speed)", styles["Normal"]))
            elements.append(Spacer(1, 6))

        if kind == "pivot":
            headers = ["Photo", "SKU", "CN Name", "Customers", "Customer Count", "Individual Sold", "In CMBs Sold"] \
                      + (["Total Sold", "Last 1Y Sold"] if month_mode else []) + (["Net Revenue"] if show_rev else []) + ["Stock", "WIP"]
        else:
            if month_mode:
                headers = ["Photo", "SKU", "Taxon"] + month_headers + ["Selected Months Sold", "Last 3M Sold", "Last 1Y Sold", "CN Name"] \
                          + (["Net Revenue"] if show_rev else []) + ["Stock", "WIP", "Blocked", "Used in CMBs", "Best CMB", "Best CMB Image"]
            else:
                headers = ["Photo", "Date", "SKU", "CN Name", "Customer", "Type", "Individual Sold", "In CMBs Sold"] + (["Net Revenue"] if show_rev else []) \
                          + ["Stock", "WIP", "Blocked"]

        table_data = [headers]
        for r in rows:
            img_cell = _img_flowable(r.get("image_url"))
            if kind == "pivot":
                line = [img_cell, r.get("sku", ""), r.get("cn_name", ""), r.get("customers", ""), r.get("customer_count", 0), r.get("qty", 0), r.get("combo_qty", 0)]
                if month_mode:
                    line += [r.get("total_qty", 0), r.get("last_1y_qty", 0)]
                if show_rev:
                    line.append(r.get("revenue", 0))
                line += [r.get("inv_stock", 0), r.get("inv_wip", 0)]
            else:
                if month_mode:
                    mq = r.get("month_qty") or {}
                    line = [img_cell, r.get("sku", ""), r.get("taxon", "")] + [mq.get(k, 0) for k in month_keys] \
                           + [r.get("selected_months_qty", 0), r.get("last_3m_qty", 0), r.get("last_1y_qty", 0), r.get("cn_name", "")]
                    if show_rev:
                        line.append(r.get("revenue", 0))
                    line += [r.get("inv_stock", 0), r.get("inv_wip", 0), r.get("blocked_qty", 0),
                             ", ".join(r.get("cmbs") or []), (str(r.get("best_cmb", "") or "") + ((" · " + str(r.get("best_cmb_name", ""))) if r.get("best_cmb_name") else "")), _link_flowable(r.get("best_cmb_image_url"))]
                else:
                    line = [img_cell, r.get("date", ""), r.get("sku", ""), r.get("cn_name", ""), r.get("customer", ""), _marketplace_display_text(r.get("type", "")), r.get("qty", 0), r.get("combo_qty", 0)]
                    if show_rev:
                        line.append(r.get("revenue", 0))
                    line += [r.get("inv_stock", 0), r.get("inv_wip", 0), r.get("blocked_qty", 0)]
            table_data.append(line)

        tbl = Table(table_data, repeatRows=1)
        pdf_font_size = 5 if month_mode and len(month_keys) > 4 else 7
        tbl.setStyle(TableStyle([
            ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#8C7A42")),
            ("TEXTCOLOR", (0, 0), (-1, 0), colors.white),
            ("FONTSIZE", (0, 0), (-1, -1), pdf_font_size),
            ("GRID", (0, 0), (-1, -1), 0.5, colors.grey),
            ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
            ("ROWBACKGROUNDS", (0, 1), (-1, -1), [colors.white, colors.HexColor("#F7F5EE")]),
        ]))
        elements.append(tbl)

        bio = io.BytesIO()
        doc = SimpleDocTemplate(bio, pagesize=landscape(A3 if month_mode else A4), topMargin=18, bottomMargin=18, leftMargin=18, rightMargin=18)
        doc.build(elements)
        bio.seek(0)
        safe_title = re.sub(r"[^A-Za-z0-9_-]+", "_", str(title))
        resp = app.response_class(bio.read(), mimetype="application/pdf")
        resp.headers["Content-Disposition"] = f"attachment; filename={safe_title}_{kind}.pdf"
        return resp
    except Exception as e:
        return jsonify({"error": f"pdf export failed: {e}"}), 500

# ════════════════════════════════════════════════════════════════
#  💸 DISCOUNT LEAKAGE REPORT  (admin only)
#  MRP vs actual Selling Price ka gap. Jaha qty zyada × discount zyada,
#  wahan sabse zyada "leakage" (lost value).
# ════════════════════════════════════════════════════════════════
def _build_discount_leakage(min_disc=0.0, sort_key="leakage", cn_query=""):
    data = get_data()
    comp = data[0]
    rows = []
    tot_leak = 0.0
    tot_units = 0.0
    cnq = str(cn_query or '').strip().lower()
    for it in comp:
        if cnq and cnq not in str(it.get('cn_name') or '').lower():
            continue
        mrp = float(it.get("mrp") or 0)
        qty = float(it.get("final_qty") or 0)
        # Overall qty-weighted average SP (total_net_revenue/qty) — same method
        # ab item compile step mein bhi use hota hai (discount_pct), taaki
        # Discount Leakage aur baaki app mein number match kare.
        sp  = (float(it.get("total_net_revenue") or 0) / qty) if qty > 0 else 0.0
        if mrp <= 0 or sp <= 0 or qty <= 0:
            continue
        if sp >= mrp:        # koi discount nahi (ya MRP se upar) → skip
            continue
        disc_pct = round((mrp - sp) / mrp * 100, 1)
        if disc_pct < min_disc:
            continue
        per_unit_gap = mrp - sp
        leakage = per_unit_gap * qty          # total value "lost" vs MRP
        tot_leak += leakage
        tot_units += qty
        rows.append({
            "sku": it.get("sku"), "sku_name": it.get("sku_name", ""), "image_url": it.get("image_url", ""),
            "stone_color": it.get("stone_color", ""),
            "taxon": it.get("taxon", ""), "plating": it.get("plating", ""),
            "mrp": mrp, "avg_sp": round(float(it.get("avg_selling_price") or 0), 2),
            # Display the actual latest non-zero dated Selling Price separately
            # from the qty-weighted average SP used for leakage mathematics.
            "last_sp": round(float(it.get("last_selling_price") or 0), 2), "disc_pct": disc_pct,
            "per_unit_gap": round(per_unit_gap, 2), "qty": int(round(qty)),
            "leakage": round(leakage, 2),
            "net_revenue": float(it.get("total_net_revenue") or 0),
        })
    key = {"leakage":"leakage","discount":"disc_pct","qty":"qty","revenue":"net_revenue"}.get(sort_key, "leakage")
    rows.sort(key=lambda x: x.get(key, 0), reverse=True)
    return {
        "rows": rows[:500],
        "total_leakage": round(tot_leak, 2),
        "total_units": int(round(tot_units)),
        "count": len(rows),
    }

@app.route("/api/discount-leakage")
def api_discount_leakage():
    if session.get("role") != "admin":
        return jsonify({"error": "admin only"}), 403
    try:
        md = float(request.args.get("min", "0") or 0)
    except Exception:
        md = 0.0
    sk = request.args.get("sort", "leakage").strip()
    cnq = request.args.get("cn_name", "").strip()
    try:
        return jsonify(_build_discount_leakage(md, sk, cnq))
    except Exception as e:
        return jsonify({"error": f"discount leakage build failed: {e}"}), 500

