def _production_request_filters():
    return {
        "channel_filter": request.args.get("channel", "").strip(),
        "sku_query": request.args.get("sku", "").strip(),
        "od1": request.args.get("od1", "").strip(),
        "od2": request.args.get("od2", "").strip(),
        "dd1": request.args.get("dd1", "").strip(),
        "dd2": request.args.get("dd2", "").strip(),
        "taxon_filter": [v.strip() for v in request.args.getlist("taxon") if v.strip()],
        "type_filter": request.args.get("type", "").strip(),
        "balance_only": request.args.get("balance", "").strip(),
        "order_query": request.args.get("order_no", "").strip(),
        "sort_mode": request.args.get("sort", "").strip(),
        "cn_query": request.args.get("cn_name", "").strip(),
    }

def _refresh_production_cache_if_requested():
    """Make the Production Refresh button and exports truly fetch live K data."""
    fresh = request.args.get("fresh", "0").strip().lower() in ("1", "true", "yes")
    if fresh:
        _PROD_CACHE["rows"] = None
        _PROD_CACHE["ts"] = 0
    return fresh

def _production_export_table(report):
    """Full filtered Production rows; never uses the 1,000-row screen cap."""
    show_pricing = session.get("role") == "admin"
    headers = [
        "Order Date", "Order No.", "SKU", "CN Name", "SKU Name", "Stock", "WIP",
        "Stone Color", "Category", "Type", "Channel",
    ]
    if show_pricing:
        headers += ["AOV / Piece", "Discount %"]
    headers += [
        "Pending / Balance Order Nos.", "Times Ordered", "Order Qty", "Received Qty",
        "Balance Qty", "Total Balance (All Orders)", "Delivery Date",
        "Receiving Date", "Image Link",
    ]
    rows = []
    for r in report.get("rows") or []:
        line = [
            r.get("date_disp") or r.get("date") or "",
            r.get("order_no") or "",
            r.get("sku") or "",
            r.get("cn_name") or "",
            cn_sku_label(r.get("sku") or ""),
            round(float(r.get("inv_stock") or 0)),
            round(float(r.get("inv_wip") or 0)),
            r.get("stone_color") or "",
            r.get("taxon") or "",
            r.get("order_type") or "",
            r.get("channel") or "",
        ]
        if show_pricing:
            line += [
                round(float(r.get("aov_per_piece") or 0), 2),
                round(float(r.get("discount_pct") or 0), 2),
            ]
        line += [
            " | ".join(str(x) for x in (r.get("all_orders") or [])),
            int(r.get("repeat_count") or 0),
            round(float(r.get("order_qty") or 0)),
            round(float(r.get("recv_qty") or 0)),
            round(float(r.get("bal_qty") or 0)),
            round(float(r.get("sku_total_balance") or 0)),
            r.get("delivery_date") or r.get("delivery_iso") or "",
            r.get("receiving_date") or r.get("receiving_iso") or "",
            r.get("image_url") or "",
        ]
        rows.append(line)
    return headers, rows

def _production_export_report():
    _refresh_production_cache_if_requested()
    filters = _production_request_filters()
    # Screen JSON stays capped for browser performance; exports deliberately
    # rebuild from every row matching the exact same filters.
    return filters, _build_production(**filters, row_limit=None)

@app.route("/api/production/export.csv")
def api_production_export_csv():
    if session.get("role") not in ("admin", "employee"):
        return jsonify({"error": "login required"}), 401
    try:
        import csv
        _, report = _production_export_report()
        headers, rows = _production_export_table(report)
        if not rows:
            return jsonify({"error": "No production data matches the selected filters."}), 404
        sio = io.StringIO(newline="")
        writer = csv.writer(sio)
        writer.writerow(headers)
        writer.writerows(rows)
        stamp = now_ist().strftime("%Y-%m-%d")
        resp = app.response_class("\ufeff" + sio.getvalue(), mimetype="text/csv; charset=utf-8")
        resp.headers["Content-Disposition"] = f'attachment; filename="production_ppc_wip_{stamp}.csv"'
        resp.headers["Cache-Control"] = "no-store"
        return resp
    except Exception as e:
        return jsonify({"error": f"production CSV export failed: {e}"}), 500

@app.route("/api/production/export.xlsx")
def api_production_export_xlsx():
    if session.get("role") not in ("admin", "employee"):
        return jsonify({"error": "login required"}), 401
    try:
        import openpyxl
        from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
        from openpyxl.utils import get_column_letter

        filters, report = _production_export_report()
        headers, rows = _production_export_table(report)
        if not rows:
            return jsonify({"error": "No production data matches the selected filters."}), 404

        wb = openpyxl.Workbook()
        ws = wb.active
        ws.title = "Production Data"
        ws.freeze_panes = "A2"
        ws.append(headers)

        header_fill = PatternFill("solid", fgColor="8C7A42")
        header_font = Font(bold=True, color="FFFFFF")
        thin = Side(style="thin", color="D9D2C3")
        border = Border(left=thin, right=thin, top=thin, bottom=thin)
        for cell in ws[1]:
            cell.fill = header_fill
            cell.font = header_font
            cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
            cell.border = border

        date_headers = {"Order Date", "Delivery Date", "Receiving Date"}
        qty_headers = {"Stock", "WIP", "Times Ordered", "Order Qty", "Received Qty", "Balance Qty", "Total Balance (All Orders)"}
        decimal_headers = {"AOV / Piece", "Discount %"}
        header_index = {name: idx for idx, name in enumerate(headers)}
        date_indexes = {header_index[name] for name in date_headers if name in header_index}
        for raw in rows:
            line = list(raw)
            for idx in date_indexes:
                parsed = parse_date_any(line[idx]) if line[idx] else None
                if parsed is not None:
                    line[idx] = datetime(parsed.year, parsed.month, parsed.day)
            ws.append(line)

        for col_idx, name in enumerate(headers, start=1):
            if name in date_headers:
                for row_idx in range(2, ws.max_row + 1):
                    ws.cell(row=row_idx, column=col_idx).number_format = "dd-mmm-yyyy"
            elif name in qty_headers:
                for row_idx in range(2, ws.max_row + 1):
                    ws.cell(row=row_idx, column=col_idx).number_format = "#,##0"
            elif name in decimal_headers:
                for row_idx in range(2, ws.max_row + 1):
                    ws.cell(row=row_idx, column=col_idx).number_format = "#,##0.00"

        image_col = header_index.get("Image Link")
        if image_col is not None:
            for row_idx in range(2, ws.max_row + 1):
                cell = ws.cell(row=row_idx, column=image_col + 1)
                if str(cell.value or "").startswith(("http://", "https://")):
                    cell.hyperlink = str(cell.value)
                    cell.style = "Hyperlink"

        ws.auto_filter.ref = ws.dimensions
        widths = {
            "Order Date": 14, "Order No.": 18, "SKU": 18, "CN Name": 34, "SKU Name": 42,
            "Stock": 12, "WIP": 12, "Stone Color": 18, "Category": 18,
            "Type": 18, "Channel": 18, "AOV / Piece": 14, "Discount %": 13,
            "Pending / Balance Order Nos.": 52, "Times Ordered": 14, "Order Qty": 12,
            "Received Qty": 14, "Balance Qty": 13,
            "Total Balance (All Orders)": 22, "Delivery Date": 15,
            "Receiving Date": 15, "Image Link": 55,
        }
        for col_idx, name in enumerate(headers, start=1):
            ws.column_dimensions[get_column_letter(col_idx)].width = widths.get(name, 16)
        for row in ws.iter_rows(min_row=2):
            for cell in row:
                cell.alignment = Alignment(vertical="top", wrap_text=cell.column in {
                    header_index.get("SKU Name", -1) + 1,
                    header_index.get("Pending / Balance Order Nos.", -1) + 1,
                    header_index.get("Image Link", -1) + 1,
                })

        summary = wb.create_sheet("Summary")
        summary.append(["Production Export Summary", "Value"])
        summary_rows = [
            ("Filtered Rows", report.get("count", len(rows))),
            ("Unique Orders", report.get("unique_orders", 0)),
            ("Unique SKUs", report.get("unique_skus", 0)),
            ("Total Order Qty", report.get("total_order_qty", 0)),
            ("Total Received Qty", report.get("total_recv_qty", 0)),
            ("Total Balance Qty", report.get("total_bal_qty", 0)),
            ("Rows with Balance", report.get("pending_rows", 0)),
            ("Balance Qty Source", "Production sheet column K"),
            ("Exported At", now_ist().strftime("%d-%b-%Y %I:%M %p")),
            ("Channel Filter", _marketplace_display_text(filters.get("channel_filter") or "All")),
            ("Type Filter", _marketplace_display_text(filters.get("type_filter") or "All")),
            ("Category Filter", ", ".join(filters.get("taxon_filter") or []) or "All"),
            ("SKU Search", filters.get("sku_query") or "All"),
            ("Order No. Search", filters.get("order_query") or "All"),
            ("Order Date From", filters.get("od1") or "All"),
            ("Order Date To", filters.get("od2") or "All"),
            ("Delivery Date From", filters.get("dd1") or "All"),
            ("Delivery Date To", filters.get("dd2") or "All"),
            ("Balance Filter", filters.get("balance_only") or "All"),
            ("Sort / Group", filters.get("sort_mode") or "Default"),
        ]
        for item in summary_rows:
            summary.append(list(item))
        for cell in summary[1]:
            cell.fill = header_fill
            cell.font = header_font
        summary.column_dimensions["A"].width = 28
        summary.column_dimensions["B"].width = 42
        summary.freeze_panes = "A2"

        bio = io.BytesIO()
        wb.save(bio)
        bio.seek(0)
        stamp = now_ist().strftime("%Y-%m-%d")
        resp = app.response_class(
            bio.read(),
            mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        )
        resp.headers["Content-Disposition"] = f'attachment; filename="production_ppc_wip_{stamp}.xlsx"'
        resp.headers["Cache-Control"] = "no-store"
        return resp
    except Exception as e:
        return jsonify({"error": f"production Excel export failed: {e}"}), 500

# ════════════════════════════════════════════════════════════════
#  💰 SKU COSTS (Profit Margin tab) — admin only
#  All Product sheet: column N (index 13)=MRP, column M (index 12)=Cost.
# ════════════════════════════════════════════════════════════════
_COSTS_CACHE = {"rows": None, "ts": 0}

def _build_sku_costs():
    if _COSTS_CACHE["rows"] is not None and (time.time() - _COSTS_CACHE["ts"] < 600):
        return _COSTS_CACHE["rows"]

    # ── Seedha compiled data se — wahi column detection jo main data me hoti hai ──
    # MRP aur Cost dono wahan se lo (I_COST ab compiled items me hai).
    out = []
    seen = set()
    try:
        comp = get_data()[0]
        for it in comp:
            sk = str(it.get("sku", "")).strip()
            if not sk:
                continue
            ku = sk.upper()
            if ku in seen:
                continue
            seen.add(ku)
            mrp_val  = float(it.get("mrp")  or 0)
            cost_val = float(it.get("cost") or 0)
            # agar compiled me cost nahi mila (purana cache) to sheet se try karo
            out.append({
                "sku":         sk,
                "sku_name":    it.get("sku_name") or cn_sku_label(sk),
                "image_url":   it.get("image_url", "") or "",
                "mrp":         mrp_val,
                "cost":        cost_val,
                "final_qty":   int(it.get("final_qty") or 0),
                "net_revenue": float(it.get("total_net_revenue") or 0),
            })
    except Exception:
        pass

    # agar compiled me kuch SKUs ka cost 0 aa raha ho (purana cache), sheet se patch karo
    zero_cost_skus = {r["sku"].upper() for r in out if r["cost"] == 0}
    if zero_cost_skus:
        try:
            df = _fetch_csv_fresh(INV_URL)
            cols = list(df.columns)
            def _at(i): return cols[i] if len(cols) > i else None
            # Live All Product: B=SKU, E=Image Link, M=Cost, N=MRP. Header
            # matching stays primary; physical fallbacks protect renamed headers.
            C_SKU  = find_col(df.columns, "SKU", "sku code", "item code") or _at(1)
            C_COST = find_col(df.columns, "Cost", "cost", "product cost", "hi cost", "item cost") or _at(12)
            C_MRP  = find_col(df.columns, "MRP", "mrp", "m.r.p") or _at(13)
            C_IMG2 = find_col(df.columns, "Image Link", "imagelink", "image", "img") or _at(4)
            patch_cost = {}; patch_mrp = {}; patch_img = {}
            for _, r in df.iterrows():
                sku = clean(r.get(C_SKU, "")) if C_SKU else ""
                if not sku:
                    continue
                ku = sku.strip().upper()
                if ku not in patch_cost:
                    patch_cost[ku] = to_num(r.get(C_COST, 0)) if C_COST else 0
                    patch_mrp[ku]  = to_num(r.get(C_MRP,  0)) if C_MRP  else 0
                    patch_img[ku]  = clean(r.get(C_IMG2, "")) if C_IMG2 else ""
            # patch existing rows
            for row in out:
                ku = row["sku"].upper()
                if ku in zero_cost_skus:
                    if patch_cost.get(ku, 0) > 0:
                        row["cost"] = patch_cost[ku]
                    if row["mrp"] == 0 and patch_mrp.get(ku, 0) > 0:
                        row["mrp"] = patch_mrp[ku]
                    if not row["image_url"] and patch_img.get(ku):
                        row["image_url"] = patch_img[ku]
            # add sheet-only SKUs (not in COSA)
            for _, r in df.iterrows():
                sku = clean(r.get(C_SKU, "")) if C_SKU else ""
                if not sku:
                    continue
                ku = sku.strip().upper()
                if ku not in seen:
                    seen.add(ku)
                    out.append({
                        "sku":         sku,
                        "sku_name":    cn_sku_label(sku),
                        "image_url":   clean(r.get(C_IMG2, "")) if C_IMG2 else "",
                        "mrp":         to_num(r.get(C_MRP,  0)) if C_MRP  else 0,
                        "cost":        to_num(r.get(C_COST, 0)) if C_COST else 0,
                        "final_qty":   0,
                        "net_revenue": 0,
                    })
        except Exception:
            pass

    _COSTS_CACHE["rows"] = out
    _COSTS_CACHE["ts"]   = time.time()
    return out

@app.route("/api/sku-costs")
def api_sku_costs():
    if session.get("role") != "admin":
        return jsonify({"error": "admin only"}), 403
    try:
        # force=true → cache saaf karo aur fresh data lo
        if request.args.get("force", "false").lower() == "true":
            _COSTS_CACHE["rows"] = None
        return jsonify({"rows": _build_sku_costs()})
    except Exception as e:
        return jsonify({"error": f"sku costs failed: {e}"}), 500

# ════════════════════════════════════════════════════════════════
#  ⚠️ AT-RISK CUSTOMERS — pehle regular the, ab 60+ din se nahi aaye
# ════════════════════════════════════════════════════════════════
_RISK_CACHE = {"items": {}}
_RISK_LOCK = threading.Lock()

def _build_at_risk(gap_days=60, min_orders=2, force=False):
    # Cache must be isolated by filter and by the exact source snapshot.
    # Earlier a single 10-minute cache made 90/120/180-day selections return
    # the previously calculated 60-day result, and it stayed stale after a
    # background sheet refresh.
    data_snapshot = get_data()
    comp = data_snapshot[0]
    order_activity = CACHE.get("orderdate_customer_activity") or {}
    source_version = float(
        CACHE.get("orderdate_customer_activity_ts")
        or CACHE.get("ts") or 0
    )
    today = now_ist().date()
    today_key = today.isoformat()
    cache_key = (source_version, today_key, int(gap_days), int(min_orders))
    if not force:
        with _RISK_LOCK:
            cached = _RISK_CACHE["items"].get(cache_key)
        if cached is not None:
            return cached

    # customer -> {dates:set, qty, rev, type}. Dedicated Order Date activity
    # is authoritative: Dispatch Date can lag a newly placed order and was the
    # reason active customers appeared as inactive. Main COSA is fallback only.
    cust = {}
    date_basis = "Order Date"
    if order_activity:
        for c in order_activity.values():
            name = str(c.get("customer") or "").strip()
            if not name:
                continue
            cust[name] = {
                "dates": set(c.get("dates") or []),
                "qty": float(c.get("qty") or 0),
                "rev": float(c.get("rev") or 0),
                "type": str(c.get("type") or ""),
            }
    else:
        date_basis = "Order Date fallback"
        for it in comp:
            for e in it.get("sales_entries", []):
                name = (e.get("cust") or "").strip()
                if not name or name.casefold() in ("website", "unknown"):
                    continue
                # Prefer Order Date whenever the main source supplies it; use
                # Dispatch Date only when no Order Date exists at all.
                d = e.get("order_date")
                if not d or d == "N/A":
                    d = e.get("date")
                if not d or d == "N/A":
                    continue
                qty = float(e.get("qty") or 0)
                rev = float(e.get("rev") or 0)
                if qty <= 0 and rev <= 0:
                    continue
                customer_key = re.sub(r"[^a-z0-9]", "", name.casefold())
                c = cust.setdefault(customer_key, {
                    "customer": name, "dates": set(), "qty": 0.0,
                    "rev": 0.0, "type": (e.get("type") or ""),
                })
                c["dates"].add(d)
                c["qty"] += max(0.0, qty)
                c["rev"] += max(0.0, rev)

    def _d(iso):
        try: return date(int(iso[0:4]), int(iso[5:7]), int(iso[8:10]))
        except Exception: return None

    rows = []
    for name_key, c in cust.items():
        name = c.get("customer") or name_key
        dts = sorted([x for x in (_d(s) for s in c["dates"]) if x])
        if len(dts) < min_orders:
            continue          # "regular" the tabhi count — kam se kam min_orders
        last = dts[-1]
        gap = (today - last).days
        if gap < gap_days:
            continue          # abhi bhi active
        # average gap between orders (regularity)
        if len(dts) >= 2:
            diffs = [(dts[i] - dts[i-1]).days for i in range(1, len(dts))]
            avg_gap = round(sum(diffs) / len(diffs))
        else:
            avg_gap = 0
        rows.append({
            "customer": name,
            "orders": len(dts),
            "last_order": last.strftime("%d-%b-%Y"),
            "days_since": gap,
            "avg_gap_days": avg_gap,
            "total_qty": int(round(c["qty"])),
            "total_rev": round(c["rev"], 2),
            "type": c["type"],
            "first_order": dts[0].strftime("%d-%b-%Y"),
        })
    # sabse zyada value waale + zyada overdue upar
    rows.sort(key=lambda x: (x["total_rev"], x["days_since"]), reverse=True)
    data = {
        "rows": rows,
        "count": len(rows),
        "total_value_at_risk": round(sum(r["total_rev"] for r in rows), 2),
        "gap_days": gap_days,
        "date_basis": date_basis,
        "generated_at": now_ist().isoformat(),
        "source_updated_at": (
            datetime.fromtimestamp(source_version, TZ).isoformat()
            if source_version else now_ist().isoformat()
        ),
    }
    with _RISK_LOCK:
        # Keep only the current source/day entries: at most four gap filters,
        # so old snapshots cannot accumulate in a long-running worker.
        _RISK_CACHE["items"] = {
            k: v for k, v in _RISK_CACHE["items"].items()
            if k[0] == source_version and k[1] == today_key
        }
        _RISK_CACHE["items"][cache_key] = data
    cust.clear()
    _gc.collect(); _malloc_trim()
    return data

@app.route("/api/at-risk")
def api_at_risk():
    if session.get("role") not in ("admin", "employee"):
        return jsonify({"error": "login required"}), 401
    try:
        gap = int(request.args.get("gap", "60") or 60)
    except Exception:
        gap = 60
    if gap not in (60, 90, 120, 180):
        gap = 60
    fresh = request.args.get("fresh", "0").strip().lower() in ("1", "true", "yes")
    try:
        payload = dict(_build_at_risk(gap, force=fresh))
        payload["checked_at"] = now_ist().isoformat()
        resp = jsonify(payload)
        resp.headers["Cache-Control"] = "no-store, no-cache, max-age=0"
        resp.headers["Pragma"] = "no-cache"
        return resp
    except Exception as e:
        return jsonify({"error": f"at-risk failed: {e}"}), 500

# ════════════════════════════════════════════════════════════════
#  📊 TAXON DETAILS — har taxon ka total net revenue + final qty
#  (date + type filter ke saath)
# ════════════════════════════════════════════════════════════════
def _build_taxon_details(d1="", d2="", types=None):
    comp = get_data()[0]
    types = [t for t in (types or []) if t]
    types_lc = set(t.lower() for t in types)
    agg = {}   # taxon -> {rev, qty, skus:set}
    for it in comp:
        tax = (it.get("taxon") or "Other") or "Other"
        for e in it.get("sales_entries", []):
            # type filter
            if types_lc and (str(e.get("type") or "").lower() not in types_lc):
                continue
            # date filter
            dt = e.get("date")
            if d1 or d2:
                if not dt or dt == "N/A":
                    continue
                if d1 and dt < d1:
                    continue
                if d2 and dt > d2:
                    continue
            a = agg.setdefault(tax, {"rev": 0.0, "qty": 0.0, "skus": set()})
            # entry["qty"] already Final Qty hai (total - return) — dobara subtract mat karo
            a["rev"] += float(e.get("rev") or 0)
            a["qty"] += float(e.get("qty") or 0)
            a["skus"].add(it.get("sku"))

    rows = []
    for tax, a in agg.items():
        rows.append({
            "taxon": tax,
            "net_revenue": round(a["rev"], 0),
            "final_qty": int(round(a["qty"])),
            "sku_count": len(a["skus"]),
        })
    rows.sort(key=lambda x: x["net_revenue"], reverse=True)
    total_rev = round(sum(r["net_revenue"] for r in rows), 0)
    total_qty = int(round(sum(r["final_qty"] for r in rows)))
    agg.clear()
    _gc.collect(); _malloc_trim()
    return {"rows": rows, "total_rev": total_rev, "total_qty": total_qty}

@app.route("/api/taxon-details")
def api_taxon_details():
    if session.get("role") not in ("admin", "employee"):
        return jsonify({"error": "login required"}), 401
    try:
        d1 = (request.args.get("d1", "") or "").strip()
        d2 = (request.args.get("d2", "") or "").strip()
        types = [t for t in (request.args.get("types", "") or "").split(",") if t.strip()]
        return jsonify(_build_taxon_details(d1, d2, types))
    except Exception as e:
        return jsonify({"error": f"taxon-details failed: {e}"}), 500

# ════════════════════════════════════════════════════════════════
#  💰 PAYMENTS — Ledger + Payment Terms se Due / Overdue (FIFO aging)
# ════════════════════════════════════════════════════════════════
PAY_LEDGER_URL = os.environ.get("PAY_LEDGER_URL",
    "https://docs.google.com/spreadsheets/d/e/2PACX-1vSsgrfjsrSCqWYZaiyHYKHcyQnca-gsA2asz01Fjsb28J1y04CyLZDpVazFcdnre5zO95VOgQBOugXQ/pub?gid=745089354&single=true&output=csv")
PAY_TERMS_URL = os.environ.get("PAY_TERMS_URL",
    "https://docs.google.com/spreadsheets/d/e/2PACX-1vSsgrfjsrSCqWYZaiyHYKHcyQnca-gsA2asz01Fjsb28J1y04CyLZDpVazFcdnre5zO95VOgQBOugXQ/pub?gid=1240216036&single=true&output=csv")
_PAY_CACHE = {"data": None, "ts": 0}
# Payments data changes throughout the day. Keep only a very short cache so
# the Payments + Planning API calls can share one build, while Refresh always
# pulls the latest published-sheet data immediately.
_PAY_CACHE_TTL = max(0, int(os.environ.get("PAY_CACHE_TTL_SECONDS", "30") or 30))
_PAY_RAW_LEDGER = {"data": None}
# Month-start pe overdue target freeze hota hai (poore month fixed). Key = "YYYY-MM".
# Ek baar set hone ke baad month bhar wahi rehta hai (target reference).
_PAY_OVERDUE_TARGET = {}   # {"2026-07": {"total": 1873072, "weeks": {"Week 1": ..., ...}}}
# Per-customer FROZEN target — Overdue(month end) Target ab tag/type filter ke
# hisaab se change hona chahiye, isliye company-wide total ke bajaye har
# customer ka apna target (month ki pehli baar jo week_due bana, wahi) freeze
# karke rakhte hain. Filtered rows me se jinke customers pass karte hain,
# unka target sum karke dikhaya jata hai — number filter ke hisaab se badalta
# hai par MONTH BHAR wahi fixed rehta hai (ledger baad me badle to bhi nahi).
_PAY_TARGET_FREEZE = {}   # {"2026-07": {"customer_norm_name": [[date, amt], ...]}}

def _norm_name(s):
    return re.sub(r"\s+", " ", str(s or "").strip()).upper()

def _build_payments():
    if (_PAY_CACHE_TTL > 0 and _PAY_CACHE["data"] is not None
            and (time.time() - _PAY_CACHE["ts"] < _PAY_CACHE_TTL)):
        return _PAY_CACHE["data"]

    # ---- Payment terms (Customer -> days, tag) ----
    term_map = {}; tag_map = {}
    # One canonical spelling per case-insensitive tag. The same helper is used
    # for both Terms and Full_Ledger_Main so Designer/DESIGNER/designer merge.
    _tag_canon = {}
    def _canon_pay_tag(v):
        raw = clean(v).strip()
        if not raw:
            return ""
        key = raw.lower()
        if key not in _tag_canon:
            _tag_canon[key] = raw
        return _tag_canon[key]
    try:
        terms_df = _fetch_csv_fresh(PAY_TERMS_URL)
        tcols = list(terms_df.columns)
        T_CUST = find_col(terms_df.columns, "Customer Name", "customer", "name") or (tcols[0] if tcols else None)
        T_TERM = find_col(terms_df.columns, "Payment Term", "payment terms", "term", "credit days", "credit period", "days", "payment term (days)", "term (days)")
        T_TAG  = find_col(terms_df.columns, "Tag", "type", "tag", "tag / type", "b2b/b2c", "customer type")
        tc = terms_df[T_CUST].tolist() if T_CUST else []
        tt = terms_df[T_TERM].tolist() if T_TERM else [0]*len(tc)
        tg = terms_df[T_TAG].tolist()  if T_TAG  else [""]*len(tc)
        # Tag/Type CASE-INSENSITIVE hai; canonical spelling shared helper se.
        for i in range(len(tc)):
            nm = _norm_name(tc[i])
            if not nm:
                continue
            term_map[nm] = to_int(tt[i])
            tag_map[nm] = _canon_pay_tag(tg[i])
    except Exception as e:
        print("payments terms fetch error:", str(e)[:200])

    # ---- Ledger ----
    led_df = _fetch_csv_fresh(PAY_LEDGER_URL)
    lcols = list(led_df.columns)
    L_DATE = find_col(led_df.columns, "Date", "date", "invoice date", "txn date") or (lcols[0] if lcols else None)
    L_CUST = find_col(led_df.columns, "Customer Name", "customer", "name", "party")
    L_INV  = find_col(led_df.columns, "Invoice No", "invoice", "inv no", "bill no", "voucher", "vch no", "vchno")
    L_DEB  = find_col(led_df.columns, "Debit", "sum of debit", "invoice amount", "debit (invoice)", "debit_invoice", "dr")
    L_CRED = find_col(led_df.columns, "Credit", "sum of credit", "payment", "credit (payment)", "credit_payment", "cr")
    L_BAL  = find_col(led_df.columns, "Balance", "sum of outstanding", "bal", "running balance")
    L_PART = find_col(led_df.columns, "Particulars", "particular", "narration")
    L_VTYPE = find_col(led_df.columns, "Vch Type", "voucher type", "vch_type")
    L_DUE  = find_col(led_df.columns, "Due Date", "due date", "duedate")
    L_CMP  = find_col(led_df.columns, "Company Details", "company")
    # Full_Ledger_Main ka Tag authoritative hai. Terms-sheet tag sirf fallback
    # rahega, kyunki latest credits/payment rows isi ledger me update hote hain.
    L_TAG  = find_col(led_df.columns, "Tag", "tag", "Customer Tag", "customer tag",
                      "Category", "category", "Type", "type")

    if not L_CUST:
        raise ValueError(f"'Customer Name' column not found in Ledger. Columns: {lcols[:12]}")

    by_cust = {}
    raw_by_cust = {}
    # FAST: column lists nikaal ke zip karo (.iterrows bahut dheema hota hai)
    custs = led_df[L_CUST].tolist() if L_CUST else []
    n = len(custs)
    dates = led_df[L_DATE].tolist() if L_DATE else [None]*n
    debs  = led_df[L_DEB].tolist()  if L_DEB  else [0]*n
    creds = led_df[L_CRED].tolist() if L_CRED else [0]*n
    invs  = led_df[L_INV].tolist()  if L_INV  else [""]*n
    bals  = led_df[L_BAL].tolist()  if L_BAL  else [None]*n
    parts = led_df[L_PART].tolist() if L_PART else [""]*n
    vtyps = led_df[L_VTYPE].tolist() if L_VTYPE else [""]*n
    dues  = led_df[L_DUE].tolist()  if L_DUE  else [None]*n
    cmps  = led_df[L_CMP].tolist()  if L_CMP  else [""]*n
    ltags = led_df[L_TAG].tolist() if L_TAG else [""]*n
    ledger_tag_map = {}
    _date_cache = {}
    def _fast_date(v):
        key = str(v)
        if key in _date_cache:
            return _date_cache[key]
        try:
            dd = parse_date_any(v)
        except Exception:
            dd = None
        if isinstance(dd, datetime):
            dd = dd.date()
        _date_cache[key] = dd
        return dd
    for i in range(n):
        nm = _norm_name(custs[i])
        if not nm:
            continue
        dt = _fast_date(dates[i])
        row_tag = _canon_pay_tag(ltags[i])
        if row_tag:
            # Last non-empty ledger tag wins; Full_Ledger_Main is the live source.
            ledger_tag_map[nm] = row_tag
        by_cust.setdefault(nm, []).append({
            "date": dt,
            "inv":  clean(invs[i]),
            "debit":  to_num(debs[i]),
            "credit": to_num(creds[i]),
            "tag": row_tag,
        })
        due_v = _fast_date(dues[i]) if dues[i] not in (None, "") else None
        raw_by_cust.setdefault(nm, []).append({
            "company": clean(cmps[i]),
            "date": dt.strftime("%d-%b-%y") if dt else clean(dates[i]),
            "particulars": clean(parts[i]) or ("To Opening Balance" if i == 0 else ""),
            "vch_type": clean(vtyps[i]),
            "vch_no": clean(invs[i]),
            "debit": to_num(debs[i]),
            "credit": to_num(creds[i]),
            "balance": to_num(bals[i]) if bals[i] is not None else None,
            "due_date": due_v.strftime("%d-%b-%y") if due_v else None,
            "_sort": dt or date(1900, 1, 1),
        })

    today = now_ist().date()
    # month-end of current month
    if today.month == 12:
        month_end = date(today.year, 12, 31)
    else:
        month_end = date(today.year, today.month + 1, 1) - timedelta(days=1)
    month_start_g = date(today.year, today.month, 1)

    # IMPORTANT: Planning Actual must include every current-month Credit row.
    # Earlier it was derived from outstanding-customer rows only, so customers
    # whose balance became zero were skipped and Designer Actual was understated.
    collected_month_by_customer = {}
    collected_month_by_tag = {}
    for i in range(n):
        credit_amt = to_num(creds[i])
        if credit_amt <= 0.009:
            continue
        cd = _fast_date(dates[i])
        if not cd or not (month_start_g <= cd <= month_end):
            continue
        nm = _norm_name(custs[i])
        if not nm:
            continue
        row_tag = (_canon_pay_tag(ltags[i]) or ledger_tag_map.get(nm)
                   or tag_map.get(nm) or "Unknown")
        collected_month_by_customer[nm] = collected_month_by_customer.get(nm, 0.0) + credit_amt
        collected_month_by_tag[row_tag] = collected_month_by_tag.get(row_tag, 0.0) + credit_amt

    AG_LABELS = ["0 Days", "0-30 Days", "31-60 Days", "61-90 Days", "91-180 Days", ">180 Days"]
    def _ag_bucket(days):
        if days <= 0:   return "0 Days"
        if days <= 30:  return "0-30 Days"
        if days <= 60:  return "31-60 Days"
        if days <= 90:  return "61-90 Days"
        if days <= 180: return "91-180 Days"
        return ">180 Days"

    rows = []
    aging = {k: 0.0 for k in AG_LABELS}
    tot_due = tot_over = tot_bal = 0.0
    # till month-end totals
    me_due = me_over = 0.0
    tags_set = set()
    all_due_pairs = []   # (due_date, remaining_amount) across ALL customers — for week-wise tracker
    carry_over_total = 0.0   # pichle mahine (ya usse pehle) se due/overdue balance, abhi tak unpaid

    for nm, entries in by_cust.items():
        term_days = term_map.get(nm, 0)
        tag = ledger_tag_map.get(nm) or tag_map.get(nm, "") or "Unknown"
        tags_set.add(tag)

        # FIFO: open invoices queue (oldest first), payments knock them off
        ents = sorted(entries, key=lambda e: (e["date"] or date(1900,1,1)))
        open_inv = []   # list of {date, amt_remaining}
        credit_pool = 0.0
        # All month credits were calculated before outstanding filtering, so a
        # fully-paid customer is still counted in Planning Actual.
        cust_collected_month = collected_month_by_customer.get(nm, 0.0)
        for e in ents:
            credit_pool += e["credit"]
            if e["debit"] > 0:
                open_inv.append({"date": e["date"], "amt": e["debit"]})
        # apply credit pool FIFO
        cp = credit_pool
        for inv in open_inv:
            if cp <= 0: break
            pay = min(cp, inv["amt"])
            inv["amt"] -= pay
            cp -= pay

        cust_due = cust_over = cust_bal = 0.0
        cust_due_me = cust_over_me = 0.0
        cust_carry_over = 0.0   # balance jo is month se PEHLE hi due/overdue tha aur abhi tak nahi mila
        cust_aging = {k: 0.0 for k in AG_LABELS}
        for inv in open_inv:
            rem = round(inv["amt"], 2)
            if rem <= 0.009:
                continue
            cust_bal += rem
            idt = inv["date"]
            due_date = (idt + timedelta(days=term_days)) if idt else None
            all_due_pairs.append((due_date, rem))
            if due_date and due_date < month_start_g:
                cust_carry_over += rem
            # as of TODAY
            if due_date and today > due_date:
                cust_over += rem
                od = (today - due_date).days
                bkt = _ag_bucket(od)
                aging[bkt] += rem
                cust_aging[bkt] += rem
            else:
                cust_due += rem
                aging["0 Days"] += rem
                cust_aging["0 Days"] += rem
            # as of MONTH-END
            # >= isliye: month ka aakhiri din (e.g. July 31) jis invoice
            # ki due date hai, wo EOD tak unpaid raha to overdue hi mana
            # jata hai — aur week_due bhi <= month_end use karta hai,
            # to dono totals match karte hain.
            if due_date and month_end >= due_date:
                cust_over_me += rem
            else:
                cust_due_me += rem

        if cust_bal <= 0.009:
            continue
        # is customer ke is-month due-date pairs (week summary filter-aware ke liye)
        _cust_week_due = []
        for inv in open_inv:
            rem2 = round(inv["amt"], 2)
            if rem2 <= 0.009:
                continue
            idt2 = inv["date"]
            dd2 = (idt2 + timedelta(days=term_days)) if idt2 else None
            if dd2 and month_start_g <= dd2 <= month_end:
                _cust_week_due.append([dd2.strftime("%Y-%m-%d"), rem2])
        # CARRY-OVER: jo balance pichle mahine (ya usse pehle) hi due/overdue ho chuka
        # tha aur customer ne abhi tak nahi diya — vo is month ke Week 1 me "Overdue
        # Becoming Due" ke roop me dikhna chahiye (amount = wahi jo Outstanding table
        # ke "Balance" column me hai). month_start_g ki date daal rahe hain taaki ye
        # week-wise bucketing (ws <= date <= we) me apne aap Week 1 me chala jaye.
        if cust_carry_over > 0.009:
            _cust_week_due.append([month_start_g.strftime("%Y-%m-%d"), round(cust_carry_over, 2)])
        # is customer ke is-month payment (credit) date-wise — week-wise "Payment
        # Received" ko FILTER-AWARE banane ke liye (pehle company-wide payment
        # frozen data use hota tha, filtered balance ke saath mix ho ke galat
        # "Balance Remaining" deta tha).
        _cust_week_paid = []
        for e in ents:
            if e["credit"] > 0 and e["date"] and month_start_g <= e["date"] <= month_end:
                _cust_week_paid.append([e["date"].strftime("%Y-%m-%d"), round(e["credit"], 2)])
        # is customer ne is month kitna pay kiya (collected this month)

        # FREEZE: is customer ka target (week_due jaisa tha) month ki pehli
        # baar yahan freeze ho jata hai — filter-aware AUR poore month fixed.
        _mkey_now = f"{today.year}-{today.month:02d}"
        if _mkey_now not in _PAY_TARGET_FREEZE:
            _PAY_TARGET_FREEZE[_mkey_now] = {}
        if nm not in _PAY_TARGET_FREEZE[_mkey_now]:
            _PAY_TARGET_FREEZE[_mkey_now][nm] = [list(x) for x in _cust_week_due]
        _cust_target_week_due = _PAY_TARGET_FREEZE[_mkey_now][nm]

        rows.append({
            "customer": nm.title(),
            "tag": tag,
            "term_days": term_days,
            "due": round(cust_due, 0),
            "overdue": round(cust_over, 0),
            "balance": round(cust_bal, 0),
            "due_me": round(cust_due_me, 0),
            "overdue_me": round(cust_over_me, 0),
            "aging": {k: round(v, 0) for k, v in cust_aging.items()},
            "collected_month": round(cust_collected_month, 0),
            "carry_over_overdue": round(cust_carry_over, 0),
            "week_due": _cust_week_due,
            "week_paid": _cust_week_paid,
            "target_week_due": _cust_target_week_due,
        })
        tot_due += cust_due; tot_over += cust_over; tot_bal += cust_bal
        me_due += cust_due_me; me_over += cust_over_me
        carry_over_total += cust_carry_over

    rows.sort(key=lambda x: x["balance"], reverse=True)

    # raw ledger lines sorted by date, per customer (for the printable customer ledger view)
    for nm in raw_by_cust:
        raw_by_cust[nm].sort(key=lambda e: e["_sort"])
        for e in raw_by_cust[nm]:
            e.pop("_sort", None)
    _PAY_RAW_LEDGER["data"] = raw_by_cust

    # ---- Ledger last updated (latest payment/credit entry date across the whole ledger) ----
    last_pay_date = None
    for i in range(n):
        if to_num(creds[i]) > 0:
            cd = _fast_date(dates[i])
            if cd and (last_pay_date is None or cd > last_pay_date):
                last_pay_date = cd

    # ---- PAYMENTS RECEIVED LOG — every credit/payment entry, latest first ----
    payments_log = []
    for i in range(n):
        credit_amt = to_num(creds[i])
        if credit_amt <= 0.009:
            continue
        nm = _norm_name(custs[i])
        if not nm:
            continue
        cd = _fast_date(dates[i])
        payments_log.append({
            "customer": nm.title(),
            "tag": (_canon_pay_tag(ltags[i]) or ledger_tag_map.get(nm)
                    or tag_map.get(nm, "") or "Unknown"),
            "date": cd.strftime("%d-%b-%y") if cd else clean(dates[i]),
            "date_sort": cd.strftime("%Y-%m-%d") if cd else "",
            "amount": round(credit_amt, 2),
            "vch_type": clean(vtyps[i]),
            "vch_no": clean(invs[i]),
            "particulars": clean(parts[i]),
        })
    payments_log.sort(key=lambda x: x["date_sort"], reverse=True)

    # ---- Week-wise overdue tracker for the CURRENT month (fixed buckets, whole month) ----
    month_start = date(today.year, today.month, 1)
    week_bounds = []
    ws = month_start
    while ws <= month_end:
        we = min(ws + timedelta(days=6), month_end)
        week_bounds.append((ws, we))
        ws = we + timedelta(days=1)

    week_overdue_amt = [0.0] * len(week_bounds)
    for due_date, rem in all_due_pairs:
        if not due_date or rem <= 0.009:
            continue
        if due_date < month_start or due_date > month_end:
            continue
        for wi, (ws_, we_) in enumerate(week_bounds):
            if ws_ <= due_date <= we_:
                week_overdue_amt[wi] += rem
                break
    # CARRY-OVER: pichle mahine (ya usse pehle) se jo due/overdue tha aur abhi tak
    # nahi mila, uska poora balance is month ke Week 1 me "Overdue Becoming Due"
    # me add hota hai (company-wide / unfiltered view ke liye — filtered view
    # frontend me row.week_due se hi recompute hota hai, jisme carry-over already
    # month_start ki date se Week 1 me daala gaya hai).
    if week_overdue_amt:
        week_overdue_amt[0] += carry_over_total

    week_payment_amt = [0.0] * len(week_bounds)
    for i in range(n):
        credit_amt = to_num(creds[i])
        if credit_amt <= 0:
            continue
        cd = _fast_date(dates[i])
        if not cd or cd < month_start or cd > month_end:
            continue
        for wi, (ws_, we_) in enumerate(week_bounds):
            if ws_ <= cd <= we_:
                week_payment_amt[wi] += credit_amt
                break

    week_overdue = []
    cum_pay = 0.0
    for wi, (ws_, we_) in enumerate(week_bounds):
        cum_pay += week_payment_amt[wi]
        bal_after = tot_bal - cum_pay
        week_overdue.append({
            "label": f"Week {wi + 1}",
            "range": f'{ws_.strftime("%d-%b")} to {we_.strftime("%d-%b")}',
            "overdue": round(week_overdue_amt[wi], 0),
            "payment": round(week_payment_amt[wi], 0),
            "balance": round(bal_after, 0),
        })

    # ---- FROZEN OVERDUE TARGET (month start pe freeze — poore month fixed) ----
    # Pehli baar jab is month ka data banta hai, tab week-wise "overdue becoming due"
    # ka snapshot le ke freeze kar dete hain. Fir month bhar wahi target dikhta hai.
    mkey = f"{today.year}-{today.month:02d}"
    if mkey not in _PAY_OVERDUE_TARGET:
        _PAY_OVERDUE_TARGET[mkey] = {
            "total": round(sum(week_overdue_amt), 0),
            "weeks": {f"Week {wi+1}": round(week_overdue_amt[wi], 0) for wi in range(len(week_bounds))},
        }
    frozen = _PAY_OVERDUE_TARGET[mkey]
    # week rows me frozen target add karo
    for wi, w in enumerate(week_overdue):
        w["target"] = frozen["weeks"].get(w["label"], 0)

    # week bounds (frontend filter-aware recompute ke liye)
    week_meta = [{"label": f"Week {wi+1}",
                  "start": ws_.strftime("%Y-%m-%d"),
                  "end": we_.strftime("%Y-%m-%d")} for wi, (ws_, we_) in enumerate(week_bounds)]

    # ---- TAG-WISE SUMMARY (due / overdue / collected this month / balance) ----
    # Due/overdue/balance naturally come from outstanding rows. Collected Month
    # comes from ALL live ledger Credit rows, including customers now at ₹0 balance.
    tag_summary = {}
    for r in rows:
        tg = r.get("tag") or "Unknown"
        s = tag_summary.setdefault(tg, {"tag": tg, "due": 0.0, "overdue": 0.0,
                                        "collected_month": 0.0, "balance": 0.0, "customers": 0})
        s["due"] += r["due"]; s["overdue"] += r["overdue"]
        s["balance"] += r["balance"]; s["customers"] += 1
    for tg, amt in collected_month_by_tag.items():
        s = tag_summary.setdefault(tg, {"tag": tg, "due": 0.0, "overdue": 0.0,
                                        "collected_month": 0.0, "balance": 0.0, "customers": 0})
        s["collected_month"] = amt
        tags_set.add(tg)
    tag_summary_list = sorted(tag_summary.values(), key=lambda x: x["balance"], reverse=True)
    for s in tag_summary_list:
        for k in ("due", "overdue", "collected_month", "balance"):
            s[k] = round(s[k], 0)

    data = {
        "rows": rows,
        "today": today.strftime("%d-%b-%y"),
        "month_end": month_end.strftime("%d-%b-%y"),
        "month_label": today.strftime("%b-%y"),
        "ledger_last_updated": last_pay_date.strftime("%d-%b-%y") if last_pay_date else None,
        "totals": {
            "due": round(tot_due, 0), "overdue": round(tot_over, 0), "balance": round(tot_bal, 0),
            "due_me": round(me_due, 0), "overdue_me": round(me_over, 0),
        },
        "aging": [{"bucket": k, "amount": round(aging[k], 0)} for k in AG_LABELS],
        "aging_total": round(sum(aging.values()), 0),
        "week_overdue": week_overdue,
        "week_meta": week_meta,
        "overdue_target_total": frozen["total"],
        "carry_over_overdue_total": round(carry_over_total, 0),
        "tag_summary": tag_summary_list,
        "collected_by_tag": {k: round(v, 0) for k, v in collected_month_by_tag.items()},
        "tags": sorted([t for t in tags_set if t]),
        "payments_log": payments_log,
    }
    _PAY_CACHE["data"] = data
    _PAY_CACHE["ts"] = time.time()
    return data

# ════════════════════════════════════════════════════════════════
#  📋 PAYMENTS PLANNING — published Planning sheet is the source of truth
#  for Channel, Inward Projection, Actual, Pending, % Ach, Actual STR and
#  Required STR. The loader discovers the real header below the title rows.
# ════════════════════════════════════════════════════════════════
PAY_PLANNING_URL = (
    "https://docs.google.com/spreadsheets/d/e/2PACX-1vSmZIJi58MyrgdxhjR2fvtxBwDuCJgPBjSK6puZ-w2qk2fL-fhytUAfExU2v4C-QcwKnj8aA1H_PAx7/"
    "pub?gid=0&single=true&output=csv"
)

_PLAN_CACHE = {"data": None, "ts": 0}
_PLAN_CACHE_TTL = max(0, int(os.environ.get("PAY_PLAN_CACHE_TTL_SECONDS", "30") or 30))

def _plan_norm(v):
    return re.sub(r"[^a-z0-9]+", "", str(v or "").strip().lower())

def _plan_col_index(header, *aliases):
    normalized = [_plan_norm(v) for v in header]
    wanted = [_plan_norm(v) for v in aliases]
    for key in wanted:
        if key in normalized:
            return normalized.index(key)
    for key in wanted:
        for i, cell in enumerate(normalized):
            if key and cell and (key in cell or cell in key):
                return i
    return None

def _plan_cell(row, index):
    return row[index] if index is not None and index < len(row) else ""

def _plan_percent(v, fallback=None):
    raw = clean(v)
    if not raw:
        return fallback
    num = to_num(raw)
    if "%" not in raw and 0 < abs(num) <= 1:
        num *= 100
    return round(num, 1)

def _build_payments_planning():
    if (_PLAN_CACHE_TTL > 0 and _PLAN_CACHE["data"] is not None
            and (time.time() - _PLAN_CACHE["ts"] < _PLAN_CACHE_TTL)):
        return _PLAN_CACHE["data"]

    today = now_ist().date()
    rows = []
    source_totals = None
    period_label = ""
    updated_till = ""
    plan_err = None
    try:
        pdf = _fetch_csv_fresh(PAY_PLANNING_URL)
        raw_rows = [[clean(v) for v in row] for row in pdf.itertuples(index=False, name=None)]
        header_at = None
        for i, row in enumerate(raw_rows):
            keys = {_plan_norm(v) for v in row if clean(v)}
            if "channel" in keys and "inwardprojection" in keys and "actual" in keys:
                header_at = i
                break
        if header_at is None:
            raise ValueError("Channel/Inward projection/Actual header row nahi mila")

        for row in raw_rows[:header_at]:
            for value in row:
                text = clean(value)
                if not text:
                    continue
                match = re.search(r"updated\s+till\s*[-:=]?\s*(.+)$", text, re.I)
                if match:
                    updated_till = clean(match.group(1))
                if re.match(r"^from\s+", text, re.I):
                    period_label = text

        header = raw_rows[header_at]
        c_channel = _plan_col_index(header, "Channel", "Category", "Type")
        c_inward = _plan_col_index(header, "Inward projection", "Projection", "Inward")
        c_actual = _plan_col_index(header, "Actual")
        c_pending = _plan_col_index(header, "Pending")
        c_pct = _plan_col_index(header, "% Ach", "Ach", "Achievement")
        c_actual_str = _plan_col_index(header, "Actual STR")
        c_required_str = _plan_col_index(header, "Required STR")
        required = [c_channel, c_inward, c_actual, c_pending, c_pct, c_actual_str, c_required_str]
        if any(index is None for index in required):
            raise ValueError("Planning table ke required columns complete nahi mile")

        for row in raw_rows[header_at + 1:]:
            category = clean(_plan_cell(row, c_channel))
            if not category:
                continue
            inward = round(to_num(_plan_cell(row, c_inward)), 0)
            actual = round(to_num(_plan_cell(row, c_actual)), 0)
            pending_raw = clean(_plan_cell(row, c_pending))
            pending = round(to_num(pending_raw), 0) if pending_raw else round(inward - actual, 0)
            pct = _plan_percent(
                _plan_cell(row, c_pct),
                round(actual / inward * 100, 1) if inward else None,
            )
            actual_str = round(to_num(_plan_cell(row, c_actual_str)), 0)
            required_str = round(to_num(_plan_cell(row, c_required_str)), 0)
            parsed = {
                "category": category,
                "inward_projection": inward,
                "actual": actual,
                "pending": pending,
                "pct_achievement": pct,
                "actual_str": actual_str,
                "required_str": required_str,
            }
            if _plan_norm(category) in ("total", "grandtotal"):
                source_totals = {k: v for k, v in parsed.items() if k != "category"}
                break
            rows.append(parsed)
        if not rows:
            raise ValueError("Planning table me channel rows nahi mile")
    except Exception as e:
        plan_err = f"Planning sheet fetch/parse nahi ho payi: {str(e)[:200]}"

    if source_totals is None:
        total_inward = sum(r["inward_projection"] for r in rows)
        total_actual = sum(r["actual"] for r in rows)
        source_totals = {
            "inward_projection": round(total_inward, 0),
            "actual": round(total_actual, 0),
            "pending": round(sum(r["pending"] for r in rows), 0),
            "pct_achievement": round(total_actual / total_inward * 100, 1) if total_inward else None,
            "actual_str": round(sum(r["actual_str"] for r in rows), 0),
            "required_str": round(sum(r["required_str"] for r in rows), 0),
        }

    data = {
        "rows": rows,
        "totals": source_totals,
        "month_label": period_label or today.strftime("%b-%y"),
        "today": updated_till or today.strftime("%d-%b-%y"),
        "error": plan_err,
    }
    _PLAN_CACHE["data"] = data
    _PLAN_CACHE["ts"] = time.time()
    return data

@app.route("/api/payments/planning")
def api_payments_planning():
    if session.get("role") not in ("admin", "employee"):
        return jsonify({"error": "login required"}), 401
    try:
        if request.args.get("force", "").lower() == "true":
            _PLAN_CACHE["data"] = None
            _PAY_CACHE["data"] = None
        return jsonify(_build_payments_planning())
    except Exception as e:
        return jsonify({"error": f"planning build failed: {e}"}), 500

@app.route("/api/payments")
def api_payments():
    if session.get("role") not in ("admin", "employee"):
        return jsonify({"error": "login required"}), 401
    try:
        if request.args.get("force", "").lower() == "true":
            _PAY_CACHE["data"] = None
            _PLAN_CACHE["data"] = None
        return jsonify(_build_payments())
    except Exception as e:
        import traceback
        tb = traceback.format_exc()
        print("PAYMENTS ERROR:\n", tb)
        return jsonify({"error": f"payments failed: {e}", "where": tb.splitlines()[-3:] if tb else ""}), 500

@app.route("/api/payments/ledger")
def api_payments_ledger():
    if session.get("role") not in ("admin", "employee"):
        return jsonify({"error": "login required"}), 401
    name = request.args.get("customer", "")
    if not name:
        return jsonify({"error": "customer required"}), 400
    try:
        _build_payments()  # ensure cache populated
        raw = _PAY_RAW_LEDGER.get("data") or {}
        entries = raw.get(_norm_name(name)) or []
        tot_debit = round(sum(e.get("debit") or 0 for e in entries), 2)
        tot_credit = round(sum(e.get("credit") or 0 for e in entries), 2)
        closing_bal = entries[-1]["balance"] if entries and entries[-1].get("balance") is not None else round(tot_debit - tot_credit, 2)
        period = ""
        if entries:
            d0 = entries[0].get("date") or ""
            d1 = entries[-1].get("date") or ""
            if d0 or d1:
                period = f"{d0} to {d1}"
        return jsonify({
            "customer": name,
            "period": period,
            "entries": entries,
            "totals": {"debit": tot_debit, "credit": tot_credit, "balance": closing_bal},
        })
    except Exception as e:
        import traceback
        print("PAYMENTS LEDGER ERROR:\n", traceback.format_exc())
        return jsonify({"error": f"ledger failed: {e}"}), 500


# ════════════════════════════════════════════════════════════════
#  🆘 HELP QUERIES  (employee bhejta hai → admin home par 24h dikhta hai)
# ════════════════════════════════════════════════════════════════
_HELP_QUERIES = []   # [{id, text, user, ts}]
_HELP_LOCK = threading.Lock()

def _purge_help():
    cutoff = time.time() - 24*3600
    with _HELP_LOCK:
        _HELP_QUERIES[:] = [q for q in _HELP_QUERIES if q["ts"] >= cutoff]

@app.route("/api/help", methods=["POST"])
def api_help_submit():
    # Employee (ya admin) apni problem bhej sakta hai.
    role = session.get("role")
    if role not in ("employee", "admin"):
        return jsonify({"ok": False, "error": "login required"}), 401
    body = request.get_json(silent=True) or {}
    text = (body.get("text") or "").strip()
    if not text:
        return jsonify({"ok": False, "error": "empty"}), 400
    text = text[:1000]
    with _HELP_LOCK:
        _HELP_QUERIES.append({
            "id": uuid.uuid4().hex[:10],
            "text": text,
            "user": session.get("user") or role,
            "ts": time.time(),
        })
        # purana 24h+ saaf + max 200 rakho
        cutoff = time.time() - 24*3600
        _HELP_QUERIES[:] = [q for q in _HELP_QUERIES if q["ts"] >= cutoff][-200:]
    return jsonify({"ok": True})

@app.route("/api/help-queries")
def api_help_list():
    # Sirf admin — home page par dikhane ke liye. 24h+ purane apne aap gayab.
    if session.get("role") != "admin":
        return jsonify({"queries": []})
    _purge_help()
    now = time.time()
    with _HELP_LOCK:
        out = [{
            "id": q["id"], "text": q["text"], "user": q["user"],
            "ago_min": int((now - q["ts"]) / 60),
        } for q in sorted(_HELP_QUERIES, key=lambda x: x["ts"], reverse=True)]
    return jsonify({"queries": out})

@app.route("/api/help-dismiss", methods=["POST"])
def api_help_dismiss():
    # Admin ek query ko manually hata sakta hai.
    if session.get("role") != "admin":
        return jsonify({"ok": False}), 403
    qid = (request.get_json(silent=True) or {}).get("id", "")
    with _HELP_LOCK:
        _HELP_QUERIES[:] = [q for q in _HELP_QUERIES if q["id"] != qid]
    return jsonify({"ok": True})

